def _regular_entry(path: Path, *, root: Path = ROOT) -> dict[str, Any]:
    relative = path.relative_to(root).as_posix() if path.is_relative_to(root) else str(path)
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        before = os.fstat(fd)
        digest = hashlib.sha256()
        while True:
            chunk = os.read(fd, 8 << 20)
            if not chunk:
                break
            digest.update(chunk)
        after = os.fstat(fd)
    finally:
        os.close(fd)
    path_st = path.lstat()
    identity = (before.st_dev, before.st_ino, before.st_mode, before.st_uid,
                before.st_nlink, before.st_size)
    if (identity != (after.st_dev, after.st_ino, after.st_mode, after.st_uid,
                     after.st_nlink, after.st_size)
            or (before.st_dev, before.st_ino) != (path_st.st_dev, path_st.st_ino)
            or not stat.S_ISREG(before.st_mode) or stat.S_ISLNK(path_st.st_mode)
            or before.st_uid != os.getuid() or before.st_nlink != 1):
        raise ValueError(f"candidate/closure file identity drift: {path}")
    return {
        "path": relative, "type": "regular", "mode": stat.S_IMODE(before.st_mode),
        "uid": before.st_uid, "nlink": before.st_nlink, "size": before.st_size,
        "sha256": digest.hexdigest(), "verification_action": "content_rehash",
    }


def _path_present(path: Path) -> bool:
    return path.exists() or path.is_symlink()


def _write_all(fd: int, payload: bytes) -> None:
    """Write an exact payload or fail; os.write is permitted to short-write."""
    offset = 0
    while offset < len(payload):
        written = os.write(fd, payload[offset:])
        if written <= 0:
            raise OSError("zero-length write before payload completion")
        offset += written


def _regular_bytes(path: Path, *, mode: int, owner: int | None = None) -> bytes:
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    try:
        before = os.fstat(fd)
        chunks = []
        while True:
            chunk = os.read(fd, 8 << 20)
            if not chunk:
                break
            chunks.append(chunk)
        after = os.fstat(fd)
    finally:
        os.close(fd)
    path_st = path.lstat()
    expected_owner = os.getuid() if owner is None else owner
    if ((before.st_dev, before.st_ino, before.st_mode, before.st_uid, before.st_nlink,
         before.st_size, before.st_mtime_ns, before.st_ctime_ns) !=
        (after.st_dev, after.st_ino, after.st_mode, after.st_uid, after.st_nlink,
         after.st_size, after.st_mtime_ns, after.st_ctime_ns)
            or (before.st_dev, before.st_ino) != (path_st.st_dev, path_st.st_ino)
            or not stat.S_ISREG(before.st_mode) or stat.S_ISLNK(path_st.st_mode)
            or stat.S_IMODE(before.st_mode) != mode or before.st_uid != expected_owner
            or before.st_nlink != 1):
        raise ValueError(f"regular-file identity/mode/ownership drift: {path}")
    return b"".join(chunks)


def _read_root_json(root: Path, relative: str) -> Any:
    return base.strict_json_loads((root / relative).read_text(encoding="utf-8"))


def generic_config_projection(config: Mapping[str, Any]) -> dict[str, Any]:
    """Return the exact config schema accepted by the reviewed generic builders."""
    expected = set(GENERIC_CONFIG_KEYS) | set(SUCCESSOR_CONFIG_KEYS)
    if set(config) != expected:
        raise ValueError(f"successor config key mismatch: {sorted(set(config) ^ expected)}")
    return {key: config[key] for key in GENERIC_CONFIG_KEYS}


def generic_replay_bundle(bundle: Mapping[str, Any], generic_config_sha256: str) -> dict[str, Any]:
    expected = {"schema_version", "protocol_config_sha256", "replay_registry_sha256",
                "source_role", "source_revision", "partition", "observations"}
    if set(bundle) != expected:
        raise ValueError(f"successor replay-bundle key mismatch: {sorted(set(bundle) ^ expected)}")
    base.validate_sha256(generic_config_sha256, "generic protocol config SHA-256")
    return {**dict(bundle), "protocol_config_sha256": generic_config_sha256}


def _validate_m2_semantics(*, root: Path = ROOT) -> dict[str, Any]:
    prefix = "data/msae_independent_measurement_v3"
    task = _read_root_json(root, f"{prefix}/task_manifest.json")
    support = _read_root_json(root, f"{prefix}/support.json")
    templates = _read_root_json(root, f"{prefix}/prefix_templates.json")
    maps = _read_root_json(root, f"{prefix}/maps.json")
    matrix = _read_root_json(root, f"{prefix}/finite_pass_matrix.json")
    imports = _read_root_json(root, f"{prefix}/protocol_imports.json")
    if (task.get("schema_version") != "msae_v3_task_manifest_v1"
            or task.get("protocol_id") != PROTOCOL
            or task.get("roles") != list(base.ROLES) or task.get("tasks") != list(base.TASKS)
            or task.get("label_rows") != 1491748):
        raise ValueError("M2 task-manifest semantics drift")
    audit = task.get("amalgum_legacy_upos_repair", {}).get("audit", {})
    denominators = {name: [row.get("population_token_count"), row.get("correction_token_count")]
                    for name, row in audit.get("ledgers", {}).items()}
    if denominators != {"raw_selected": [290192, 36], "tokenizable": [286938, 20],
                        "retained_after_cap": [89600, 11]}:
        raise ValueError("M2 correction-ledger semantics drift")
    if (support.get("schema_version") != "msae_v3_support_v1"
            or support.get("status") != "eligible" or set(support.get("roles", {})) != set(base.ROLES)):
        raise ValueError("M2 support semantics drift")
    if any(set(support["roles"][role]) != set(base.TASKS)
           or any(support["roles"][role][task_name].get("status") != "eligible"
                  for task_name in base.TASKS) for role in base.ROLES):
        raise ValueError("M2 role/task support is incomplete")
    template_rows = templates.get("templates")
    if (templates.get("schema_version") != "msae_v3_prefix_templates_v1"
            or not isinstance(template_rows, list) or len(template_rows) != 4
            or [row.get("literal") for row in template_rows] != list(base.PREFIXES)
            or len({row.get("length") for row in template_rows}) != 4):
        raise ValueError("M2 prefix-template semantics drift")
    entries = maps.get("map_entries")
    if (maps.get("schema_version") != "msae_v3_bootstrap_maps_v1"
            or maps.get("draws_per_role_task") != 500 or not isinstance(entries, list)
            or len(entries) != len(base.ROLES) * len(base.TASKS) * 500):
        raise ValueError("M2 map registry dimensions drift")
    keys = {(row.get("role"), row.get("task"), row.get("draw")) for row in entries}
    expected_keys = {(role, task_name, draw) for role in base.ROLES
                     for task_name in base.TASKS for draw in range(500)}
    if keys != expected_keys or len(keys) != len(entries):
        raise ValueError("M2 map registry keys are incomplete or duplicated")
    finite = collections.Counter((row["role"], row["task"]) for row in entries
                                 if row.get("finite") is True and row.get("reasons") == [])
    if any(row.get("finite") not in {True, False}
           or base.HEX_RE.fullmatch(str(row.get("map_sha256"))) is None for row in entries):
        raise ValueError("M2 map entry type/digest drift")
    expected_matrix = {role: {task_name: finite[(role, task_name)] for task_name in base.TASKS}
                       for role in base.ROLES}
    if (matrix.get("schema_version") != "msae_v3_finite_pass_matrix_v1"
            or matrix.get("status") != "eligible" or matrix.get("minimum_finite_draws") != 490
            or matrix.get("finite_draw_counts") != expected_matrix
            or any(count != 500 for values in expected_matrix.values() for count in values.values())
            or matrix.get("map_payload_sha256") != base.sha_file(root / prefix / "maps.json")):
        raise ValueError("M2 finite-pass matrix does not close over maps")
    if imports.get("schema_version") != "msae_v3_protocol_imports_v1":
        raise ValueError("M2 protocol-import semantics drift")
    return {"label_rows": 1491748, "role_task_cells": 68, "map_entries": len(entries),
            "finite_draws_per_cell": 500, "support_status": "eligible",
            "finite_pass_status": "eligible", "correction_denominators": denominators}


@contextlib.contextmanager
def _later_data_projection() -> Iterable[None]:
    original = base._phase_data_names
    def names(phase: str) -> set[str]:
        result = original(phase)
        if phase in {"M1", "M2"}:
            result |= {name for name in base.V3_DATA_PHASE_FILES["M4"]
                       if (V3_DATA / name).exists()}
        return result
    base._phase_data_names = names
    try:
        yield
    finally:
        base._phase_data_names = original


def _m2_completion_payload() -> dict[str, Any]:
    with _later_data_projection():
        continuation.verify_m1_completion(M1_REVIEWED_COMPLETION_SHA256, allow_m2_recovery=True)
        base.verify_baseline_projection("M2")
    entries = [_regular_entry(V3_DATA / name) for name in base.V3_DATA_PHASE_FILES["M2"]]
    return {"schema_version": "msae_v3_m2_completion_manifest_v1", "protocol_id": PROTOCOL,
            "reviewed_m1_completion_sha256": M1_REVIEWED_COMPLETION_SHA256,
            "entries": entries, "entry_count": len(entries),
            "entries_sha256": base.sha_bytes(base.canonical_bytes(entries)),
            "success_semantics": _validate_m2_semantics(),
            "status": "m2_support_and_maps_eligible_ready_for_independent_review_pin"}


def build_m2_completion() -> dict[str, Any]:
    raise RuntimeError("gen3 cannot construct or replace the immutable M2 completion")


def verify_m2_completion(reviewed_sha256: str) -> dict[str, Any]:
    # Verifier ownership remains with the exact immutable gen2 runtime that
    # created and reviewed this completion. Gen3 may only consume its result.
    return predecessor_runtime.verify_m2_completion(reviewed_sha256)


def checkpoint_registry(*, root: Path = ROOT) -> list[dict[str, Any]]:
    specs = [
        ("g4", 42, "inc1e2", "final_step249244_tok1000000016.pt", "replicate"),
        ("g5", 43, "inc1e2", "final_step249244_tok1000000016.pt", "replicate"),
        ("g6", 44, "inc1e2", "final_step249675_tok1000000042.pt", "replicate"),
        ("g7", 42, "inc0", "final_step249244_tok1000000016.pt", "matched_negative_control"),
    ]
    rows: list[dict[str, Any]] = []
    for checkpoint_id, seed, suffix, filename, role in specs:
        run_id = f"k2_wave2_fast_{checkpoint_id}_L3_s{seed}_{suffix}"
        relative_root = (Path("pilot_runs/20260601_132158_k2_msae_wave2_fastdata_stream/outputs") /
                         run_id)
        checkpoint = root / relative_root / "checkpoints" / filename
        summary = root / relative_root / "train_summary.json"
        metrics = root / relative_root / "train_metrics.jsonl"
        payload = base.strict_json_loads(summary.read_text(encoding="utf-8"))
        if payload.get("seed") != seed or payload.get("layer_index") != 3:
            raise ValueError(f"checkpoint summary mismatch: {checkpoint_id}")
        rows.append({
            "checkpoint_id": checkpoint_id, "role": role, "seed": seed,
            "training_run_id": run_id,
            "checkpoint_path": (relative_root / "checkpoints" / filename).as_posix(),
            "checkpoint_size": checkpoint.stat().st_size,
            "checkpoint_sha256": base.sha_file(checkpoint),
            "summary_path": (relative_root / "train_summary.json").as_posix(),
            "summary_sha256": base.sha_file(summary),
            "metrics_path": (relative_root / "train_metrics.jsonl").as_posix(),
            "metrics_sha256": base.sha_file(metrics),
            "tokens_seen": payload["tokens_seen"], "lambda_inc": payload["lambda_inc"],
            "training_git_state": payload["git_commit_hash"],
        })
    if ([row["checkpoint_id"] for row in rows] != ["g4", "g5", "g6", "g7"]
            or [row["role"] for row in rows] != ["replicate", "replicate", "replicate", "matched_negative_control"]
            or len({row["seed"] for row in rows[:3]}) != 3
            or len({row["checkpoint_sha256"] for row in rows[:3]}) != 3
            or any(base.HEX_RE.fullmatch(row["checkpoint_sha256"]) is None for row in rows)):
        raise ValueError("checkpoint lineage registry does not meet the frozen design")
    if rows[3]["seed"] != rows[0]["seed"] or rows[3]["lambda_inc"] == rows[0]["lambda_inc"]:
        raise ValueError("g7 is not the frozen matched negative control")
    return rows


def _expected_endpoint_keys() -> set[tuple[Any, ...]]:
    """Independently enumerate the frozen endpoint product.

    This deliberately returns typed tuples rather than endpoint IDs so a bug in
    string formatting cannot make construction and validation agree.
    """
    keys: set[tuple[Any, ...]] = set()
    localization_metrics = ("recovery", "leakage", "selectivity")
    for role, checkpoints, components in (
        ("C1", ("raw",), ("raw_full", "simple_family_projection",
                          "simple_family_complement", "simple_family_residual")),
        ("C2", ("g4", "g5", "g6", "g7"),
         ("assigned", "nonassigned", "joint", "complement", "residual")),
    ):
        for checkpoint in checkpoints:
            for family, tasks in FAMILIES.items():
                for task_name in tasks:
                    for component in components:
                        for metric in localization_metrics:
                            keys.add(("localization", role, checkpoint, family,
                                      task_name, component, metric, 3))
    for family, tasks in FAMILIES.items():
        for task_name in tasks:
            for metric in localization_metrics:
                keys.add(("functional_reproducibility", "C2", ("g4", "g5", "g6"),
                          "g7_descriptive_only", family, "task", task_name, metric))
        for metric in localization_metrics:
            keys.add(("functional_reproducibility", "C2", ("g4", "g5", "g6"),
                      "g7_descriptive_only", family, "family_summary", None, metric))
    for role, checkpoints, components in (
        ("C1", ("raw",), ("raw_full", "simple_family_projection",
                            "simple_family_complement", "simple_family_residual")),
        ("C2", ("g4", "g5", "g6", "g7"),
         ("assigned", "nonassigned", "joint", "complement", "residual")),
    ):
        for checkpoint in checkpoints:
            for component in components:
                for task_name in TIER2:
                    for metric in ("recovery", "retention", "leakage"):
                        keys.add(("collateral", role, checkpoint, component, task_name, metric))
    for checkpoint in ("g4", "g5", "g6", "g7"):
        for transform in TRANSFORMS:
            for control in CONTROLS:
                keys.add(("counterfactual", "C2", checkpoint, transform, control))
    for role in base.ROLES:
        for baseline in BASELINES:
            keys.add(("baseline", role, baseline))
    return keys


def _endpoint_key(row: Mapping[str, Any]) -> tuple[Any, ...]:
    category = row.get("category")
    if category == "localization":
        return (category, row.get("role"), row.get("checkpoint"), row.get("family"),
                row.get("task"), row.get("component"), row.get("metric"), row.get("layer"))
    if category == "functional_reproducibility":
        checkpoints = row.get("checkpoints")
        return (category, row.get("role"), tuple(checkpoints) if isinstance(checkpoints, list) else None,
                row.get("control"), row.get("family"), row.get("summary_level"),
                row.get("task"), row.get("metric"))
    if category == "collateral":
        return (category, row.get("role"), row.get("checkpoint"), row.get("component"),
                row.get("task"), row.get("metric"))
    if category == "counterfactual":
        return (category, row.get("role"), row.get("checkpoint"), row.get("transform"), row.get("control"))
    if category == "baseline":
        return (category, row.get("role"), row.get("baseline"))
    raise ValueError(f"unknown endpoint category: {category!r}")


def validate_endpoint_registry(value: Mapping[str, Any]) -> dict[str, Any]:
    entries = value.get("entries")
    if not isinstance(entries, list):
        raise ValueError("endpoint entries are not an array")
    keys = [_endpoint_key(row) for row in entries]
    expected = _expected_endpoint_keys()
    if len(keys) != len(set(keys)) or set(keys) != expected:
        missing = expected - set(keys)
        extra = set(keys) - expected
        raise ValueError(f"endpoint product mismatch: missing={len(missing)} extra={len(extra)}")
    ids = [row.get("endpoint_id") for row in entries]
    if any(not isinstance(item, str) or not item for item in ids) or len(ids) != len(set(ids)):
        raise ValueError("endpoint IDs are missing or duplicated")
    def expected_id(key: tuple[Any, ...]) -> str:
        category = key[0]
        if category == "localization":
            _, role, checkpoint, family, task, component, metric, layer = key
            return f"{role}.{checkpoint}.{family}.{task}.{component}.{metric}.L{layer}"
        if category == "functional_reproducibility":
            _, _, checkpoints, _, family, level, task, metric = key
            unit = task if level == "task" else "family_summary"
            return f"{'_'.join(checkpoints)}.{family}.{unit}.{metric}.spread"
        if category == "collateral":
            _, role, checkpoint, component, task, metric = key
            return f"{role}.{checkpoint}.{component}.{task}.{metric}.L3"
        if category == "counterfactual":
            _, role, checkpoint, transform, control = key
            return f"{role}.{checkpoint}.{transform}.{control}.L3"
        _, role, baseline = key
        return f"{role}.{baseline}.registered"
    if any(row["endpoint_id"] != expected_id(key) for row, key in zip(entries, keys)):
        raise ValueError("endpoint ID is not the canonical typed-key encoding")
    for row in entries:
        required = (["maximum_spread", "uncertainty", "status"]
                    if row["category"] == "functional_reproducibility"
                    else ["estimate", "uncertainty", "status"]
                    if row["category"] == "collateral" else None)
        if required is not None and row.get("required_output_fields") != required:
            raise ValueError("endpoint required-output schema mismatch")
    counts = collections.Counter(row["category"] for row in entries)
    expected_counts = collections.Counter(key[0] for key in expected)
    if (value.get("schema_version") != "msae_v3_endpoint_registry_v2"
            or value.get("protocol_id") != PROTOCOL
            or value.get("endpoint_count") != len(expected)
            or value.get("category_counts") != dict(expected_counts)
            or value.get("endpoint_id_set_sha256") !=
               base.sha_bytes(base.canonical_bytes(sorted(ids)))):
        raise ValueError("endpoint registry summary mismatch")
    if (value.get("families") != {key: list(rows) for key, rows in FAMILIES.items()}
            or value.get("tier2_tasks") != list(TIER2)
            or value.get("counterfactual_transforms") != list(TRANSFORMS)
            or value.get("counterfactual_controls") != list(CONTROLS)
            or value.get("baselines") != list(BASELINES)
            or value.get("g7_interpretation") != "matched_negative_control_not_replicate"
            or value.get("C1_scope") != "raw_simple_G1_operands_only"
            or value.get("C2_scope") != "G2_and_descriptive_control"):
        raise ValueError("endpoint registry metadata mismatch")
    return dict(value)


def endpoint_registry() -> dict[str, Any]:
    entries: list[dict[str, Any]] = []
    for role in ("C1", "C2"):
        checkpoints = ("raw",) if role == "C1" else ("g4", "g5", "g6", "g7")
        components = ("raw_full", "simple_family_projection", "simple_family_complement", "simple_family_residual") if role == "C1" else ("assigned", "nonassigned", "joint", "complement", "residual")
        for checkpoint in checkpoints:
            for family, tasks in FAMILIES.items():
                for task_name in tasks:
                    for component in components:
                        for metric in ("recovery", "leakage", "selectivity"):
                            entries.append({"category": "localization", "role": role,
                                            "checkpoint": checkpoint, "family": family,
                                            "task": task_name, "component": component,
                                            "metric": metric, "layer": 3,
                                            "endpoint_id": f"{role}.{checkpoint}.{family}.{task_name}.{component}.{metric}.L3"})
    for family, tasks in FAMILIES.items():
        for task_name in tasks:
            for metric in ("recovery", "leakage", "selectivity"):
                entries.append({"category": "functional_reproducibility", "role": "C2",
                                "checkpoints": ["g4", "g5", "g6"], "control": "g7_descriptive_only",
                                "family": family, "summary_level": "task", "task": task_name,
                                "metric": metric,
                                "required_output_fields": ["maximum_spread", "uncertainty", "status"],
                                "endpoint_id": f"g4_g5_g6.{family}.{task_name}.{metric}.spread"})
        for metric in ("recovery", "leakage", "selectivity"):
            entries.append({"category": "functional_reproducibility", "role": "C2",
                            "checkpoints": ["g4", "g5", "g6"], "control": "g7_descriptive_only",
                            "family": family, "summary_level": "family_summary", "task": None,
                            "metric": metric,
                            "required_output_fields": ["maximum_spread", "uncertainty", "status"],
                            "endpoint_id": f"g4_g5_g6.{family}.family_summary.{metric}.spread"})
    for role in ("C1", "C2"):
        checkpoints = ("raw",) if role == "C1" else ("g4", "g5", "g6", "g7")
        components = (("raw_full", "simple_family_projection", "simple_family_complement",
                       "simple_family_residual") if role == "C1"
                      else ("assigned", "nonassigned", "joint", "complement", "residual"))
        for checkpoint in checkpoints:
            for component in components:
                for task_name in TIER2:
                    for metric in ("recovery", "retention", "leakage"):
                        entries.append({"category": "collateral", "role": role,
                                        "checkpoint": checkpoint, "component": component,
                                        "task": task_name, "metric": metric,
                                        "required_output_fields": ["estimate", "uncertainty", "status"],
                                        "endpoint_id": f"{role}.{checkpoint}.{component}.{task_name}.{metric}.L3"})
    for checkpoint in ("g4", "g5", "g6", "g7"):
        for transform in TRANSFORMS:
            for control in CONTROLS:
                entries.append({"category": "counterfactual", "role": "C2",
                                "checkpoint": checkpoint, "transform": transform, "control": control,
                                "endpoint_id": f"C2.{checkpoint}.{transform}.{control}.L3"})
    for role in base.ROLES:
        for baseline in BASELINES:
            entries.append({"category": "baseline", "role": role, "baseline": baseline,
                            "endpoint_id": f"{role}.{baseline}.registered"})
    ids = [row["endpoint_id"] for row in entries]
    if len(ids) != len(set(ids)):
        raise ValueError("duplicate endpoint IDs")
    counts = collections.Counter(row["category"] for row in entries)
    value = {"schema_version": "msae_v3_endpoint_registry_v2", "protocol_id": PROTOCOL,
            "entries": entries, "endpoint_count": len(entries), "category_counts": dict(counts),
            "endpoint_id_set_sha256": base.sha_bytes(base.canonical_bytes(sorted(ids))),
            "families": {key: list(value) for key, value in FAMILIES.items()},
            "tier2_tasks": list(TIER2), "counterfactual_transforms": list(TRANSFORMS),
            "counterfactual_controls": list(CONTROLS), "baselines": list(BASELINES),
            "g7_interpretation": "matched_negative_control_not_replicate",
            "C1_scope": "raw_simple_G1_operands_only", "C2_scope": "G2_and_descriptive_control"}
    validate_endpoint_registry(value)
    return value


def _canonical_review(
    path: Path,
    supplied_sha256: str,
    *,
    scope: str,
    expected_digests: Mapping[str, str],
) -> dict[str, Any]:
    """Validate one create-once review and its exact machine control lines."""
    base.validate_sha256(supplied_sha256, f"{scope} review SHA-256")
    raw = _regular_bytes(path, mode=0o644)
    if base.sha_bytes(raw) != supplied_sha256 or not raw.endswith(b"\n") or b"\r" in raw:
        raise ValueError(f"{scope} review digest/newline drift")
    text = raw.decode("utf-8", errors="strict")
    if text.encode("utf-8") != raw:
        raise ValueError(f"{scope} review is not canonical UTF-8")
    lines = text.splitlines()
    stripped = [line.strip() for line in lines]
    for raw_line, stripped_line in zip(lines, stripped):
        control_like = (re.match(r"(?:VERDICT|REVIEW_SCOPE)\b", stripped_line,
                                 re.ASCII) is not None
                        or re.match(r"[A-Z][A-Z0-9_]*_SHA256\b", stripped_line,
                                    re.ASCII) is not None)
        if control_like and raw_line != stripped_line:
            raise ValueError(f"{scope} review has indented/padded control lines")
    malformed_review_controls = [line for line in lines
        if re.match(r"(?:VERDICT|REVIEW_SCOPE)\b", line, re.ASCII)
        and line not in {"VERDICT: SHIP", f"REVIEW_SCOPE: {scope}"}]
    if malformed_review_controls:
        raise ValueError(f"{scope} review has malformed/conflicting controls")
    verdicts = [line for line in lines if line.startswith("VERDICT:")]
    scopes = [line for line in lines if line.startswith("REVIEW_SCOPE:")]
    if verdicts != ["VERDICT: SHIP"] or scopes != [f"REVIEW_SCOPE: {scope}"]:
        raise ValueError(f"{scope} review verdict/scope is not uniquely SHIP")
    digest_rows: dict[str, str] = {}
    malformed_digest_controls = [line for line in lines
        if re.match(r"[A-Z][A-Z0-9_]*_SHA256\b", line, re.ASCII)
        and re.fullmatch(r"[A-Z][A-Z0-9_]*_SHA256: [0-9a-f]{64}", line,
                         re.ASCII) is None]
    if malformed_digest_controls:
        raise ValueError(f"{scope} review has malformed digest controls")
    digest_lines = [line for line in lines
                    if re.fullmatch(r"[A-Z][A-Z0-9_]*_SHA256: [0-9a-f]{64}",
                                    line, re.ASCII)]
    for line in digest_lines:
        match = re.fullmatch(r"([A-Z][A-Z0-9_]*)_SHA256: ([0-9a-f]{64})", line,
                             re.ASCII)
        if match is None or match.group(1) in digest_rows:
            raise ValueError(f"{scope} review has malformed/duplicate digest controls")
        digest_rows[match.group(1)] = match.group(2)
    if digest_rows != dict(expected_digests):
        raise ValueError(f"{scope} review digest controls mismatch: {digest_rows!r}")
    return {
        "path": path.relative_to(ROOT).as_posix(),
        "sha256": supplied_sha256,
        "scope": scope,
        "digests": digest_rows,
        "entry": _regular_entry(path),
    }


def _plan_review_binding(supplied_sha256: str) -> dict[str, Any]:
    if base.sha_file(PLAN_PATH) != FROZEN_PLAN_SHA256:
        raise ValueError("frozen gen3 plan bytes drifted")
    if supplied_sha256 != FROZEN_PLAN_REVIEW_SHA256:
        raise ValueError("setup does not name the reviewed frozen plan transcript")
    return _canonical_review(
        PLAN_REVIEW,
        supplied_sha256,
        scope="plan",
        expected_digests={"PLAN": FROZEN_PLAN_SHA256},
    )


def _typed_json_leaf_differences(
    left: Any, right: Any, pointer: str = "",
) -> list[dict[str, Any]]:
    """Return exact JSON-leaf differences with RFC-6901-style pointers."""
    if type(left) is not type(right):
        return [{"pointer": pointer or "/", "live": left, "candidate": right}]
    if isinstance(left, dict):
        differences: list[dict[str, Any]] = []
        keys = sorted(set(left) | set(right), key=lambda value: str(value).encode("utf-8"))
        for key in keys:
            escaped = str(key).replace("~", "~0").replace("/", "~1")
            child = f"{pointer}/{escaped}"
            if key not in left or key not in right:
                differences.append({"pointer": child, "live": left.get(key),
                                    "candidate": right.get(key)})
            else:
                differences.extend(_typed_json_leaf_differences(left[key], right[key], child))
        return differences
    if isinstance(left, list):
        differences = []
        for index in range(max(len(left), len(right))):
            child = f"{pointer}/{index}"
            if index >= len(left) or index >= len(right):
                differences.append({"pointer": child,
                                    "live": left[index] if index < len(left) else None,
                                    "candidate": right[index] if index < len(right) else None})
            else:
                differences.extend(
                    _typed_json_leaf_differences(left[index], right[index], child))
        return differences
    return [] if left == right else [
        {"pointer": pointer or "/", "live": left, "candidate": right}]


def _validate_gen2_terminal_namespace(*, require_failure: bool) -> None:
    """Close every gen2 child set without opening any quarantined payload."""
    _exact_directory_entries(predecessor_runtime.ACTIVE_CONFIG, {
        "protocol.json", "authorization_commitment.json", "ed25519_public.pem",
        "cpu_no_model_public_entry_trace.json",
    })
    _exact_directory_entries(
        predecessor_runtime.ACTIVE_PROV,
        {"m4_failure.json"} if require_failure else set())
    _exact_directory_entries(predecessor_runtime.ACTIVE_STATE, {"nonces"})
    _exact_directory_entries(predecessor_runtime.ACTIVE_NONCE_DIR, set())
    _exact_directory_entries(V3_DATA, {
        name for phase in ("M0", "M1", "M2")
        for name in base.V3_DATA_PHASE_FILES[phase]})
    for path in (predecessor_runtime.ACTIVE_CONFIG,
                 predecessor_runtime.ACTIVE_PROV,
                 predecessor_runtime.ACTIVE_STATE,
                 predecessor_runtime.ACTIVE_NONCE_DIR):
        st = path.lstat()
        if (stat.S_IMODE(st.st_mode) != 0o700 or st.st_uid != os.getuid()
                or not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)):
            raise ValueError(f"failed gen2 secure-directory drift: {path}")


def _rebuild_generic_config_at_synthetic_root(
    candidate_root: Path, checkpoints: list[dict[str, Any]],
) -> dict[str, Any]:
    """Execute immutable generic-builder bytes with typed read-only path mapping."""
    builder_path = ROOT / "scripts/msae_independent_measurement_v3.py"
    _regular_entry(builder_path)
    module_name = f"_msae_gen2_failure_rooted_{os.getpid()}_{id(candidate_root)}"
    spec = continuation.source_only_module_spec(module_name, builder_path)
    if spec is None or spec.loader is None:
        raise ValueError("cannot load immutable generic builder for failure reproduction")
    rooted_builder = importlib.util.module_from_spec(spec)
    captured: list[dict[str, Any]] = []

    def live_alias(path: Path) -> Path:
        return (ROOT / path.relative_to(candidate_root)
                if path.is_relative_to(candidate_root) else path)

    try:
        sys.modules[module_name] = rooted_builder
        spec.loader.exec_module(rooted_builder)
        rooted_builder.ROOT = candidate_root
        rooted_builder.V3_CONFIG = candidate_root / "configs/msae_independent_measurement_v3"
        rooted_builder.__file__ = str(
            candidate_root / "scripts/msae_independent_measurement_v3.py")
        rooted_builder.read_json = lambda path: base.read_json(live_alias(Path(path)))
        rooted_builder.sha_file = lambda path: base.sha_file(live_alias(Path(path)))
        rooted_builder.install_json = lambda path, value: captured.append(value)
        value = rooted_builder.build_protocol_config(checkpoints)
    finally:
        sys.modules.pop(module_name, None)
    if len(captured) != 1 or captured[0] != value:
        raise AssertionError("synthetic-root generic config interception failed")
    return value


def _rebuild_gen2_config_at_synthetic_root(
    candidate_root: Path, checkpoints: list[dict[str, Any]],
) -> dict[str, Any]:
    """Execute immutable generic + gen2 adapter code with no candidate-tree write."""
    rooted_generic = _rebuild_generic_config_at_synthetic_root(
        candidate_root, checkpoints)
    original_builder = base.build_protocol_config
    original_entry = predecessor_runtime._regular_entry

    def intercepted_builder(bound_checkpoints: list[dict[str, Any]]) -> dict[str, Any]:
        if bound_checkpoints != checkpoints:
            raise ValueError("synthetic gen2 checkpoint input drift")
        base.install_json(base.V3_CONFIG / "protocol.json", rooted_generic)
        return rooted_generic

    def rooted_entry(path: Path, *, root: Path) -> dict[str, Any]:
        if root != candidate_root or not path.is_relative_to(candidate_root):
            raise ValueError("synthetic gen2 adapter attempted a non-rooted local entry")
        live_path = ROOT / path.relative_to(candidate_root)
        return original_entry(live_path, root=ROOT)

    try:
        base.build_protocol_config = intercepted_builder
        predecessor_runtime._regular_entry = rooted_entry
        return predecessor_runtime._protocol_config_payload(
            checkpoints, M2_REVIEWED_COMPLETION_SHA256, root=candidate_root)
    finally:
        base.build_protocol_config = original_builder
        predecessor_runtime._regular_entry = original_entry


def _gen2_failure_payload() -> dict[str, Any]:
    """Reconstruct gen2's failed-M4 terminal record without rerunning M4."""
    expected_config_sha = "0abb5276f5241fc8bd206b271d63a11ece254adbbf6f66cc54f414121ce73c4e"
    expected_trace_sha = "0d9ce79822888aa8096018e3b271cf15fb0a02044c7a2d1af41afa28423e3ce2"
    predecessor_runtime.verify_m2_completion(M2_REVIEWED_COMPLETION_SHA256)
    predecessor_runtime._verify_existing_authorization_state()
    _validate_gen2_terminal_namespace(
        require_failure=_path_present(GEN2_FAILURE_PATH))
    trace_raw = predecessor_runtime._regular_bytes(
        predecessor_runtime.CPU_NO_MODEL_TRACE, mode=0o644)
    if base.sha_bytes(trace_raw) != expected_trace_sha:
        raise ValueError("failed gen2 CPU/no-model trace digest drift")
    trace_value = base.strict_json_loads(trace_raw.decode("utf-8"))
    if trace_raw != base.canonical_bytes(trace_value):
        raise ValueError("failed gen2 CPU/no-model trace canonical bytes drift")
    predecessor_runtime._validate_cpu_no_model_trace(
        trace_value, root=ROOT, checkpoints=predecessor_runtime.checkpoint_registry())
    gen2_config_path = predecessor_runtime.ACTIVE_CONFIG / "protocol.json"
    gen2_config_raw = predecessor_runtime._regular_bytes(gen2_config_path, mode=0o644)
    if base.sha_bytes(gen2_config_raw) != expected_config_sha:
        raise ValueError("failed gen2 M3 protocol config drift")
    gen2_config = base.strict_json_loads(gen2_config_raw.decode("utf-8"))
    if gen2_config_raw != base.canonical_bytes(gen2_config):
        raise ValueError("failed gen2 M3 protocol config is noncanonical")
    if gen2_config.get("post_m2_runtime", {}).get("generation") != "post_m2_gen2":
        raise ValueError("failed gen2 M3 generation drift")
    if any(predecessor_runtime.ACTIVE_NONCE_DIR.iterdir()):
        raise ValueError("failed gen2 nonce directory is not empty")
    absent_paths = [
        *(ROOT / relative for relative in predecessor_runtime.M4_NEW),
        predecessor_runtime.M4_TRANSACTION,
        predecessor_runtime.PRESCORE_REVIEW,
        predecessor_runtime.ACTIVE_RUN_ROOT,
        predecessor_runtime.M4_PRIMARY,
        predecessor_runtime.M4_REBUILD,
    ]
    for path in absent_paths:
        if _path_present(path):
            raise ValueError(f"failed gen2 downstream output unexpectedly exists: {path}")
    for pattern in _post_m3_forbidden_tmp_patterns()[3:]:
        matches = sorted(Path("/tmp").glob(pattern))
        if matches:
            raise ValueError(f"failed gen2 derived output unexpectedly exists: {matches}")
    quarantine = []
    for relative in sorted(base.QUARANTINED):
        path = ROOT / relative
        st = path.lstat()
        if (not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode)
                or stat.S_IMODE(st.st_mode) != 0o600 or st.st_nlink != 1):
            raise ValueError(f"failed gen2 quarantine identity drift: {relative}")
        quarantine.append({"path": relative, "device": st.st_dev, "inode": st.st_ino,
                           "uid": st.st_uid, "mode": stat.S_IMODE(st.st_mode),
                           "size": st.st_size, "nlink": st.st_nlink,
                           "content_read": False})
    generic = predecessor_runtime.generic_config_projection(gen2_config)
    live_environment = base.sha_bytes(base.canonical_bytes({
        "python": str((ROOT / ".venv-atlas/bin/python").resolve()),
        "deterministic": True, "tf32": False,
        "model_revision": base.SNAPSHOT.name, "dtype": "float16",
        "cache_dtype": "float32",
    }))
    synthetic_root = Path("/tmp/msae_independent_measurement_v3_gen2_failure_reproduction")
    rooted_environment = base.sha_bytes(base.canonical_bytes({
        "python": str((synthetic_root / ".venv-atlas/bin/python").resolve()),
        "deterministic": True, "tf32": False,
        "model_revision": base.SNAPSHOT.name, "dtype": "float16",
        "cache_dtype": "float32",
    }))
    strata = generic["replay"]["strata"]
    if len(strata) != 4 or any(row.get("environment_sha256") != live_environment
                               for row in strata):
        raise ValueError("failed gen2 environment reproduction precondition drift")
    candidate_config = _rebuild_gen2_config_at_synthetic_root(
        synthetic_root, list(gen2_config["checkpoint_registry"]))
    candidate_generic = predecessor_runtime.generic_config_projection(candidate_config)
    rooted_strata = candidate_generic.get("replay", {}).get("strata")
    if (not isinstance(rooted_strata, list) or len(rooted_strata) != 4
            or any(row.get("environment_sha256") != rooted_environment
                   for row in rooted_strata)):
        raise ValueError("failed gen2 synthetic-root builder environment drift")
    # The immutable failed Stage-A compared the full successor config, not only
    # its generic projection.  Prove that the complete gen2 candidate differs
    # at exactly the same four root-dependent leaves before reporting cause.
    differences = _typed_json_leaf_differences(gen2_config, candidate_config)
    pointers = [row["pointer"] for row in differences]
    expected_pointers = [f"/replay/strata/{index}/environment_sha256"
                         for index in range(len(strata))]
    if pointers != expected_pointers or any(
            row["live"] != live_environment or row["candidate"] != rooted_environment
            for row in differences):
        raise ValueError(f"failed gen2 typed root-cause diff drift: {differences}")
    config_entries = [_regular_entry(predecessor_runtime.ACTIVE_CONFIG / name)
                      for name in ("protocol.json", "authorization_commitment.json",
                                   "ed25519_public.pem",
                                   "cpu_no_model_public_entry_trace.json")]
    private_st = predecessor_runtime.ACTIVE_PRIVATE_KEY.lstat()
    payload = {
        "schema_version": "msae_v3_gen2_m4_failure_v1",
        "protocol_id": PROTOCOL,
        "generation": "post_m2_gen2",
        "status": "failed_before_stage_a_during_m4",
        "historical_failure": {
            "evidence_class": "operator_attested",
            "command": (".venv-atlas/bin/python -S -B -I "
                        "scripts/msae_independent_measurement_v3_post_m1.py build-m4"),
            "error_type": "ValueError",
            "error": "active protocol config does not reproduce",
            "full_original_transcript_available": False,
        },
        "independent_root_cause_reproduction": {
            "method": ("immutable_generic_builder_and_gen2_adapter_execution_at_fixed_"
                       "synthetic_candidate_root"),
            "generic_builder_entry": _regular_entry(
                ROOT / "scripts/msae_independent_measurement_v3.py"),
            "synthetic_candidate_root": str(synthetic_root),
            "live_environment_sha256": live_environment,
            "candidate_root_environment_sha256": rooted_environment,
            "differing_json_pointers": pointers,
            "field_differences": differences,
            "differing_field_count": len(differences),
            "all_other_generic_fields_unchanged": pointers == expected_pointers,
            "cause": "generic_builder_environment_python_path_depends_on_candidate_ROOT",
        },
        "m3_config_entries": config_entries,
        "m3_config_entry_set_sha256": base.sha_bytes(base.canonical_bytes(config_entries)),
        "private_key_lstat": {
            "path": str(predecessor_runtime.ACTIVE_PRIVATE_KEY),
            "device": private_st.st_dev, "inode": private_st.st_ino,
            "uid": private_st.st_uid, "mode": stat.S_IMODE(private_st.st_mode),
            "size": private_st.st_size, "nlink": private_st.st_nlink,
            "public_binding_independently_verified": True,
        },
        "quarantined_lstat": quarantine,
        "sealed_payload_content_reads": 0,
        "stage_a": "not_created", "m4_outputs": "not_created",
        "prescore_review": "not_created", "authorization_signature": "not_created",
        "model_gpu_tmux": "not_run", "successor_generation": GENERATION,
    }
    return payload


def _implementation_review_binding(supplied_sha256: str,
                                   predicted_failure: Mapping[str, Any]) -> dict[str, Any]:
    expected = {
        "PLAN": FROZEN_PLAN_SHA256,
        "PLAN_REVIEW": FROZEN_PLAN_REVIEW_SHA256,
        "CONTROLLER": base.sha_file(continuation.CONTROLLER_PATH),
        "RUNTIME": base.sha_file(RUNTIME),
        "RUNNER": base.sha_file(RUNNER),
        "LAUNCHER": base.sha_file(LAUNCHER),
        "RFC": base.sha_file(RUNTIME_RFC),
        "TEST": base.sha_file(RUNTIME_TEST),
        "GEN2_FAILURE_PAYLOAD": base.sha_bytes(base.canonical_bytes(predicted_failure)),
    }
    return _canonical_review(
        IMPLEMENTATION_REVIEW,
        supplied_sha256,
        scope="implementation",
        expected_digests=expected,
    )


def _environment_derivation(*, candidate_root: Path) -> dict[str, Any]:
    external_python = (ROOT / ".venv-atlas/bin/python").resolve(strict=True)
    st = external_python.stat()
    generic_payload = {
        "python": str(external_python), "deterministic": True, "tf32": False,
        "model_revision": base.SNAPSHOT.name, "dtype": "float16",
        "cache_dtype": "float32",
    }
    return {
        "schema_version": "msae_v3_gen3_environment_derivation_v1",
        "canonical_external_python_realpath": str(external_python),
        "canonical_external_python_size": st.st_size,
        "canonical_external_python_mode": stat.S_IMODE(st.st_mode),
        "canonical_external_python_sha256": base.sha_file(external_python),
        "python_startup_sha256": base.sha_bytes(base.canonical_bytes(_python_startup_payload())),
        "deterministic_algorithms": True, "allow_tf32": False,
        "model_revision": base.SNAPSHOT.name, "model_dtype": "float16",
        "cache_dtype": "float32",
        "canonical_environment_sha256": base.sha_bytes(base.canonical_bytes(generic_payload)),
    }


def _rooted_generic_environment_sha256(candidate_root: Path) -> str:
    return base.sha_bytes(base.canonical_bytes({
        "python": str((candidate_root / ".venv-atlas/bin/python").resolve()),
        "deterministic": True, "tf32": False,
        "model_revision": base.SNAPSHOT.name, "dtype": "float16",
        "cache_dtype": "float32",
    }))


def _rooted_generic_protocol_config(
    candidate_root: Path, checkpoints: list[dict[str, Any]],
) -> dict[str, Any]:
    """Load and execute the generic protocol builder from one candidate tree."""
    builder_path = candidate_root / "scripts/msae_independent_measurement_v3.py"
    st = builder_path.lstat()
    if (not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode)
            or st.st_uid != os.getuid() or st.st_nlink != 1):
        raise ValueError(f"rooted protocol-builder identity drift: {builder_path}")
    module_name = f"_msae_independent_measurement_v3_rooted_{os.getpid()}_{id(candidate_root)}"
    spec = continuation.source_only_module_spec(module_name, builder_path)
    if spec is None or spec.loader is None:
        raise ValueError("cannot load rooted generic protocol builder")
    rooted_builder = importlib.util.module_from_spec(spec)
    captured: list[dict[str, Any]] = []
    try:
        sys.modules[module_name] = rooted_builder
        spec.loader.exec_module(rooted_builder)
        rooted_builder.install_json = lambda path, value: captured.append(value)
        value = rooted_builder.build_protocol_config(checkpoints)
    finally:
        sys.modules.pop(module_name, None)
    if len(captured) != 1 or captured[0] != value:
        raise AssertionError("rooted protocol config interception failed")
    return value


def _protocol_config_payload(
    checkpoints: list[dict[str, Any]],
    reviewed_m2_sha256: str,
    *,
    plan_review_sha256: str,
    implementation_review_sha256: str,
    root: Path = ROOT,
) -> dict[str, Any]:
    base_config = _rooted_generic_protocol_config(root, checkpoints)
    derivation = _environment_derivation(candidate_root=root)
    candidate_gen2_runner_sha = base.sha_file(
        root / "scripts/run_msae_independent_calibration_v3.py")
    candidate_gen3_runner_sha = base.sha_file(root / RUNNER.relative_to(ROOT))
    strata = base_config.get("replay", {}).get("strata")
    if (not isinstance(strata, list)
            or [row.get("stratum_id") if isinstance(row, Mapping) else None
                for row in strata] != list(EXPECTED_REPLAY_STRATUM_IDS)):
        raise ValueError("generic replay stratum dimensions drift")
    adapted_strata = []
    for index, original_stratum in enumerate(strata):
        if (not isinstance(original_stratum, dict)
                or original_stratum.get("code_sha256") != candidate_gen2_runner_sha
                or original_stratum.get("environment_sha256") !=
                   _rooted_generic_environment_sha256(root)):
            raise ValueError(f"generic stratum substitution precondition drift: {index}")
        adapted = dict(original_stratum)
        adapted["code_sha256"] = candidate_gen3_runner_sha
        adapted["environment_sha256"] = derivation["canonical_environment_sha256"]
        if ({key: value for key, value in adapted.items()
             if key not in {"code_sha256", "environment_sha256"}} !=
                {key: value for key, value in original_stratum.items()
                 if key not in {"code_sha256", "environment_sha256"}}):
            raise AssertionError("gen3 typed adapter changed an undeclared stratum field")
        adapted_strata.append(adapted)
    base_config = dict(base_config)
    base_config["replay"] = dict(base_config["replay"])
    base_config["replay"]["strata"] = adapted_strata
    registry = endpoint_registry()
    by_category: dict[str, list[str]] = collections.defaultdict(list)
    for row in registry["entries"]:
        by_category[row["category"]].append(row["endpoint_id"])
    config = dict(base_config)
    config["post_m2_runtime"] = {
        "generation": GENERATION,
        "reviewed_m2_completion_sha256": reviewed_m2_sha256,
        "operator_instruction_sha256": base.sha_bytes(OPERATOR_INSTRUCTION.encode("utf-8")),
        "runtime_entry": _regular_entry(root / RUNTIME.relative_to(ROOT), root=root),
        "runner_entry": _regular_entry(root / RUNNER.relative_to(ROOT), root=root),
        "launcher_entry": _regular_entry(root / LAUNCHER.relative_to(ROOT), root=root),
        "runtime_rfc_entry": _regular_entry(root / RUNTIME_RFC.relative_to(ROOT), root=root),
        "runtime_test_entry": _regular_entry(root / RUNTIME_TEST.relative_to(ROOT), root=root),
        "model_snapshot_path": str(base.SNAPSHOT), "model_snapshot_revision": base.SNAPSHOT.name,
        "active_config_root": str(ACTIVE_CONFIG.relative_to(ROOT)),
        "active_provenance_root": str(ACTIVE_PROV.relative_to(ROOT)),
        "active_run_root": ACTIVE_RUN_REL,
        "environment_derivation": derivation,
        "review_gates": {
            "plan_sha256": FROZEN_PLAN_SHA256,
            "plan_entry": _regular_entry(root / PLAN_PATH.relative_to(ROOT), root=root),
            "plan_review_entry": _regular_entry(root / PLAN_REVIEW.relative_to(ROOT), root=root),
            "plan_review_sha256": plan_review_sha256,
            "implementation_review_entry": _regular_entry(
                root / IMPLEMENTATION_REVIEW.relative_to(ROOT), root=root),
            "implementation_review_sha256": implementation_review_sha256,
        },
    }
    config["checkpoint_registry"] = checkpoints
    config["endpoint_registry_payload_sha256"] = base.sha_bytes(base.canonical_bytes(registry))
    config["stages"] = dict(config["stages"])
    config["stages"]["C"] = {"purpose": "decision_review_candidate",
                               "required_by_category": {key: sorted(value) for key, value in by_category.items()},
                               "optional": []}
    replay = config["replay"]
    if any(row["source_role"] != replay["source_role"]
           or row["source_revision"] != replay["source_revision"]
           or row["partition"] != replay["partition"] for row in replay["strata"]):
        raise ValueError("global replay source/partition does not bind every stratum")
    for row in replay["strata"]:
        if (row["code_sha256"] != candidate_gen3_runner_sha
                or row["environment_sha256"] != derivation["canonical_environment_sha256"]):
            raise ValueError("gen3 replay code/environment adapter did not close")
    return config


def _validate_private_key_lstat_binding(
    path: Path, expected: Mapping[str, Any],
) -> os.stat_result:
    """Validate a committed private-key identity without reading key bytes."""
    st = path.lstat()
    if (not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode)
            or expected.get("path") != str(path)
            or (st.st_dev, st.st_ino, st.st_uid, st.st_nlink,
                stat.S_IMODE(st.st_mode), st.st_size, st.st_mtime_ns, st.st_ctime_ns) !=
               (expected.get("device"), expected.get("inode"), expected.get("uid"),
                expected.get("nlink"), expected.get("mode"), expected.get("size"),
                expected.get("mtime_ns"), expected.get("ctime_ns"))):
        raise ValueError("private key binding drift")
    return st


def _verify_existing_authorization_state(
    *, verify_private_content: bool = False,
) -> dict[str, Any]:
    from cryptography.hazmat.primitives import serialization
    config_st = ACTIVE_CONFIG.lstat()
    if (not stat.S_ISDIR(config_st.st_mode) or stat.S_ISLNK(config_st.st_mode)
            or stat.S_IMODE(config_st.st_mode) != 0o700 or config_st.st_uid != os.getuid()):
        raise ValueError("active config directory identity/mode/ownership drift")
    commitment_raw = _regular_bytes(ACTIVE_CONFIG / "authorization_commitment.json", mode=0o644)
    commitment = base.strict_json_loads(commitment_raw.decode("utf-8"))
    if commitment_raw != base.canonical_bytes(commitment):
        raise ValueError("authorization commitment is not canonical")
    commitment_keys = {
        "schema_version", "protocol_id", "generation", "operator_instruction",
        "operator_instruction_sha256", "public_key_path", "public_key_sha256",
        "public_key_fingerprint", "private_key_binding", "algorithm",
        "envelope_schema", "allowed_scope", "maximum_lifetime_seconds",
        "nonce_directory", "gpu_lock_directory", "review_gates",
        "contains_execution_authorization",
    }
    if (set(commitment) != commitment_keys
            or commitment.get("schema_version") != "msae_v3_authorization_commitment_v2"
            or commitment.get("protocol_id") != PROTOCOL
            or commitment.get("generation") != GENERATION
            or commitment.get("operator_instruction") != OPERATOR_INSTRUCTION
            or commitment.get("operator_instruction_sha256") != base.sha_bytes(OPERATOR_INSTRUCTION.encode("utf-8"))
            or commitment.get("public_key_path") !=
               str((ACTIVE_CONFIG / "ed25519_public.pem").relative_to(ROOT))
            or commitment.get("public_key_fingerprint") != commitment.get("public_key_sha256")
            or commitment.get("algorithm") != "Ed25519"
            or commitment.get("envelope_schema") != "msae_v3_signed_authorization_v2"
            or commitment.get("contains_execution_authorization") is not False
            or commitment.get("allowed_scope") != "calibration_replay_only"
            or commitment.get("maximum_lifetime_seconds") != 86400):
        raise ValueError("authorization commitment semantics drift")
    review_gates = commitment.get("review_gates")
    expected_review_gates = _trace_review_gates(
        ROOT, FROZEN_PLAN_REVIEW_SHA256, base.sha_file(IMPLEMENTATION_REVIEW))
    if review_gates != expected_review_gates:
        raise ValueError("authorization commitment review-gate binding drift")
    expected = commitment["private_key_binding"]
    if (not isinstance(expected, dict)
            or set(expected) != {"path", "device", "inode", "uid", "mode", "nlink",
                                 "size", "mtime_ns", "ctime_ns", "public_key_match"}
            or expected.get("public_key_match") is not True):
        raise ValueError("private key binding schema drift")
    _validate_private_key_lstat_binding(ACTIVE_PRIVATE_KEY, expected)
    public_bytes = _regular_bytes(ACTIVE_CONFIG / "ed25519_public.pem", mode=0o644)
    if base.sha_bytes(public_bytes) != commitment["public_key_sha256"]:
        raise ValueError("public key digest drift")
    if verify_private_content:
        private_raw = _regular_bytes(ACTIVE_PRIVATE_KEY, mode=0o600)
        private = serialization.load_pem_private_key(private_raw, password=None)
        derived = private.public_key().public_bytes(
            serialization.Encoding.PEM,
            serialization.PublicFormat.SubjectPublicKeyInfo)
        if derived != public_bytes:
            raise ValueError("private/public key mismatch")
    nonce = base._directory_binding(ACTIVE_NONCE_DIR)
    gpu = base._directory_binding(base.GPU_LOCK_DIR)
    if nonce != commitment.get("nonce_directory") or gpu != commitment.get("gpu_lock_directory"):
        raise ValueError("authorization state directory binding drift")
    return commitment


def preserve_m3_preflight() -> dict[str, Any]:
    """Append-only record for the stale, never-Stage-A preflight generation."""
    old_config = V3_CONFIG / "protocol.json"
    old_commitment = V3_CONFIG / "authorization_commitment.json"
    old_public = V3_CONFIG / "ed25519_public.pem"
    paths = (old_config, old_commitment, old_public, base.PRIVATE_KEY)
    if not all(path.exists() for path in paths):
        raise ValueError("the failed M3 preflight state is incomplete")
    private_st = base.PRIVATE_KEY.lstat()
    config = base.read_json(old_config)
    expected_digests = {
        old_config: FAILED_M3_CONFIG_SHA256,
        old_commitment: FAILED_M3_COMMITMENT_SHA256,
        old_public: FAILED_M3_PUBLIC_SHA256,
    }
    for path, expected_digest in expected_digests.items():
        if base.sha_file(path) != expected_digest:
            raise ValueError(f"failed M3 preflight artifact drift: {path}")
    old_commitment_value = base.read_json(old_commitment)
    expected_private = old_commitment_value["private_key_binding"]
    if (expected_private.get("path") != str(base.PRIVATE_KEY)
            or (private_st.st_dev, private_st.st_ino, private_st.st_uid, private_st.st_nlink,
                stat.S_IMODE(private_st.st_mode)) !=
               (expected_private["device"], expected_private["inode"], expected_private["uid"],
                expected_private["nlink"], expected_private["mode"])):
        raise ValueError("failed M3 preflight private-key binding drift")
    payload = {
        "schema_version": "msae_v3_m3_preflight_attempt_v1", "protocol_id": PROTOCOL,
        "generation": "post_m2_gen1_failed_preflight", "status": "failed_before_stage_a",
        "reviewed_m2_completion_sha256": M2_COMPLETION_PATH.exists() and base.sha_file(M2_COMPLETION_PATH),
        "config_entry": _regular_entry(old_config), "commitment_entry": _regular_entry(old_commitment),
        "public_key_entry": _regular_entry(old_public),
        "private_key_lstat": {"path": str(base.PRIVATE_KEY), "device": private_st.st_dev,
                              "inode": private_st.st_ino, "uid": private_st.st_uid,
                              "mode": stat.S_IMODE(private_st.st_mode), "size": private_st.st_size,
                              "nlink": private_st.st_nlink, "content_read": False},
        "bound_runtime_sha256": config.get("post_m2_runtime", {}).get("runtime_entry", {}).get("sha256"),
        "failure": {"type": "ValueError", "message": "cannot resolve unique RECORD for torch",
                    "command": ".venv-atlas/bin/python -B -I <closure_probe>",
                    "full_original_transcript_available": False},
        "stage_a": "not_run", "authorization_signature": "not_created",
        "model_gpu_tmux": "not_run", "successor_generation": GENERATION,
    }
    if PREFLIGHT_FAILURE_PATH.exists():
        if PREFLIGHT_FAILURE_PATH.read_bytes() != base.canonical_bytes(payload):
            raise ValueError("failed-preflight manifest drift")
    else:
        base.write_once(PREFLIGHT_FAILURE_PATH, base.canonical_bytes(payload), 0o644)
        base._fsync_directory(PREFLIGHT_FAILURE_PATH.parent)
    return payload


def _ensure_secure_dir(path: Path) -> None:
    if path.exists():
        base._secure_directory(path, create=False)
    else:
        path.mkdir(mode=0o700, parents=False)
        os.chmod(path, 0o700)
        base._fsync_directory(path.parent)
        base._secure_directory(path, create=False)


def _create_active_authorization_state(review_gates: Mapping[str, Any]) -> None:
    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
    ACTIVE_CONFIG.mkdir(mode=0o700, parents=False)
    os.chmod(ACTIVE_CONFIG, 0o700)
    base._fsync_directory(ACTIVE_CONFIG.parent)
    _ensure_secure_dir(ACTIVE_PRIVATE_KEY.parent)
    _ensure_secure_dir(ACTIVE_STATE.parent)
    _ensure_secure_dir(ACTIVE_STATE)
    _ensure_secure_dir(ACTIVE_NONCE_DIR)
    _ensure_secure_dir(base.GPU_LOCK_DIR)
    private = Ed25519PrivateKey.generate()
    private_bytes = private.private_bytes(serialization.Encoding.PEM,
                                          serialization.PrivateFormat.PKCS8,
                                          serialization.NoEncryption())
    base.write_once(ACTIVE_PRIVATE_KEY, private_bytes, 0o600)
    base._fsync_directory(ACTIVE_PRIVATE_KEY.parent)
    public_bytes = private.public_key().public_bytes(serialization.Encoding.PEM,
                                                      serialization.PublicFormat.SubjectPublicKeyInfo)
    base.write_once(ACTIVE_CONFIG / "ed25519_public.pem", public_bytes, 0o644)
    private_st = ACTIVE_PRIVATE_KEY.lstat()
    commitment = {
        "schema_version": "msae_v3_authorization_commitment_v2", "protocol_id": PROTOCOL,
        "generation": GENERATION, "operator_instruction": OPERATOR_INSTRUCTION,
        "operator_instruction_sha256": base.sha_bytes(OPERATOR_INSTRUCTION.encode("utf-8")),
        "public_key_path": str((ACTIVE_CONFIG / "ed25519_public.pem").relative_to(ROOT)),
        "public_key_sha256": base.sha_bytes(public_bytes),
        "public_key_fingerprint": base.sha_bytes(public_bytes),
        "private_key_binding": {"path": str(ACTIVE_PRIVATE_KEY), "device": private_st.st_dev,
                                "inode": private_st.st_ino, "uid": private_st.st_uid,
                                "mode": stat.S_IMODE(private_st.st_mode), "nlink": private_st.st_nlink,
                                "size": private_st.st_size,
                                "mtime_ns": private_st.st_mtime_ns,
                                "ctime_ns": private_st.st_ctime_ns,
                                "public_key_match": True},
        "algorithm": "Ed25519", "envelope_schema": "msae_v3_signed_authorization_v2",
        "allowed_scope": "calibration_replay_only", "maximum_lifetime_seconds": 86400,
        "nonce_directory": base._directory_binding(ACTIVE_NONCE_DIR),
        "gpu_lock_directory": base._directory_binding(base.GPU_LOCK_DIR),
        "review_gates": dict(review_gates),
        "contains_execution_authorization": False,
    }
    base.write_once(ACTIVE_CONFIG / "authorization_commitment.json", base.canonical_bytes(commitment), 0o644)
    base._fsync_directory(ACTIVE_CONFIG)


def _validate_setup_namespace_preconditions(
    predicted_failure: Mapping[str, Any],
) -> None:
    """Reject every partial/preplanted gen3 namespace before setup's first write."""
    downstream = [
        *[ROOT / relative for relative in M4_NEW],
        M4_TRANSACTION, M4_PRIMARY, M4_REBUILD, POST_M3_REVIEW,
        PRESCORE_REVIEW, ACTIVE_RUN_ROOT,
    ]
    for path in downstream:
        if _path_present(path):
            raise ValueError(f"gen3 downstream path exists before M3 setup: {path}")
    for pattern in (
        "msae_independent_measurement_v3_post_m2_gen3_*.prescore.check.json",
        "msae_independent_measurement_v3_post_m2_gen3_*.prescore.trace.log",
        "msae_independent_measurement_v3_post_m2_gen3_*.sock",
    ):
        matches = list(Path("/tmp").glob(pattern))
        if matches:
            raise ValueError(f"gen3 derived downstream path exists before M3 setup: {matches}")
    _validate_gen3_review_namespace("implementation")

    config_present = _path_present(ACTIVE_CONFIG)
    failure_present = _path_present(GEN2_FAILURE_PATH)
    if failure_present:
        _exact_directory_entries(
            GEN2_FAILURE_PATH.parent, {GEN2_FAILURE_PATH.name}, mode=0o700)
        if (_regular_bytes(GEN2_FAILURE_PATH, mode=0o644) !=
                base.canonical_bytes(predicted_failure)):
            raise ValueError("pre-existing gen2 M4 failure record drift")
    elif config_present:
        # The failure record is durably installed before ACTIVE_CONFIG is ever
        # created.  This is not a legitimate crash-recovery prefix.
        raise ValueError("active gen3 config exists before gen2 failure record")

    if not config_present:
        unexpected = [path for path in
                      (ACTIVE_PRIVATE_KEY, ACTIVE_STATE, ACTIVE_PROV, ACTIVE_M4_DATA)
                      if _path_present(path)]
        if unexpected:
            raise ValueError(f"partial/preplanted gen3 M3 namespace: {unexpected}")
        return

    # Setup is the sole pre-M3 transition allowed to read the private key; a
    # complete-looking preplant must prove public/private agreement before the
    # first append-only failure-record write.
    _verify_existing_authorization_state(verify_private_content=True)
    _exact_directory_entries(ACTIVE_CONFIG, {
        "protocol.json", "authorization_commitment.json", "ed25519_public.pem",
        "cpu_no_model_public_entry_trace.json",
    }, mode=0o700)
    _exact_directory_entries(ACTIVE_PROV, set(), mode=0o700)
    _exact_directory_entries(ACTIVE_M4_DATA, set(), mode=0o700)
    _exact_directory_entries(ACTIVE_STATE, {"nonces"}, mode=0o700)
    _exact_directory_entries(ACTIVE_NONCE_DIR, set(), mode=0o700)


def _preserve_gen2_failure_record(predicted_failure: Mapping[str, Any]) -> None:
    """Create or verify the sole allowed gen3 write in the gen2 namespace."""
    expected_children = {GEN2_FAILURE_PATH.name} if _path_present(GEN2_FAILURE_PATH) else set()
    _exact_directory_entries(GEN2_FAILURE_PATH.parent, expected_children, mode=0o700)
    failure_raw = base.canonical_bytes(predicted_failure)
    if _path_present(GEN2_FAILURE_PATH):
        if _regular_bytes(GEN2_FAILURE_PATH, mode=0o644) != failure_raw:
            raise ValueError("existing gen2 M4 failure record drift")
    else:
        base.write_once(GEN2_FAILURE_PATH, failure_raw, 0o644)
        base._fsync_directory(GEN2_FAILURE_PATH.parent)


def _validate_gen3_review_namespace(phase: str) -> None:
    """Close the shared adversarial directory for this generation's prefix."""
    expected_by_phase = {
        "implementation": {PLAN_REVIEW.name, IMPLEMENTATION_REVIEW.name},
        "post_m3": {PLAN_REVIEW.name, IMPLEMENTATION_REVIEW.name, POST_M3_REVIEW.name},
        "prescore": {PLAN_REVIEW.name, IMPLEMENTATION_REVIEW.name, POST_M3_REVIEW.name},
        "post_review": {
            PLAN_REVIEW.name, IMPLEMENTATION_REVIEW.name, POST_M3_REVIEW.name,
            PRESCORE_REVIEW.name,
        },
    }
    if phase not in expected_by_phase:
        raise ValueError(f"unknown gen3 review projection phase: {phase}")
    prefix = "msae_independent_measurement_v3_post_m2_gen3_"
    review_root = PLAN_REVIEW.parent
    observed = {
        entry.name for entry in os.scandir(review_root)
        if entry.name.startswith(prefix)
    }
    if observed != expected_by_phase[phase]:
        raise ValueError(
            f"gen3 review namespace drift: missing={expected_by_phase[phase] - observed}, "
            f"extra={observed - expected_by_phase[phase]}")


def setup_m3(reviewed_m2_sha256: str, plan_review_sha256: str,
             implementation_review_sha256: str) -> dict[str, Any]:
    if reviewed_m2_sha256 != M2_REVIEWED_COMPLETION_SHA256:
        raise ValueError("M3 requires the independently reviewed M2 completion pin")
    plan_review = _plan_review_binding(plan_review_sha256)
    predicted_failure = _gen2_failure_payload()
    implementation_review = _implementation_review_binding(
        implementation_review_sha256, predicted_failure)
    verify_m2_completion(reviewed_m2_sha256)
    _validate_setup_namespace_preconditions(predicted_failure)
    preserve_m3_preflight()
    checkpoints = checkpoint_registry()
    config = _protocol_config_payload(
        checkpoints, reviewed_m2_sha256,
        plan_review_sha256=plan_review_sha256,
        implementation_review_sha256=implementation_review_sha256)
    trace_review_gates = _trace_review_gates(
        ROOT, plan_review_sha256, implementation_review_sha256)
    cpu_trace = cpu_no_model_public_entry_trace(review_gates=trace_review_gates)
    _validate_cpu_no_model_trace(cpu_trace, root=ROOT, checkpoints=checkpoints)
    cpu_trace_raw = base.canonical_bytes(cpu_trace)
    _preserve_gen2_failure_record(predicted_failure)
    state = (_path_present(ACTIVE_PRIVATE_KEY),
             _path_present(ACTIVE_CONFIG / "ed25519_public.pem"),
             _path_present(ACTIVE_CONFIG / "authorization_commitment.json"))
    created = False
    if state == (False, False, False) and not _path_present(ACTIVE_CONFIG):
        _create_active_authorization_state(trace_review_gates)
        created = True
    elif state != (True, True, True):
        raise ValueError(f"partial successor M3 authorization state: {state}")
    if _path_present(CPU_NO_MODEL_TRACE):
        if _regular_bytes(CPU_NO_MODEL_TRACE, mode=0o644) != cpu_trace_raw:
            raise ValueError("existing CPU/no-model public-entry trace drift")
    elif created:
        base.write_once(CPU_NO_MODEL_TRACE, cpu_trace_raw, 0o644)
        base._fsync_directory(ACTIVE_CONFIG)
    else:
        raise ValueError("partial successor M3 state lacks CPU/no-model trace")
    commitment = _verify_existing_authorization_state(verify_private_content=True)
    config_path = ACTIVE_CONFIG / "protocol.json"
    if _path_present(config_path):
        if _regular_bytes(config_path, mode=0o644) != base.canonical_bytes(config):
            raise ValueError("existing protocol config drift")
    else:
        base.write_once(config_path, base.canonical_bytes(config), 0o644)
        base._fsync_directory(config_path.parent)
    if _path_present(ACTIVE_PROV):
        st = ACTIVE_PROV.lstat()
        if (not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)
                or st.st_uid != os.getuid() or stat.S_IMODE(st.st_mode) != 0o700):
            raise ValueError("active provenance root drift")
    else:
        ACTIVE_PROV.mkdir(mode=0o700)
        os.chmod(ACTIVE_PROV, 0o700)
        base._fsync_directory(ACTIVE_PROV.parent)
    if _path_present(ACTIVE_M4_DATA):
        _exact_directory_entries(ACTIVE_M4_DATA, set(), mode=0o700)
    else:
        ACTIVE_M4_DATA.mkdir(mode=0o700)
        os.chmod(ACTIVE_M4_DATA, 0o700)
        base._fsync_directory(ACTIVE_M4_DATA.parent)
    base.verify_baseline_projection("M2")
    return {"schema_version": "msae_v3_m3_completion_v1",
            "generation": GENERATION,
            "protocol_config_sha256": base.sha_file(config_path),
            "authorization_commitment_sha256": base.sha_file(ACTIVE_CONFIG / "authorization_commitment.json"),
            "public_key_sha256": base.sha_file(ACTIVE_CONFIG / "ed25519_public.pem"),
            "cpu_no_model_trace_sha256": base.sha_file(CPU_NO_MODEL_TRACE),
            "plan_review_sha256": plan_review["sha256"],
            "implementation_review_sha256": implementation_review["sha256"],
            "gen2_failure_sha256": base.sha_file(GEN2_FAILURE_PATH),
            "checkpoint_sha256": {row["checkpoint_id"]: row["checkpoint_sha256"] for row in checkpoints},
            "contains_execution_authorization": commitment["contains_execution_authorization"]}


def _ldd_inventory(path: Path, *, library_dirs: Sequence[Path] = ()) -> list[dict[str, Any]]:
    # ldd is part of the frozen execution closure, so its resolution must not
    # depend on an operator's inherited LD_PRELOAD/LD_LIBRARY_PATH or locale.
    environment = dict(FROZEN_BASE_PROCESS_ENVIRONMENT)
    if library_dirs:
        environment["LD_LIBRARY_PATH"] = ":".join(
            str(item.resolve(strict=True)) for item in library_dirs)
    result = subprocess.run(["/usr/bin/ldd", str(path)], text=True, capture_output=True,
                            env=environment)
    output = result.stdout + result.stderr
    if result.returncode != 0:
        if "not a dynamic executable" in output and path.read_bytes().startswith(b"#!"):
            return []
        raise ValueError(f"ldd failed for {path}: {output.strip()}")
    if re.search(r"=>\s+not found(?:\s|$)", output):
        raise ValueError(f"unresolved ldd dependency for {path}: {output.strip()}")
    paths: set[Path] = set()
    for line in output.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith(("linux-vdso.so", "linux-gate.so")):
            continue
        match = re.search(r"(?:=>\s+)?(/[^ ]+)", line)
        if not match:
            if stripped in {"statically linked"}:
                continue
            raise ValueError(f"unrecognized ldd dependency line for {path}: {stripped}")
        raw = match.group(1).replace("/usr/${LIB}/", "/usr/lib/x86_64-linux-gnu/")
        candidate = Path(raw)
        if not candidate.exists():
            raise ValueError(f"unresolved ldd dependency for {path}: {raw}")
        paths.add(candidate.resolve(strict=True))
    return [{"path": str(item), "size": item.stat().st_size, "sha256": base.sha_file(item)}
            for item in sorted(paths, key=lambda value: str(value).encode("utf-8"))]


def _executable_record(path: Path) -> dict[str, Any]:
    resolved = path.resolve(strict=True)
    return {"path": str(resolved), "size": resolved.stat().st_size,
            "mode": stat.S_IMODE(resolved.stat().st_mode), "sha256": base.sha_file(resolved),
            "ldd": _ldd_inventory(resolved)}


def _python_startup_payload() -> dict[str, Any]:
    launcher = ROOT / ".venv-atlas/bin/python"
    pyvenv = ROOT / ".venv-atlas/pyvenv.cfg"
    launcher_entry = base._content_entry(launcher)
    pyvenv_entry = _regular_entry(pyvenv)
    stdlib = Path("/usr/lib/python3.12")
    stdlib_entries = []
    for path in sorted(stdlib.rglob("*"), key=lambda item: str(item).encode("utf-8")):
        relative = path.relative_to(stdlib)
        if relative.parts and relative.parts[0] in {"site-packages", "dist-packages"}:
            continue
        if path.is_dir() and not path.is_symlink():
            continue
        entry = base._content_entry(path, root=stdlib)
        stdlib_entries.append(entry)
    site_roots = []
    for root in FROZEN_SITE_PATHS:
        root_st = root.lstat()
        if not stat.S_ISDIR(root_st.st_mode) or stat.S_ISLNK(root_st.st_mode):
            raise ValueError(f"frozen site root identity drift: {root}")
        entries = []
        for path in sorted(root.iterdir(), key=lambda item: item.name.encode("utf-8")):
            st = path.lstat()
            row: dict[str, Any] = {"name": path.name,
                                   "type": ("symlink" if stat.S_ISLNK(st.st_mode) else
                                            "directory" if stat.S_ISDIR(st.st_mode) else
                                            "regular" if stat.S_ISREG(st.st_mode) else "other"),
                                   "mode": stat.S_IMODE(st.st_mode)}
            if row["type"] == "other":
                raise ValueError(f"unsupported frozen site-root entry: {path}")
            if row["type"] in {"regular", "symlink"}:
                resolved = path.resolve(strict=True)
                if not resolved.is_file():
                    raise ValueError(f"site-root entry does not resolve to a file: {path}")
                row.update({"realpath": str(resolved), "size": resolved.stat().st_size,
                            "sha256": base.sha_file(resolved)})
            entries.append(row)
        site_roots.append({"path": str(root), "mode": stat.S_IMODE(root_st.st_mode),
                           "uid": root_st.st_uid, "entries": entries,
                           "entries_sha256": base.sha_bytes(base.canonical_bytes(entries))})
    return {"schema_version": "msae_v3_python_startup_v1",
            "required_flags": ["-S", "-B", "-I"],
            "launcher": launcher_entry, "pyvenv_config": pyvenv_entry,
            "base_sys_path": ["/usr/lib/python312.zip", "/usr/lib/python3.12",
                              "/usr/lib/python3.12/lib-dynload"],
            "manually_appended_site_paths": [str(path) for path in FROZEN_SITE_PATHS],
            "site_roots": site_roots,
            "stdlib_entries": stdlib_entries,
            "stdlib_entries_sha256": base.sha_bytes(base.canonical_bytes(stdlib_entries)),
            "site_initialization_disabled": True, "pth_execution_disabled": True,
            "sitecustomize_execution_disabled": True}


def _distribution_inventory(name: str) -> dict[str, Any]:
    """Bind RECORD when available, otherwise exhaustively bind installed files."""
    distribution = importlib.metadata.distribution(name)
    site_root = Path(distribution.locate_file("."))
    shared_search = {path.parent.resolve(strict=True) for path in site_root.glob("*.libs/*.so*")}
    shared_search.update(path.parent.resolve(strict=True) for path in site_root.glob("*/lib/*.so*"))
    shared_search.update(path.parent.resolve(strict=True) for path in site_root.glob("nvidia/*/lib/*.so*"))
    record_paths = [Path(item.locate()) for item in distribution.files or []
                    if str(item).endswith(".dist-info/RECORD")]
    if len(record_paths) == 1:
        value = base._distribution_record(name)
        native_ldd = []
        for row in value.get("native_libraries", []):
            path = Path(row["path"])
            with path.open("rb") as handle:
                magic = handle.read(4)
            if magic == b"\x7fELF":
                search = sorted(shared_search | {path.parent.resolve(strict=True)}, key=lambda item: str(item))
                native_ldd.append({"path": str(path.resolve(strict=True)),
                                   "dependencies": _ldd_inventory(path, library_dirs=search)})
        value["fallback"] = None
        value["declared_top_level_roots"] = None
        value["entries"] = []
        value["entries_sha256"] = base.sha_bytes(base.canonical_bytes([]))
        value["native_ldd"] = native_ldd
        value["native_ldd_sha256"] = base.sha_bytes(base.canonical_bytes(native_ldd))
        return value
    roots: list[Path] = []
    metadata_root = Path(distribution._path)  # type: ignore[attr-defined]
    if metadata_root.exists():
        roots.append(metadata_root)
    top_level = metadata_root / "top_level.txt"
    declared: list[str]
    if top_level.exists():
        declared = [line.strip() for line in top_level.read_text(encoding="utf-8").splitlines()
                    if line.strip() and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", line.strip())]
    else:
        declared = {"nvidia-ml-py": ["pynvml.py"]}.get(name, [name.lower().replace("-", "_")])
    if not declared:
        raise ValueError(f"distribution declares no import roots: {name}")
    for package_name in declared:
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*(?:\.py)?", package_name, re.ASCII) is None:
            raise ValueError(f"invalid declared distribution root: {name}/{package_name}")
        package_root = Path(distribution.locate_file(package_name))
        if not package_root.exists():
            raise ValueError(f"declared distribution root is missing: {name}/{package_name}")
        if package_root not in roots:
            roots.append(package_root)
    if not roots:
        raise ValueError(f"distribution has neither RECORD nor installed roots: {name}")
    entries: list[dict[str, Any]] = []
    seen: set[str] = set()
    for root in sorted(roots, key=lambda path: str(path).encode("utf-8")):
        candidates = [root] if root.is_file() else list(root.rglob("*"))
        for path in sorted(candidates, key=lambda item: str(item).encode("utf-8")):
            if path.is_dir() and not path.is_symlink():
                continue
            resolved = path.resolve(strict=True)
            if not resolved.is_file():
                raise ValueError(f"non-file in exhaustive distribution inventory: {path}")
            key = str(path)
            if key in seen:
                continue
            seen.add(key)
            st = path.lstat()
            entries.append({"path": key, "type": "symlink" if stat.S_ISLNK(st.st_mode) else "regular",
                            "mode": stat.S_IMODE(st.st_mode), "size": st.st_size,
                            "realpath": str(resolved), "target_size": resolved.stat().st_size,
                            "sha256": base.sha_file(resolved)})
    native_libraries = [{"path": row["realpath"], "size": row["target_size"],
                         "sha256": row["sha256"]}
                        for row in entries if ".so" in Path(row["path"]).name]
    native_ldd = []
    for row in native_libraries:
        path = Path(row["path"])
        if path.read_bytes()[:4] == b"\x7fELF":
            search = sorted(shared_search | {path.parent.resolve(strict=True)}, key=lambda item: str(item))
            native_ldd.append({"path": row["path"],
                               "dependencies": _ldd_inventory(path, library_dirs=search)})
    return {"distribution": distribution.metadata["Name"], "version": distribution.version,
            "record_path": None, "record_sha256": None, "record_verified_files": 0,
            "record_unhashed_rows": 0, "fallback": "exhaustive_installed_file_manifest",
            "declared_top_level_roots": declared,
            "entries": entries, "entries_sha256": base.sha_bytes(base.canonical_bytes(entries)),
            "native_libraries": native_libraries,
            "native_ldd": native_ldd,
            "native_ldd_sha256": base.sha_bytes(base.canonical_bytes(native_ldd))}


LOCAL_PYTHON_ENTRYPOINTS = (
    "scripts/msae_independent_measurement_v3.py",
    "scripts/msae_independent_measurement_v3_post_m1.py",
    "scripts/msae_independent_measurement_v3_post_m1_runtime.py",
    "scripts/run_msae_independent_calibration_v3.py",
    "scripts/msae_independent_measurement_v3_post_m2_gen3.py",
    "scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
    "scripts/run_msae_independent_calibration_v3_gen3.py",
    "scripts/msae_measurement_remediation_v1.py",
    "scripts/msae_measurement_v2.py",
)


def _qualified_call_name(node: ast.AST) -> str | None:
    parts: list[str] = []
    while isinstance(node, ast.Attribute):
        parts.append(node.attr)
        node = node.value
    if isinstance(node, ast.Name):
        parts.append(node.id)
        return ".".join(reversed(parts))
    return None


def _local_import_path(module: str, *, root: Path) -> str | None:
    pieces = module.split(".")
    candidates = []
    for prefix in (Path("scripts"), Path(".")):
        base_path = root / prefix.joinpath(*pieces)
        candidates.extend((base_path.with_suffix(".py"), base_path / "__init__.py"))
    existing = [path for path in candidates if path.is_file() and not path.is_symlink()]
    if len(existing) > 1:
        raise ValueError(f"ambiguous local import resolution: {module}")
    if not existing:
        return None
    return existing[0].relative_to(root).as_posix()


def _path_taking_local_helpers(*, root: Path) -> dict[str, tuple[tuple[int, str], ...]]:
    """Infer local helper parameters that can flow to a file/FD operation.

    This conservative fixed point closes calls such as ``protocol.read_json(p)``
    and wrappers around those helpers.  It intentionally unions same-named
    local functions: over-approximating a path parameter is safer than silently
    missing an indirect file sink.
    """
    file_leaves = {
        "open", "read", "write", "lseek", "fstat", "fsync", "ftruncate",
        "fchmod", "close", "mkdir", "rename", "replace", "unlink", "remove",
        "stat", "lstat", "readlink", "chmod", "scandir", "walk", "listdir",
        "rmtree", "read_bytes", "read_text", "write_bytes", "write_text",
        "rmdir", "exists", "is_file", "is_dir", "is_symlink", "iterdir",
        "rglob", "glob", "resolve",
    }
    trees = {
        relative: ast.parse((root / relative).read_text(encoding="utf-8"), filename=relative)
        for relative in LOCAL_PYTHON_ENTRYPOINTS
    }
    functions: list[tuple[str, tuple[str, ...], ast.AST]] = []
    for tree in trees.values():
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                parameters = tuple(
                    argument.arg for argument in
                    (*node.args.posonlyargs, *node.args.args, *node.args.kwonlyargs)
                )
                functions.append((node.name, parameters, node))
    helper_parameters: dict[str, set[int]] = collections.defaultdict(set)
    changed = True
    while changed:
        changed = False
        for function_name, parameters, function in functions:
            by_name = {name: index for index, name in enumerate(parameters)}
            for call in (node for node in ast.walk(function) if isinstance(node, ast.Call)):
                qualified = _qualified_call_name(call.func)
                leaf = (call.func.attr if isinstance(call.func, ast.Attribute)
                        else call.func.id if isinstance(call.func, ast.Name) else None)
                expressions: list[ast.AST] = []
                if leaf in file_leaves or qualified in {"open", "io.open"}:
                    descriptor_qualified = {"os.read", "os.write", "os.lseek", "os.fstat",
                                            "os.fsync", "os.ftruncate", "os.fchmod", "os.close"}
                    if qualified in descriptor_qualified:
                        expressions.extend(call.args[:1])
                    elif (qualified or "").startswith(("os.", "io.", "shutil.")) or qualified == "open":
                        width = 2 if leaf in {"rename", "replace"} else 1
                        expressions.extend(call.args[:width])
                    elif isinstance(call.func, ast.Attribute):
                        expressions.append(call.func.value)
                        if leaf in {"rename", "replace"}:
                            expressions.extend(call.args[:1])
                    else:
                        expressions.extend(call.args[:1])
                elif leaf in helper_parameters:
                    for index in helper_parameters[leaf]:
                        if index < len(call.args):
                            expressions.append(call.args[index])
                        else:
                            parameter_names = {
                                candidate_parameters[index]
                                for candidate_name, candidate_parameters, _ in functions
                                if candidate_name == leaf and index < len(candidate_parameters)
                            }
                            expressions.extend(keyword.value for keyword in call.keywords
                                               if keyword.arg in parameter_names)
                for expression in expressions:
                    referenced = {node.id for node in ast.walk(expression)
                                  if isinstance(node, ast.Name)}
                    for name in referenced & by_name.keys():
                        index = by_name[name]
                        if index not in helper_parameters[function_name]:
                            helper_parameters[function_name].add(index)
                            changed = True
    parameter_names_by_function: dict[str, dict[int, set[str]]] = collections.defaultdict(
        lambda: collections.defaultdict(set))
    for name, parameters, _ in functions:
        for index in helper_parameters.get(name, set()):
            if index < len(parameters):
                parameter_names_by_function[name][index].add(parameters[index])
    return {
        name: tuple((index, sorted(parameter_names_by_function[name][index])[0])
                    for index in sorted(indices))
        for name, indices in helper_parameters.items()
    }


def _normalized_local_value_flow_ast_sha256(*, root: Path) -> str:
    """Bind every local AST while excluding only the self-authenticating constants.

    Per-site analysis handles known sinks. This conservative ledger closes
    otherwise-unresolved caller-built argv, tuple destructuring, helper-return,
    attribute, conditional, and subscript value flows: any such construction
    change requires an explicit new reviewed freeze rather than inheriting an
    old sink authorization.
    """
    excluded = {
        "FROZEN_STATIC_SURFACE_SET_SHA256", "FROZEN_DYNAMIC_FILE_SITE_SET_SHA256",
        "FROZEN_LOCAL_VALUE_FLOW_AST_SHA256", "FROZEN_DYNAMIC_FILE_SITE_BINDING_IDS",
        "FROZEN_NONFILE_SURFACE_SITE_BINDING_IDS",
    }

    class Normalize(ast.NodeTransformer):
        def visit_Assign(self, node: ast.Assign) -> ast.AST:  # noqa: N802
            names = {target.id for target in node.targets if isinstance(target, ast.Name)}
            frozen_names = names & excluded
            if frozen_names:
                for name in frozen_names:
                    if name.endswith("SHA256"):
                        if (not isinstance(node.value, ast.Constant)
                                or not isinstance(node.value.value, str)
                                or re.fullmatch(r"[0-9a-f]{64}", node.value.value,
                                                re.ASCII) is None):
                            raise ValueError(f"self-authenticating digest constant is not inert: {name}")
                    else:
                        value = node.value
                        if (not isinstance(value, ast.Call)
                                or not isinstance(value.func, ast.Name)
                                or value.func.id != "frozenset" or len(value.args) != 1
                                or value.keywords
                                or not isinstance(value.args[0], ast.Call)
                                or not isinstance(value.args[0].func, ast.Attribute)
                                or value.args[0].func.attr != "split"
                                or value.args[0].args or value.args[0].keywords
                                or not isinstance(value.args[0].func.value, ast.Constant)
                                or not isinstance(value.args[0].func.value.value, str)
                                or any(re.fullmatch(r"[0-9a-f]{64}", item, re.ASCII) is None
                                       for item in value.args[0].func.value.value.split())):
                            raise ValueError(f"self-authenticating site registry is not inert: {name}")
            node = self.generic_visit(node)
            if frozen_names:
                node.value = ast.Constant(value="<self-authenticating-static-ledger>")
            return node

    rows = []
    for relative in sorted(LOCAL_PYTHON_ENTRYPOINTS):
        tree = ast.parse((root / relative).read_text(encoding="utf-8"), filename=relative)
        normalized = Normalize().visit(tree)
        ast.fix_missing_locations(normalized)
        rows.append({"path": relative,
                     "ast": ast.dump(normalized, annotate_fields=True,
                                     include_attributes=False)})
    return base.sha_bytes(base.canonical_bytes(rows))


def _static_closure_analysis(*, root: Path = ROOT) -> dict[str, Any]:
    """Recursively resolve local imports and statically close dangerous surfaces."""
    queue = list(LOCAL_PYTHON_ENTRYPOINTS)
    parsed: dict[str, ast.Module] = {}
    import_edges: list[dict[str, str]] = []
    external_modules: set[str] = set()
    surfaces: list[dict[str, Any]] = []
    dynamic_imports: list[dict[str, Any]] = []
    process_calls = {"subprocess.run", "subprocess.check_output", "subprocess.check_call",
                     "subprocess.Popen", "os.execve", "os.execv", "os.execl", "os.system"}
    file_calls = {"open", "io.open", "os.open", "os.read", "os.write", "os.lseek",
                  "os.fstat", "os.fsync", "os.ftruncate", "os.fchmod", "os.close",
                  "os.mkdir", "os.rename", "os.replace", "os.unlink", "os.remove",
                  "os.stat", "os.lstat", "os.readlink", "os.chmod",
                  "os.scandir", "os.walk", "os.listdir", "shutil.rmtree",
                  "Path.open", "Path.read_bytes", "Path.read_text", "Path.write_bytes",
                  "Path.write_text", "Path.unlink", "Path.mkdir", "Path.rename",
                  "Path.replace", "Path.rmdir", "Path.exists", "Path.is_file",
                  "Path.is_dir", "Path.is_symlink", "Path.stat", "Path.lstat",
                  "Path.iterdir", "Path.rglob", "Path.glob", "Path.resolve"}
    library_calls = {"ctypes.CDLL", "ctypes.PyDLL", "ctypes.cdll.LoadLibrary"}
    network_calls = {"socket.socket", "socket.create_connection"}
    network_leaf_calls = {"connect", "bind", "listen", "accept", "sendall", "sendmsg",
                          "recv", "recvmsg", "getsockopt", "settimeout"}
    allowed_process_literals = {"/usr/bin/bash", "/usr/bin/git", "/usr/bin/ldd",
                                "/usr/bin/nvidia-smi", "/usr/bin/strace", "/usr/bin/tmux",
                                str(ROOT / ".venv-atlas/bin/python")}
    allowed_absolute_file_literals = {
        "/", "/proc", "/proc/self/maps", "/dev/null", "/tmp", "/usr/${LIB}/",
        "/usr/lib/python3.12", "/usr/lib/x86_64-linux-gnu",
        "/usr/lib/x86_64-linux-gnu/libcuda.so.1",
        "/usr/lib/python3.12/site-packages", "/usr/local/lib/python3.12/dist-packages",
        "/usr/lib/python3/dist-packages", "/usr/bin/bash", "/usr/bin/git",
        "/usr/bin/ldd", "/usr/bin/nvidia-smi", "/usr/bin/strace", "/usr/bin/tmux",
        str(ROOT / ".venv-atlas/bin/python"), str(base.SNAPSHOT), str(ACTIVE_PRIVATE_KEY),
        str(base.PRIVATE_KEY), str(base.PRIMARY_BUILD_ROOT), str(base.REBUILD_BUILD_ROOT),
        str(base.STATE_ROOT), str(base.NONCE_DIR.parent), str(base.NONCE_DIR),
        str(base.GPU_LOCK_DIR), str(base.RUN_ROOT),
        str(ACTIVE_STATE), str(ACTIVE_NONCE_DIR), str(M4_PRIMARY), str(M4_REBUILD),
        str(predecessor_runtime.ACTIVE_PRIVATE_KEY),
        str(predecessor_runtime.ACTIVE_STATE), str(predecessor_runtime.ACTIVE_NONCE_DIR),
        str(predecessor_runtime.M4_PRIMARY), str(predecessor_runtime.M4_REBUILD),
        str(predecessor_runtime.ACTIVE_RUN_ROOT),
        "/tmp/msae_independent_measurement_v3_gen2_failure_reproduction",
        ("/tmp/msae_independent_measurement_v3_gen2_failure_reproduction/"
         ".venv-atlas/bin/python"),
        "/tmp/msae_surface_probe_check.json", "/tmp/msae_surface_probe_trace.log",
    }
    dynamic_process_mappings = {
        ("scripts/msae_independent_measurement_v3.py", "prescore_traced_check", "subprocess.run"):
            ["/usr/bin/strace"],
        ("scripts/msae_independent_measurement_v3.py", "broker", "os.execve"):
            [str(ROOT / ".venv-atlas/bin/python")],
        ("scripts/msae_independent_measurement_v3_post_m1_runtime.py",
         "_prescore_traced_check_impl", "subprocess.run"): ["/usr/bin/strace"],
        ("scripts/msae_independent_measurement_v3_post_m1_runtime.py", "broker", "os.execve"):
            [str(ROOT / ".venv-atlas/bin/python")],
        ("scripts/msae_independent_measurement_v3_post_m1_runtime.py",
         "_supervise_broker_process", "subprocess.Popen"):
            [str(ROOT / ".venv-atlas/bin/python")],
        ("scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
         "_prescore_traced_check_impl", "subprocess.run"): ["/usr/bin/strace"],
        ("scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py", "broker", "os.execve"):
            [str(ROOT / ".venv-atlas/bin/python")],
        ("scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
         "_supervise_broker_process", "subprocess.Popen"):
            [str(ROOT / ".venv-atlas/bin/python")],
    }
    dynamic_import_mappings = {
        ("scripts/msae_independent_measurement_v3_post_m1_runtime.py",
         "cpu_no_model_public_entry_trace", "runner_path"):
            ("scripts/run_msae_independent_calibration_v3.py",
             "scripts/run_msae_independent_calibration_v3.py"),
        ("scripts/msae_independent_measurement_v3_post_m1_runtime.py",
         "_rooted_generic_build_stage_a", "dependency_path"):
            ("scripts/msae_measurement_v2.py", "msae_measurement_v2.py"),
        ("scripts/msae_independent_measurement_v3_post_m1_runtime.py",
         "_rooted_generic_build_stage_a", "builder_path"):
            ("scripts/msae_measurement_remediation_v1.py",
             "msae_measurement_remediation_v1.py"),
        ("scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
         "_rooted_generic_protocol_config", "builder_path"):
            ("scripts/msae_independent_measurement_v3.py",
             "scripts/msae_independent_measurement_v3.py"),
        ("scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
         "_rebuild_generic_config_at_synthetic_root", "builder_path"):
            ("scripts/msae_independent_measurement_v3.py",
             "scripts/msae_independent_measurement_v3.py"),
        ("scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
         "cpu_no_model_public_entry_trace", "runner_path"):
            ("scripts/run_msae_independent_calibration_v3_gen3.py",
             "scripts/run_msae_independent_calibration_v3_gen3.py"),
        ("scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
         "_rooted_generic_build_stage_a", "dependency_path"):
            ("scripts/msae_measurement_v2.py", "msae_measurement_v2.py"),
        ("scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
         "_rooted_generic_build_stage_a", "builder_path"):
            ("scripts/msae_measurement_remediation_v1.py",
             "msae_measurement_remediation_v1.py"),
    }
    # The exact canonical paths are enumerated separately in the closure's
    # typed finite-file registry.  Sites bind this registry identifier rather
    # than broad directory prefixes; the behavioral trace checks every observed
    # request against the registry entries.
    dynamic_file_mapping = ["typed_registry:msae_v3_finite_file_registry_v1"]
    path_taking_helpers = _path_taking_local_helpers(root=root)
    while queue:
        relative = queue.pop(0)
        if relative in parsed:
            continue
        path = root / relative
        tree = ast.parse(path.read_text(encoding="utf-8"), filename=relative)
        parsed[relative] = tree
        scopes = [(node.lineno, node.end_lineno or node.lineno, node.name)
                  for node in ast.walk(tree)
                  if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))]
        def enclosing(line: int) -> str:
            candidates = [(end - start, name) for start, end, name in scopes
                          if start <= line <= end]
            return min(candidates)[1] if candidates else "<module>"
        assignments_by_scope: dict[str, dict[str, list[ast.AST]]] = collections.defaultdict(
            lambda: collections.defaultdict(list))
        for assignment in ast.walk(tree):
            if isinstance(assignment, (ast.Assign, ast.AnnAssign)) and assignment.value is not None:
                targets = assignment.targets if isinstance(assignment, ast.Assign) else [assignment.target]
                for target in targets:
                    if isinstance(target, ast.Name):
                        assignments_by_scope[enclosing(assignment.lineno)][target.id].append(
                            assignment.value)

        def statically_assigned_literals(expression: ast.AST | None,
                                          scope: str,
                                          seen: frozenset[str] = frozenset()) -> set[str]:
            if expression is None:
                return set()
            if isinstance(expression, ast.Constant) and isinstance(expression.value, str):
                return {expression.value}
            if (isinstance(expression, ast.Call)
                    and _qualified_call_name(expression.func) in {"Path", "pathlib.Path"}
                    and expression.args):
                return statically_assigned_literals(expression.args[0], scope, seen)
            if isinstance(expression, ast.Name) and expression.id not in seen:
                values = (assignments_by_scope[scope].get(expression.id, [])
                          or assignments_by_scope["<module>"].get(expression.id, []))
                return set().union(*(
                    statically_assigned_literals(value, scope, seen | {expression.id})
                    for value in values
                )) if values else set()
            if isinstance(expression, ast.BinOp) and isinstance(expression.op, ast.Div):
                left = statically_assigned_literals(expression.left, scope, seen)
                right = statically_assigned_literals(expression.right, scope, seen)
                return {str(Path(a) / b) for a in left for b in right}
            if isinstance(expression, ast.IfExp):
                return (statically_assigned_literals(expression.body, scope, seen)
                        | statically_assigned_literals(expression.orelse, scope, seen))
            return set()

        def assignment_origin_expressions(expression: ast.AST | None, scope: str,
                                          seen: frozenset[str] = frozenset()) -> set[str]:
            if expression is None:
                return set()
            result: set[str] = set()
            for name_node in (node for node in ast.walk(expression) if isinstance(node, ast.Name)):
                if name_node.id in seen:
                    continue
                values = (assignments_by_scope[scope].get(name_node.id, [])
                          or assignments_by_scope["<module>"].get(name_node.id, []))
                for value in values:
                    result.add(f"{name_node.id}={ast.unparse(value)}")
                    result.update(assignment_origin_expressions(
                        value, scope, seen | {name_node.id}))
            return result

        def assignment_origin_string_literals(
                expression: ast.AST | None, scope: str,
                seen: frozenset[str] = frozenset()) -> set[str]:
            if expression is None:
                return set()
            result = {node.value for node in ast.walk(expression)
                      if isinstance(node, ast.Constant) and isinstance(node.value, str)}
            for name_node in (node for node in ast.walk(expression)
                              if isinstance(node, ast.Name)):
                if name_node.id in seen:
                    continue
                values = (assignments_by_scope[scope].get(name_node.id, [])
                          or assignments_by_scope["<module>"].get(name_node.id, []))
                for value in values:
                    result.update(assignment_origin_string_literals(
                        value, scope, seen | {name_node.id}))
            return result
        dangerous_attributes = (process_calls | file_calls | library_calls | network_calls
                                | network_leaf_calls)
        dangerous_leaf_names = {value.rsplit(".", 1)[-1] for value in dangerous_attributes}
        call_aliases: dict[str, str] = {}
        module_aliases: dict[str, str] = {}
        for candidate in ast.walk(tree):
            if isinstance(candidate, ast.Import):
                for alias in candidate.names:
                    head = alias.name.split(".", 1)[0]
                    if head in {"subprocess", "os", "socket", "ctypes", "io", "pathlib", "importlib"}:
                        module_aliases[alias.asname or head] = head
            elif isinstance(candidate, ast.ImportFrom) and candidate.module == "pathlib":
                for alias in candidate.names:
                    if alias.name == "Path":
                        module_aliases[alias.asname or alias.name] = "Path"
        def normalize_call(value: str | None) -> str | None:
            if value is None:
                return None
            head, separator, tail = value.partition(".")
            replacement = module_aliases.get(head)
            return f"{replacement}{separator}{tail}" if replacement is not None else value
        for candidate in ast.walk(tree):
            if isinstance(candidate, (ast.Assign, ast.AnnAssign)):
                value = candidate.value
                qualified = normalize_call(_qualified_call_name(value)) if value is not None else None
                if qualified in dangerous_attributes:
                    targets = (candidate.targets if isinstance(candidate, ast.Assign)
                               else [candidate.target])
                    if len(targets) != 1 or not isinstance(targets[0], ast.Name):
                        raise ValueError(f"indirect dangerous-call alias is forbidden: "
                                         f"{relative}:{candidate.lineno}")
                    call_aliases[targets[0].id] = qualified
            elif isinstance(candidate, ast.ImportFrom) and candidate.module in {
                    "subprocess", "ctypes", "socket", "pathlib", "os", "io"}:
                for alias in candidate.names:
                    qualified = f"{candidate.module}.{alias.name}"
                    if qualified in dangerous_attributes:
                        call_aliases[alias.asname or alias.name] = qualified
        imports: list[tuple[str, int]] = []
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                imports.extend((alias.name, node.lineno) for alias in node.names)
            elif isinstance(node, ast.ImportFrom):
                if node.level:
                    raise ValueError(f"relative local import is not supported by frozen resolver: {relative}:{node.lineno}")
                if node.module:
                    imports.append((node.module, node.lineno))
            elif isinstance(node, ast.Call):
                name = normalize_call(_qualified_call_name(node.func))
                planted_probe_scope = (relative in {
                    "scripts/msae_independent_measurement_v3_post_m1_runtime.py",
                    "scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py"} and
                    enclosing(node.lineno) == "cpu_no_model_public_entry_trace")
                if isinstance(node.func, (ast.Call, ast.Subscript, ast.Lambda)) and not planted_probe_scope:
                    raise ValueError(f"unresolved dynamic callable is forbidden: {relative}:{node.lineno}")
                if name in {"eval", "exec", "compile"}:
                    raise ValueError(f"runtime code evaluation is forbidden: {relative}:{node.lineno}:{name}")
                if name == "getattr":
                    if len(node.args) < 2 or not isinstance(node.args[1], ast.Constant) or \
                            not isinstance(node.args[1].value, str):
                        allowed_dynamic_getattr = {
                            ("scripts/msae_independent_measurement_v3_post_m1.py", "__getattr__"),
                            ("scripts/msae_independent_measurement_v3_post_m1_runtime.py",
                             "verify_authorization"),
                            ("scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
                             "verify_authorization"),
                        }
                        if (relative, enclosing(node.lineno)) not in allowed_dynamic_getattr:
                            raise ValueError(f"dynamic getattr dispatch is forbidden: {relative}:{node.lineno}")
                    elif node.args[1].value in dangerous_leaf_names and not planted_probe_scope:
                        raise ValueError(f"indirect dangerous getattr is forbidden: "
                                         f"{relative}:{node.lineno}:{node.args[1].value}")
                if name in call_aliases:
                    name = call_aliases[name]
                if name in {"__import__", "importlib.import_module"}:
                    raise ValueError(f"dynamic import is forbidden: {relative}:{node.lineno}:{name}")
                if name in {"importlib.util.spec_from_file_location",
                            "continuation.source_only_module_spec"}:
                    scope = enclosing(node.lineno)
                    if len(node.args) < 2:
                        raise ValueError(
                            f"dynamic import lacks an exact path argument: {relative}:{node.lineno}")
                    argument_expression = ast.unparse(node.args[1])
                    mapping = dynamic_import_mappings.get(
                        (relative, scope, argument_expression))
                    if mapping is None:
                        raise ValueError(
                            f"dynamic import site lacks an exact mapping: "
                            f"{relative}:{scope}:{argument_expression}")
                    target, required_origin_literal = mapping
                    origin_literals = assignment_origin_string_literals(
                        node.args[1], scope)
                    if required_origin_literal not in origin_literals:
                        raise ValueError(
                            f"dynamic import target origin drift: {relative}:{scope}:"
                            f"{argument_expression}:{sorted(origin_literals)}")
                    dynamic_imports.append({"path": relative, "line": node.lineno,
                                            "operation": name,
                                            "argument_expression": argument_expression,
                                            "assignment_origin_literals": sorted(origin_literals),
                                            "finite_mapping": [target]})
                leaf = node.func.attr if isinstance(node.func, ast.Attribute) else None
                helper_leaf = (node.func.attr if isinstance(node.func, ast.Attribute)
                               else node.func.id if isinstance(node.func, ast.Name) else None)
                helper_path_bindings = path_taking_helpers.get(str(helper_leaf), ())
                helper_path_indices = tuple(index for index, _ in helper_path_bindings)
                category = ("process" if name in process_calls else
                            "file" if name in file_calls or
                            helper_path_indices or
                            (leaf in
                             {"open", "read_bytes", "read_text", "write_bytes", "write_text",
                              "unlink", "mkdir", "rename", "replace", "rmdir", "exists",
                              "is_file", "is_dir", "is_symlink", "stat", "lstat", "iterdir",
                              "rglob", "glob", "resolve", "ftruncate", "fchmod", "close",
                              "remove", "chmod", "readlink", "rmtree"}) else
                            "library" if name in library_calls else
                            "network" if name in network_calls or leaf in network_leaf_calls else None)
                if category is not None:
                    # This one function contains deliberately forbidden calls
                    # executed only after all real surfaces are monkeypatched;
                    # they are behavioral negative fixtures, never allowlist
                    # entries.
                    if planted_probe_scope:
                        continue
                    if name == "os.system" or any(keyword.arg == "shell" and
                                                   isinstance(keyword.value, ast.Constant) and
                                                   keyword.value.value is True
                                                   for keyword in node.keywords):
                        raise ValueError(f"shell expansion is forbidden: {relative}:{node.lineno}")
                    if category == "network" and name == "socket.socket" and (not node.args or
                            not isinstance(node.args[0], ast.Attribute) or
                            _qualified_call_name(node.args[0]) != "socket.AF_UNIX"):
                        raise ValueError(f"non-UNIX network surface is forbidden: {relative}:{node.lineno}")
                    literal = None
                    file_literal = None
                    scope = enclosing(node.lineno)
                    path_argument_index = helper_path_indices[0] if helper_path_indices else 0
                    path_argument: ast.AST | None = (
                        node.args[path_argument_index]
                        if len(node.args) > path_argument_index else None)
                    if path_argument is None and helper_path_bindings:
                        keyword_names = {name for index, name in helper_path_bindings
                                         if index == path_argument_index}
                        matches = [keyword.value for keyword in node.keywords
                                   if keyword.arg in keyword_names]
                        if len(matches) == 1:
                            path_argument = matches[0]
                    if (path_argument is None and category == "file"
                            and isinstance(node.func, ast.Attribute)
                            and not (name or "").startswith(("os.", "io."))):
                        path_argument = node.func.value
                    if path_argument is not None:
                        first = path_argument
                        if isinstance(first, ast.Constant) and isinstance(first.value, (str, type(None))):
                            literal = first.value
                        elif (isinstance(first, (ast.List, ast.Tuple)) and first.elts
                              and isinstance(first.elts[0], ast.Constant)
                              and isinstance(first.elts[0].value, (str, type(None)))):
                            literal = first.elts[0].value
                        elif (isinstance(first, ast.Call)
                              and _qualified_call_name(first.func) in {"Path", "pathlib.Path"}
                              and first.args and isinstance(first.args[0], ast.Constant)
                              and isinstance(first.args[0].value, str)):
                            literal = first.args[0].value
                    receiver_literal = None
                    if (category == "file" and isinstance(node.func, ast.Attribute)
                            and isinstance(node.func.value, ast.Call)
                            and _qualified_call_name(node.func.value.func) == "Path"
                            and node.func.value.args
                            and isinstance(node.func.value.args[0], ast.Constant)
                            and isinstance(node.func.value.args[0].value, str)):
                        receiver_literal = node.func.value.args[0].value
                    file_literal = receiver_literal if receiver_literal is not None else literal
                    if (category == "file" and isinstance(file_literal, str)
                            and os.path.isabs(file_literal)
                            and file_literal not in allowed_absolute_file_literals):
                        raise ValueError(f"absolute file literal is outside the typed finite registry: "
                                         f"{relative}:{node.lineno}:{file_literal}")
                    assigned_literals = statically_assigned_literals(path_argument, scope)
                    forbidden_assigned = sorted(
                        value for value in assigned_literals
                        if os.path.isabs(value) and value not in allowed_absolute_file_literals
                    )
                    if forbidden_assigned and not planted_probe_scope:
                        raise ValueError(
                            "dynamic file value has an assigned literal outside the finite registry: "
                            f"{relative}:{scope}:{node.lineno}:{forbidden_assigned}")
                    if category == "process" and literal is not None:
                        if not isinstance(literal, str) or literal not in allowed_process_literals:
                            raise ValueError(
                                f"process target is outside the static allowlist: "
                                f"{relative}:{node.lineno}:{literal!r}")
                    if category == "library" and literal is not None:
                        raise ValueError(
                            f"literal dlopen target is outside the distribution/ELF closure: "
                            f"{relative}:{node.lineno}:{literal!r}")
                    finite_mapping: list[Any]
                    if category == "file":
                        finite_mapping = dynamic_file_mapping
                    elif category == "process":
                        finite_mapping = ["typed_registry:msae_v3_finite_process_registry_v1"]
                    elif category == "network":
                        finite_mapping = (["AF_UNIX"] if name == "socket.socket" else
                                          ["typed_registry:unix_socket_path_or_bound_socket"])
                    elif category == "library":
                        if not node.args or not isinstance(node.args[0], ast.Constant) or node.args[0].value is not None:
                            raise ValueError(
                                f"dynamic dlopen site lacks a finite mapping: {relative}:{node.lineno}")
                        finite_mapping = ["process_global_libc"]
                    else:
                        finite_mapping = dynamic_file_mapping
                    site_payload = {"path": relative, "function": scope,
                                    "category": category,
                                    "operation": name if name is not None else f"<dynamic>.{leaf}",
                                    "receiver_expression": (ast.unparse(node.func.value)
                                                            if isinstance(node.func, ast.Attribute)
                                                            else None),
                                    "argument_expression": (
                                        ast.unparse(path_argument)
                                        if path_argument is not None else None),
                                    "assignment_origin_expressions": sorted(
                                        assignment_origin_expressions(path_argument, scope))}
                    site_id = base.sha_bytes(base.canonical_bytes(site_payload))
                    if category == "file" and file_literal is None:
                        if site_id not in FROZEN_DYNAMIC_FILE_SITE_BINDING_IDS:
                            raise ValueError(
                                "dynamic file site lacks a reviewed typed-field binding: "
                                f"{relative}:{scope}:{node.lineno}:{site_id}")
                        descriptor_operations = {
                            "os.read", "os.write", "os.lseek", "os.fstat", "os.fsync",
                            "os.ftruncate", "os.fchmod", "os.close",
                        }
                        mapping_provenance = (
                            "held_descriptor_from_registered_path_or_inherited_gate"
                            if site_payload["operation"] in descriptor_operations
                            else FROZEN_DYNAMIC_FILE_SITE_BINDING_SOURCE
                        )
                        finite_mapping = [
                            "typed_registry:msae_v3_finite_file_registry_v1",
                            f"reviewed_site:{site_id}",
                            f"mapping_source:{mapping_provenance}",
                        ]
                    elif category != "file":
                        if site_id not in FROZEN_NONFILE_SURFACE_SITE_BINDING_IDS:
                            raise ValueError(
                                "dangerous non-file site lacks a reviewed finite binding: "
                                f"{relative}:{scope}:{node.lineno}:{site_id}")
                        finite_mapping = [*finite_mapping, f"reviewed_site:{site_id}"]
                    surfaces.append({"path": relative, "line": node.lineno,
                                     "function": scope,
                                     "category": category,
                                     "operation": name if name is not None else f"<dynamic>.{leaf}",
                                     "receiver_expression": site_payload["receiver_expression"],
                                     "argument_expression": site_payload["argument_expression"],
                                     "assignment_origin_expressions":
                                         site_payload["assignment_origin_expressions"],
                                     "literal_first_argument": literal,
                                     "resolved_file_literal": file_literal if category == "file" else None,
                                     "finite_mapping_site_id": site_id,
                                     "finite_mapping": finite_mapping,
                                     "dynamic_value_policy": ("typed_finite_mapping" if
                                                               category in {"file", "process"} or literal is None
                                                               else "literal")})
        for module, line in imports:
            top = module.split(".", 1)[0]
            local = _local_import_path(module, root=root) or _local_import_path(top, root=root)
            if local is not None:
                import_edges.append({"from": relative, "module": module, "to": local,
                                     "line": str(line)})
                queue.append(local)
            elif top not in sys.stdlib_module_names:
                external_modules.add(top)
    local_modules = sorted(parsed, key=lambda value: value.encode("utf-8"))
    expected_source_only_modules = {
        Path(relative).stem for relative in LOCAL_PYTHON_ENTRYPOINTS
    }

    def frozen_string_set(relative: str, constant_name: str) -> set[str]:
        assignments = [node for node in ast.walk(parsed[relative])
                       if isinstance(node, ast.Assign)
                       and any(isinstance(target, ast.Name)
                               and target.id == constant_name for target in node.targets)]
        if len(assignments) != 1:
            raise ValueError(f"source-only module registry assignment drift: {relative}")
        value = assignments[0].value
        if (not isinstance(value, ast.Call) or not isinstance(value.func, ast.Name)
                or value.func.id != "frozenset" or len(value.args) != 1
                or not isinstance(value.args[0], ast.Set)
                or any(not isinstance(item, ast.Constant) or not isinstance(item.value, str)
                       for item in value.args[0].elts)):
            raise ValueError(f"source-only module registry is not inert: {relative}")
        return {str(item.value) for item in value.args[0].elts
                if isinstance(item, ast.Constant)}

    controller_source_only = frozen_string_set(
        "scripts/msae_independent_measurement_v3_post_m2_gen3.py",
        "SOURCE_ONLY_LOCAL_MODULES")
    runner_source_only = frozen_string_set(
        "scripts/run_msae_independent_calibration_v3_gen3.py",
        "_SOURCE_ONLY_LOCAL_MODULES")
    if (controller_source_only != expected_source_only_modules
            or runner_source_only != expected_source_only_modules):
        raise ValueError("source-only local-module registry does not equal the closure")
    source_only_policy = {
        "schema_version": "msae_v3_source_only_local_imports_v1",
        "modules": sorted(expected_source_only_modules),
        "controller_bootstrap":
            "scripts/msae_independent_measurement_v3_post_m2_gen3.py",
        "runner_bootstrap": "scripts/run_msae_independent_calibration_v3_gen3.py",
        "bytecode_cache_reads": False,
        "default_scripts_directory_search": False,
        "ignored_sourceless_or_extension_shadowing": False,
        "loader_policy": "descriptor_safe_source_file_loader_with_path_stats_failure",
    }
    for relative in (
        "scripts/msae_independent_measurement_v3_post_m2_gen3.py",
        "scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
        "scripts/run_msae_independent_calibration_v3_gen3.py",
    ):
        for node in ast.walk(parsed[relative]):
            if (isinstance(node, ast.Call)
                    and _qualified_call_name(node.func) == "sys.path.insert"):
                raise ValueError(
                    f"successor leaves default local scripts-path import enabled: {relative}")
    import_edges.sort(key=lambda row: (row["from"], row["line"], row["module"], row["to"]))
    surfaces.sort(key=lambda row: (row["path"], row["line"], row["category"], str(row["operation"])))
    dynamic_imports.sort(key=lambda row: (row["path"], row["line"]))
    dynamic_file_sites = [{key: row[key] for key in
                           ("path", "function", "operation", "receiver_expression",
                            "argument_expression", "assignment_origin_expressions",
                            "finite_mapping_site_id")}
                          for row in surfaces if row["category"] == "file"
                          and row["resolved_file_literal"] is None]
    dynamic_file_site_set_sha256 = base.sha_bytes(base.canonical_bytes(dynamic_file_sites))
    if dynamic_file_site_set_sha256 != FROZEN_DYNAMIC_FILE_SITE_SET_SHA256:
        raise ValueError(f"dynamic file site set drift: {dynamic_file_site_set_sha256}")
    surface_set = [{key: row[key] for key in
                    ("path", "function", "category", "operation", "receiver_expression",
                     "argument_expression", "assignment_origin_expressions",
                     "literal_first_argument", "finite_mapping",
                     "dynamic_value_policy", "finite_mapping_site_id")}
                   for row in surfaces]
    surface_set_sha256 = base.sha_bytes(base.canonical_bytes(surface_set))
    if surface_set_sha256 != FROZEN_STATIC_SURFACE_SET_SHA256:
        raise ValueError(f"static file/process/library/network surface set drift: {surface_set_sha256}")
    value_flow_ast_sha256 = _normalized_local_value_flow_ast_sha256(root=root)
    if value_flow_ast_sha256 != FROZEN_LOCAL_VALUE_FLOW_AST_SHA256:
        raise ValueError(f"local value-flow AST ledger drift: {value_flow_ast_sha256}")
    return {"schema_version": "msae_v3_static_closure_analysis_v1",
            "entrypoints": list(LOCAL_PYTHON_ENTRYPOINTS), "local_modules": local_modules,
            "local_import_edges": import_edges,
            "third_party_import_roots": sorted(external_modules),
            "dynamic_import_mappings": dynamic_imports,
            "source_only_local_import_policy": source_only_policy,
            "dynamic_file_sites": dynamic_file_sites,
            "dynamic_file_site_set_sha256": dynamic_file_site_set_sha256,
            "surface_calls": surfaces,
            "surface_set_sha256": surface_set_sha256,
            "local_value_flow_ast_sha256": value_flow_ast_sha256,
            "allowed_process_argv0": sorted(allowed_process_literals),
            "allowed_network_families": ["AF_UNIX"], "shell_expansion_allowed": False}


def _static_runtime_distribution_roots(*, root: Path = ROOT) -> list[str]:
    """Mechanically map third-party imports from the recursive local graph."""
    third_party = set(_static_closure_analysis(root=root)["third_party_import_roots"])
    package_map = importlib.metadata.packages_distributions()
    roots: set[str] = set()
    for module in sorted(third_party):
        candidates = package_map.get(module)
        normalized = {item.lower().replace("_", "-") for item in candidates or []}
        if len(normalized) != 1:
            raise ValueError(f"cannot uniquely map imported module to distribution: {module}:{candidates}")
        roots.add(next(iter(normalized)))
    # Torch may dispatch into Triton without a literal Python import in the
    # runner. Its system metadata has optional-only requirements, so bind it
    # as an explicit runtime root.
    roots.add("triton")
    return sorted(roots, key=lambda value: value.lower().replace("_", "-"))


PUBLIC_EXECUTION_ENTRYPOINTS = (
    "setup_m3", "build_m4", "verify_post_m3_review", "verify_candidate_manifest",
    "prescore_traced_check", "verify_prescore_trace", "sign_authorization", "launch",
    "broker", "supervise_broker", "runner.run", "checkpoint_registry",
    "endpoint_registry", "validate_endpoint_registry", "closure_payload",
    "environment_payload", "verify_dependency_closure", "verify_runtime_loaded_libraries",
    "validate_stage_a", "verify_authorization", "validate_runner_readiness",
    "commit_terminal_failure", "commit_terminal_success", "confirm_pre_model_gate",
    "worker_environment", "validate_stage_b_typed_qa", "dispatch",
    "controller.main",
)


class _SurfaceProbeBlocked(RuntimeError):
    pass


class _SurfaceProbeViolation(RuntimeError):
    pass


def _surface_logical_path(value: Any, *, root: Path) -> str:
    try:
        absolute = Path(os.path.abspath(os.fsdecode(os.fspath(value))))
    except TypeError:
        return "<nonpath>"
    try:
        relative = absolute.relative_to(root).as_posix()
        return "repo://" + ("" if relative == "." else relative)
    except ValueError:
        pass
    return str(absolute)


def _surface_file_registry(*, root: Path, checkpoints: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    """Complete exact paths plus typed runtime-field-derived templates."""
    import gettext
    relatives = set(_candidate_relatives(include_m4=True, root=root, checkpoints=checkpoints))
    protected_root = root / V3_DATA.relative_to(ROOT)
    for name in ("data_baseline_manifest.json", "protected_v1_manifest.json",
                 "protected_v2_manifest.json"):
        manifest = base.strict_json_loads((protected_root / name).read_text(encoding="utf-8"))
        relatives.update(str(row["path"]) for row in manifest.get("entries", [])
                         if row.get("path") not in base.QUARANTINED)
    # Every file and every ancestor directory is enumerated; there is no
    # arbitrary repository-directory prefix permission.
    repository_relatives = set(relatives)
    for relative in list(relatives):
        parent = Path(relative).parent
        while str(parent) not in {"", "."}:
            repository_relatives.add(parent.as_posix())
            parent = parent.parent
    repository_relatives.add("")

    run_names = {
        "", "authorization.json", "launcher_intent.json", "logs", "logs/broker.log", "logs/worker.log",
        "broker.sock", "lock_acquired.json", "handoff.json", "nonce_consumed.json",
        "observed_environment.json", "tolerance_selection.json",
        "cached_noop_hash_replay.json", "canonical_pooling_qa.json",
        "counterfactual_cache_alignment_qa.json", "terminal.claim", "cache",
        ".terminal_failure_staging", "terminal_failure",
        ".terminal_failure_staging/technical_failure.json",
        ".terminal_failure_staging/status.json", "terminal_failure/technical_failure.json",
        "terminal_failure/status.json", ".terminal_success_staging", "terminal_success",
    }
    terminal_names = {"stage_b.json", "status.json", "runtime_native_pre_import.json",
                      "runtime_native_post_torch.json", "runtime_native_post_model.json",
                      "runtime_native_final.json"}
    for directory in (".terminal_success_staging", "terminal_success"):
        run_names.update(f"{directory}/{name}" for name in terminal_names)
    for sid in ("main_long", "main_short", "pair_context", "pair_entity"):
        run_names.add(f"cache/{sid}")
        run_names.add(f"cache/{sid}/pooling_per_unit.npy")
        run_names.update(f"cache/{sid}/forward_{index}.npy" for index in range(4))
    repository_relatives.update(
        (Path(ACTIVE_RUN_REL) / name).as_posix() if name else ACTIVE_RUN_REL
        for name in run_names)
    repository_relatives.update({
        str(PRESCORE_REVIEW.relative_to(ROOT)),
        M4_NEW[-1],
        str(M4_TRANSACTION.relative_to(ROOT)),
        *(str(M4_TRANSACTION.relative_to(ROOT) / f"{index:02d}.payload")
          for index in range(len(M4_NEW))),
        str(M4_TRANSACTION.relative_to(ROOT) / "transaction.json"),
    })

    exact = {"repo://" + relative for relative in repository_relatives}
    anchor = ROOT.parent
    while str(anchor) != str(anchor.parent):
        exact.add(str(anchor)); anchor = anchor.parent
    exact.add("/")
    exact.update({str(ACTIVE_PRIVATE_KEY), str(ACTIVE_PRIVATE_KEY.parent),
                  str(ACTIVE_STATE), str(ACTIVE_NONCE_DIR), str(base.GPU_LOCK_DIR),
                  "/usr/bin/bash", "/usr/bin/git", "/usr/bin/ldd", "/usr/bin/nvidia-smi",
                  "/usr/bin/strace", "/usr/bin/tmux", str(ROOT / ".venv-atlas/bin/python"),
                  "/proc/self/maps", "/dev/null",
                  "/tmp/msae_surface_probe_check.json", "/tmp/msae_surface_probe_trace.log"})
    exact.update({
        "/tmp/msae_independent_measurement_v3_gen2_failure_reproduction",
        ("/tmp/msae_independent_measurement_v3_gen2_failure_reproduction/"
         ".venv-atlas/bin/python"),
    })
    for language in gettext._expand_lang("C.UTF-8"):  # type: ignore[attr-defined]
        for localedir in (gettext._default_localedir, "/usr/share/locale-langpack"):  # type: ignore[attr-defined]
            exact.add(str(Path(localedir) / language / "LC_MESSAGES/messages.mo"))
    exact.add(str(base.SNAPSHOT))
    for path in base.SNAPSHOT.iterdir():
        exact.add(str(path))
        exact.add(str(path.resolve(strict=True)))
    # Both independent M4 roots receive the complete exact relative projection.
    for build_root in (M4_PRIMARY, M4_REBUILD):
        exact.add(str(build_root))
        exact.update(str(build_root / relative) for relative in repository_relatives)
    # Lexical realpath resolution performs lstat on each ancestor. Enumerate
    # those exact ancestors rather than granting a directory prefix.
    for raw in list(exact):
        if raw.startswith(("repo://", "fd://")):
            continue
        parent = Path(raw)
        while str(parent) != str(parent.parent):
            parent = parent.parent
            exact.add(str(parent))
        exact.add("/")
    templates = [
        {"id": "nonce_record_from_authorization_digest",
         "pattern": re.escape(str(ACTIVE_NONCE_DIR)) + r"/[0-9a-f]{64}\.consumed",
         "source": "signed_authorization_file_sha256"},
        {"id": "gpu_lock_from_uuid_digest",
         "pattern": re.escape(str(base.GPU_LOCK_DIR)) + r"/[0-9a-f]{64}\.lock",
         "source": "selected_gpu_uuid_sha256"},
        {"id": "proc_pid_stat_from_bound_pid",
         "pattern": r"/proc/[1-9][0-9]*/stat", "source": "bound_process_identity"},
        {"id": "proc_fd_from_inherited_descriptor",
         "pattern": r"/proc/self/fd/[0-9]+", "source": "inherited_descriptor"},
        {"id": "manifest_digest_prescore_check",
         "pattern": r"/tmp/msae_independent_measurement_v3_post_m2_gen3_[0-9a-f]{64}\.prescore\.check\.json",
         "source": "candidate_manifest_sha256"},
        {"id": "manifest_digest_prescore_trace",
         "pattern": r"/tmp/msae_independent_measurement_v3_post_m2_gen3_[0-9a-f]{64}\.prescore\.trace\.log",
         "source": "candidate_manifest_sha256"},
        {"id": "stage_a_digest_tmux_socket",
         "pattern": r"/tmp/msae_independent_measurement_v3_post_m2_gen3_[0-9a-f]{64}\.sock",
         "source": "stage_a_sha256"},
    ]
    value = {"schema_version": "msae_v3_finite_file_registry_v1",
             "exact_logical_paths": sorted(exact), "templates": templates}
    value["registry_sha256"] = base.sha_bytes(base.canonical_bytes(value))
    return value


def _finite_process_registry() -> dict[str, Any]:
    exact_argv = [
        {"id": "git_status_porcelain",
         "argv": ["/usr/bin/git", "status", "--porcelain=v2", "--untracked-files=all"]},
        {"id": "nvidia_compute_process_query",
         "argv": ["/usr/bin/nvidia-smi", "--query-compute-apps=gpu_uuid,pid",
                  "--format=csv,noheader,nounits"]},
        {"id": "nvidia_idle_gpu_query",
         "argv": ["/usr/bin/nvidia-smi", "--query-gpu=index,uuid,memory.used,utilization.gpu",
                  "--format=csv,noheader,nounits"]},
    ]
    value = {
        "schema_version": "msae_v3_finite_process_registry_v1",
        "exact_argv": sorted(exact_argv, key=lambda row: row["id"]),
        "templates": [
            {"id": "ldd_bound_elf", "argv": ["/usr/bin/ldd", "{closure_elf_path}"]},
            {"id": "strace_prescore", "source": "held_check_trace_fds+candidate_controller"},
            {"id": "tmux_session_control", "source": "stage_a_sha256+fixed_session+broker_argv"},
            {"id": "isolated_python_broker",
             "source": "fixed_controller+socket+gpu_uuid+index+launcher_capability+intent"},
            {"id": "isolated_python_worker_execve",
             "operation": "os.execve",
             "argv": [str(ROOT / ".venv-atlas/bin/python"), "-S", "-B", "-I",
                      str(RUNNER), "--run-root", ACTIVE_RUN_REL,
                      "--gpu-uuid", "{selected_gpu_uuid}",
                      "--broker-pid", "{bound_broker_pid}",
                      "--readiness-fd", "{inherited_readiness_fd}",
                      "--final-ack-fd", "{inherited_final_ack_fd}",
                      "--confirmed-fd", "{inherited_confirmation_fd}"],
             "environment": {
                 "exact_static": {**FROZEN_BASE_PROCESS_ENVIRONMENT,
                                  **FROZEN_WORKER_ENVIRONMENT},
                 "typed_dynamic": {
                     "CUDA_VISIBLE_DEVICES": "{selected_gpu_uuid}",
                     "MSAE_GPU_UUID": "{selected_gpu_uuid}",
                     "MSAE_LEASE_FD": "{inherited_lease_fd}",
                     "MSAE_READINESS_FD": "{inherited_readiness_fd}",
                     "MSAE_FINAL_ACK_FD": "{inherited_final_ack_fd}",
                     "MSAE_CONFIRMED_FD": "{inherited_confirmation_fd}",
                 },
                 "inherit_parent_environment": False,
             }},
        ],
    }
    value["registry_sha256"] = base.sha_bytes(base.canonical_bytes(value))
    return value


def _trace_review_gates(root: Path, plan_review_sha256: str,
                        implementation_review_sha256: str) -> dict[str, Any]:
    return {
        "plan_sha256": FROZEN_PLAN_SHA256,
        "plan_entry": _regular_entry(root / PLAN_PATH.relative_to(ROOT), root=root),
        "plan_review_sha256": plan_review_sha256,
        "plan_review_entry": _regular_entry(root / PLAN_REVIEW.relative_to(ROOT), root=root),
        "implementation_review_sha256": implementation_review_sha256,
        "implementation_review_entry": _regular_entry(
            root / IMPLEMENTATION_REVIEW.relative_to(ROOT), root=root),
    }


def cpu_no_model_public_entry_trace(
    *,
    root: Path = ROOT,
    extra_probes: Sequence[tuple[str, Any]] = (),
    review_gates: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Tripwire all public execution entrypoints without model/GPU work."""
    import argparse
    import builtins
    import ctypes
    import io as io_module
    import unittest.mock as mock

    if root != ROOT:
        raise ValueError("behavioral CPU trace must execute in the live candidate root")
    # Verify the complete local source/value-flow ledger before importing the
    # runner.  Otherwise module-level code in a drifted runner could execute
    # outside the behavioral tripwires before the static gate noticed it.
    static_analysis = _static_closure_analysis(root=root)
    original_os_close = os.close
    original_os_lstat = os.lstat
    original_os_stat = os.stat
    gate_r, gate_w = os.pipe()
    confirmed_r, confirmed_w = os.pipe()
    descriptor_labels = {
        gate_r: "fd://pre_model_gate_read", gate_w: "fd://pre_model_gate_write",
        confirmed_r: "fd://model_gate_confirmation_read",
        confirmed_w: "fd://model_gate_confirmation_write",
    }

    runner_path = root / RUNNER.relative_to(ROOT)
    runner_spec = continuation.source_only_module_spec(
        "_msae_v3_surface_probe_runner", runner_path)
    if runner_spec is None or runner_spec.loader is None:
        raise ValueError("cannot load runner for CPU surface trace")
    runner_module = importlib.util.module_from_spec(runner_spec)
    runner_spec.loader.exec_module(runner_module)
    import numpy  # noqa: F401 -- permitted CPU-only dependency realization.

    checkpoints = checkpoint_registry(root=root)
    file_registry = _surface_file_registry(root=root, checkpoints=checkpoints)
    file_registry["exact_logical_paths"] = sorted(
        set(file_registry["exact_logical_paths"]) | set(descriptor_labels.values()))
    file_registry.pop("registry_sha256")
    file_registry["registry_sha256"] = base.sha_bytes(base.canonical_bytes(file_registry))
    exact_paths = set(file_registry["exact_logical_paths"])
    templates = [(row["id"], re.compile(row["pattern"], re.ASCII))
                 for row in file_registry["templates"]]
    forbidden = {"repo://" + relative for relative in base.QUARANTINED}
    static_categories = {row["category"] for row in static_analysis["surface_calls"]}
    allowed_requests: list[dict[str, Any]] = []
    violation_requests: list[dict[str, Any]] = []

    dummy_uuid = "GPU-1234567890abcdef"
    dummy_socket = str(ACTIVE_RUN_ROOT / "broker.sock")
    dummy_launch_capability = "a" * 64
    dummy_intent_sha256 = "b" * 64
    controller = str(root / continuation.CONTROLLER_PATH.relative_to(ROOT))
    runner_executable = str(root / RUNNER.relative_to(ROOT))
    python = str(ROOT / ".venv-atlas/bin/python")
    process_registry = _finite_process_registry()
    exact_argv_by_id = {str(row["id"]): tuple(str(item) for item in row["argv"])
                        for row in process_registry["exact_argv"]}

    stage_socket_pattern = re.compile(
        r"/tmp/msae_independent_measurement_v3_post_m2_gen3_[0-9a-f]{64}\.sock", re.ASCII)
    evidence_fd_pattern = re.compile(r"/proc/self/fd/[0-9]+", re.ASCII)

    def isolated_python_vector_allowed(vector: tuple[str, ...], command: str) -> bool:
        return (len(vector) == 16
                and vector[:5] == (python, "-S", "-B", "-I", controller)
                and vector[5] == command and vector[6] == "--socket"
                and vector[7] == dummy_socket and vector[8] == "--gpu-uuid"
                and re.fullmatch(r"GPU-[0-9A-Fa-f-]{16,}", vector[9], re.ASCII) is not None
                and vector[10] == "--gpu-index" and vector[11].isdecimal()
                and vector[12] == "--launch-capability"
                and re.fullmatch(r"[0-9a-f]{64}", vector[13], re.ASCII) is not None
                and vector[14] == "--intent-sha256"
                and re.fullmatch(r"[0-9a-f]{64}", vector[15], re.ASCII) is not None)

    def worker_python_vector_allowed(vector: tuple[str, ...]) -> bool:
        return (len(vector) == 17 and vector[:5] ==
                (python, "-S", "-B", "-I", runner_executable)
                and vector[5:7] == ("--run-root", ACTIVE_RUN_REL)
                and vector[7] == "--gpu-uuid"
                and re.fullmatch(r"GPU-[0-9A-Fa-f-]{16,}", vector[8], re.ASCII) is not None
                and vector[9] == "--broker-pid" and vector[10].isdecimal()
                and vector[11] == "--readiness-fd" and vector[12].isdecimal()
                and vector[13] == "--final-ack-fd" and vector[14].isdecimal()
                and vector[15] == "--confirmed-fd" and vector[16].isdecimal())

    def process_vector_registry_ids(vector: tuple[str, ...]) -> list[str]:
        matches = [entry_id for entry_id, registered in exact_argv_by_id.items()
                   if vector == registered]
        if len(vector) == 2 and vector[0] == "/usr/bin/ldd":
            if allowed_path(_surface_logical_path(vector[1], root=root)):
                matches.append("ldd_bound_elf")
        if (len(vector) == 18 and vector[:9] ==
                ("/usr/bin/strace", "-f", "-qq", "-yy", "-s", "4096", "-e",
                 "trace=open,openat,openat2,creat", "-o")
                and evidence_fd_pattern.fullmatch(vector[9])
                and vector[10:14] == (python, "-S", "-B", "-I")
                and vector[14] == controller and vector[15] == "prescore-check"
                and vector[16] == "--output-fd"):
            if vector[17].isdecimal():
                matches.append("strace_prescore")
        if isolated_python_vector_allowed(vector, "broker"):
            matches.append("isolated_python_broker")
        if worker_python_vector_allowed(vector):
            matches.append("isolated_python_worker_execve")
        if vector and vector[0] == "/usr/bin/tmux":
            if (len(vector) >= 6 and vector[1:4] == ("-f", "/dev/null", "-S")
                    and stage_socket_pattern.fullmatch(vector[4])):
                tail = vector[5:]
            elif (len(vector) >= 4 and vector[1] == "-S"
                  and stage_socket_pattern.fullmatch(vector[2])):
                tail = vector[3:]
            else:
                return matches
            if tail in {("has-session", "-t", "msae-independent-v3-gen3-calibration"),
                        ("kill-session", "-t", "msae-independent-v3-gen3-calibration")}:
                matches.append("tmux_session_control")
            elif tail == ("display-message", "-p", "-t", "msae-independent-v3-gen3-calibration",
                          "#{pane_pid}"):
                matches.append("tmux_session_control")
            elif (len(tail) == 9 and tail[:5] ==
                    ("new-session", "-d", "-s", "msae-independent-v3-gen3-calibration",
                     "/usr/bin/bash")
                    and tail[5:8] == ("--noprofile", "--norc", "-c")
                    and tail[8].startswith("exec ")):
                # The one shell string is generated with shlex.join from the
                # exact isolated-python supervisor argv, not arbitrary input.
                command = tail[8]
                if (command.startswith("exec ") and isolated_python_vector_allowed(
                        tuple(shlex.split(command.removeprefix("exec "))), "supervise-broker")):
                    matches.append("tmux_session_control")
        return matches

    def allowed_path(logical: str) -> bool:
        return logical in exact_paths or any(pattern.fullmatch(logical) for _, pattern in templates)

    def file_probe(operation: str, *, descriptor: bool = False):
        def blocked(value: Any = "<implicit>", *args: Any, **kwargs: Any) -> Any:
            if descriptor and isinstance(value, int):
                logical = descriptor_labels.get(value, f"fd://unregistered:{value}")
            elif kwargs.get("dir_fd") == 42 and isinstance(value, (str, bytes, os.PathLike)):
                logical = str(ACTIVE_NONCE_DIR / os.fsdecode(os.fspath(value)))
            elif kwargs.get("dir_fd") == 43 and isinstance(value, (str, bytes, os.PathLike)):
                logical = str(base.GPU_LOCK_DIR / os.fsdecode(os.fspath(value)))
            else:
                logical = _surface_logical_path(value, root=root)
            request = {"category": "file", "operation": operation, "logical_path": logical}
            if logical in forbidden and operation in {"Path.lstat", "os.lstat"}:
                request["verification_action"] = "lstat_only_against_frozen_v1_evidence"
                allowed_requests.append(request)
                return original_os_lstat(value)
            if logical in forbidden or not allowed_path(logical):
                violation_requests.append(request)
                raise _SurfaceProbeViolation(f"file request outside finite mapping: {logical}")
            allowed_requests.append(request)
            if operation == "os.lstat":
                return original_os_lstat(value, *args, **kwargs)
            if operation == "os.stat":
                return original_os_stat(value, *args, **kwargs)
            raise _SurfaceProbeBlocked(operation)
        return blocked

    def process_probe(operation: str):
        def blocked(argv: Any, *args: Any, **kwargs: Any) -> Any:
            environment = None
            if operation in {"os.execve", "os.execv"}:
                executable = os.fsdecode(os.fspath(argv))
                if not args:
                    vector = ()
                else:
                    vector = tuple(os.fsdecode(os.fspath(item)) for item in list(args[0]))
                if operation == "os.execve" and len(args) > 1:
                    environment = dict(args[1])
                executable_matches = bool(vector) and executable == vector[0]
            elif isinstance(argv, (str, bytes, os.PathLike)):
                vector = (os.fsdecode(os.fspath(argv)),)
                executable_matches = True
            else:
                vector = tuple(os.fsdecode(os.fspath(item)) for item in list(argv))
                executable_matches = True
            request = {"category": "process", "operation": operation, "argv": list(vector),
                       "shell": bool(kwargs.get("shell", False))}
            if environment is not None:
                request["environment_keys"] = sorted(environment)
                expected_keys = set(FROZEN_BASE_PROCESS_ENVIRONMENT) | set(FROZEN_WORKER_ENVIRONMENT) | {
                    "CUDA_VISIBLE_DEVICES", "MSAE_LEASE_FD", "MSAE_GPU_UUID",
                    "MSAE_READINESS_FD", "MSAE_FINAL_ACK_FD", "MSAE_CONFIRMED_FD"}
                environment_ok = (set(environment) == expected_keys
                                  and environment.get("CUDA_VISIBLE_DEVICES") ==
                                      environment.get("MSAE_GPU_UUID"))
            else:
                environment_ok = True
            registry_ids = process_vector_registry_ids(vector)
            request["registry_entry_ids"] = registry_ids
            if (kwargs.get("shell") is True or not executable_matches or not environment_ok
                    or len(registry_ids) != 1):
                violation_requests.append(request)
                raise _SurfaceProbeViolation(f"process argv outside finite mapping: {vector!r}")
            allowed_requests.append(request)
            raise _SurfaceProbeBlocked(operation)
        return blocked

    def socket_probe(family: Any = socket.AF_INET, *args: Any, **kwargs: Any) -> Any:
        request = {"category": "network", "operation": "socket.socket", "family": family}
        if family != socket.AF_UNIX:
            violation_requests.append(request)
            raise _SurfaceProbeViolation(f"network family outside finite mapping: {family}")
        allowed_requests.append(request)
        raise _SurfaceProbeBlocked("socket.socket")

    def connection_probe(address: Any, *args: Any, **kwargs: Any) -> Any:
        request = {"category": "network", "operation": "socket.create_connection",
                   "address": repr(address)}
        violation_requests.append(request)
        raise _SurfaceProbeViolation("IP/network connections are forbidden")

    def library_probe(name: Any, *args: Any, **kwargs: Any) -> Any:
        request = {"category": "library", "operation": "ctypes.dlopen", "name": name}
        if name is not None:
            violation_requests.append(request)
            raise _SurfaceProbeViolation(f"library request outside finite mapping: {name}")
        allowed_requests.append(request)
        raise _SurfaceProbeBlocked("ctypes.CDLL")

    original_import = builtins.__import__
    def import_probe(name: str, *args: Any, **kwargs: Any) -> Any:
        if name.split(".", 1)[0] in {"torch", "transformers"}:
            request = {"category": "model_import", "operation": "__import__", "name": name}
            violation_requests.append(request)
            raise _SurfaceProbeViolation(f"model import during CPU trace: {name}")
        return original_import(name, *args, **kwargs)

    manifest_path = ACTIVE_PROV / "prescore_candidate_manifest.json"
    check_path = Path("/tmp/msae_surface_probe_check.json")
    trace_path = Path("/tmp/msae_surface_probe_trace.log")
    probe_args = argparse.Namespace(run_root=ACTIVE_RUN_REL, gpu_uuid=dummy_uuid, broker_pid=2,
                                    readiness_fd=-1, final_ack_fd=-1, confirmed_fd=-1)
    empty_terminal = {name: b"{}\n" for name in
                      ("stage_b.json", "status.json", "runtime_native_pre_import.json",
                       "runtime_native_post_torch.json", "runtime_native_post_model.json",
                       "runtime_native_final.json")}
    endpoint_value = endpoint_registry()
    probes: list[tuple[str, Any]] = [
        ("setup_m3", lambda: setup_m3(
            M2_REVIEWED_COMPLETION_SHA256, "a" * 64, "b" * 64)),
        ("build_m4", lambda: build_m4("c" * 64)),
        ("verify_post_m3_review", lambda: verify_post_m3_review("c" * 64)),
        ("verify_candidate_manifest", lambda: verify_candidate_manifest("prescore")),
        ("prescore_traced_check", lambda: prescore_traced_check(manifest_path, check_path, trace_path)),
        ("verify_prescore_trace", lambda: verify_prescore_trace(manifest_path, check_path, trace_path)),
        ("sign_authorization", sign_authorization), ("launch", launch),
        ("broker", lambda: broker(dummy_socket, dummy_uuid, 0,
                                  dummy_launch_capability, dummy_intent_sha256)),
        ("supervise_broker", lambda: supervise_broker(
            dummy_socket, dummy_uuid, 0, dummy_launch_capability, dummy_intent_sha256)),
        ("runner.run", lambda: runner_module.run(probe_args)),
        ("checkpoint_registry", lambda: checkpoint_registry(root=root)),
        ("endpoint_registry", endpoint_registry),
        ("validate_endpoint_registry", lambda: validate_endpoint_registry(endpoint_value)),
        ("closure_payload", lambda: closure_payload(checkpoints, root=root)),
        ("environment_payload", lambda: environment_payload({}, root=root)),
        ("verify_dependency_closure", verify_dependency_closure),
        ("verify_runtime_loaded_libraries", lambda: verify_runtime_loaded_libraries(
            {"allowed_native_libraries": [], "executables": [],
             "model_snapshot": {"path": str(base.SNAPSHOT), "entries": []}})),
        ("validate_stage_a", validate_stage_a),
        ("verify_authorization", lambda: verify_authorization(
            ACTIVE_RUN_ROOT / "authorization.json", consume=False)),
        ("validate_runner_readiness", lambda: validate_runner_readiness({}, {}, dummy_uuid, {})),
        ("commit_terminal_failure", lambda: commit_terminal_failure(
            ACTIVE_RUN_ROOT, {"status": "not_run"})),
        ("commit_terminal_success", lambda: commit_terminal_success(ACTIVE_RUN_ROOT, empty_terminal)),
        ("confirm_pre_model_gate", lambda: confirm_pre_model_gate(gate_r, confirmed_w)),
        ("worker_environment", lambda: worker_environment(dummy_uuid, 1, 2, 3, 4)),
        ("validate_stage_b_typed_qa", lambda: validate_stage_b_typed_qa(
            ACTIVE_RUN_ROOT, {}, {}, {})),
        ("dispatch", lambda: dispatch(["build-m2-completion"])),
        ("controller.main", lambda: continuation.main(["build-m2-completion"])),
        *extra_probes,
    ]
    if not extra_probes and tuple(name for name, _ in probes) != PUBLIC_EXECUTION_ENTRYPOINTS:
        raise AssertionError("public CPU surface trace entrypoint set drift")

    results: list[dict[str, Any]] = []
    tripwire_proofs: list[str] = []
    with contextlib.ExitStack() as stack:
        for fd in descriptor_labels:
            stack.callback(original_os_close, fd)
        stack.enter_context(mock.patch.object(builtins, "__import__", import_probe))
        replacements = [
            (builtins, "open", file_probe("open")), (io_module, "open", file_probe("io.open")),
            (os, "open", file_probe("os.open")), (os, "mkdir", file_probe("os.mkdir")),
            (os, "rename", file_probe("os.rename")), (os, "replace", file_probe("os.replace")),
            (os, "unlink", file_probe("os.unlink")), (os, "remove", file_probe("os.remove")),
            (os, "stat", file_probe("os.stat")), (os, "lstat", file_probe("os.lstat")),
            (os, "scandir", file_probe("os.scandir")), (os, "listdir", file_probe("os.listdir")),
            (os, "read", file_probe("os.read", descriptor=True)),
            (os, "write", file_probe("os.write", descriptor=True)),
            (os, "lseek", file_probe("os.lseek", descriptor=True)),
            (os, "fstat", file_probe("os.fstat", descriptor=True)),
            (os, "fsync", file_probe("os.fsync", descriptor=True)),
            (os, "ftruncate", file_probe("os.ftruncate", descriptor=True)),
            (os, "close", file_probe("os.close", descriptor=True)),
            (os, "execve", process_probe("os.execve")),
            (os, "execv", process_probe("os.execv")), (os, "system", process_probe("os.system")),
            (subprocess, "run", process_probe("subprocess.run")),
            (subprocess, "check_output", process_probe("subprocess.check_output")),
            (subprocess, "check_call", process_probe("subprocess.check_call")),
            (subprocess, "Popen", process_probe("subprocess.Popen")),
            (socket, "socket", socket_probe),
            (socket, "create_connection", connection_probe),
            (ctypes, "CDLL", library_probe), (ctypes, "PyDLL", library_probe),
            (ctypes.cdll, "LoadLibrary", library_probe),
            (shutil, "rmtree", file_probe("shutil.rmtree")),
        ]
        for name in ("open", "read_bytes", "read_text", "write_bytes", "write_text",
                     "unlink", "mkdir", "rename", "replace", "rmdir", "exists", "is_file",
                     "is_dir", "is_symlink", "stat", "lstat", "iterdir", "rglob", "glob",
                     "resolve"):
            replacements.append((Path, name, file_probe(f"Path.{name}")))
        for owner, name, replacement in replacements:
            stack.enter_context(mock.patch.object(owner, name, replacement))

        for name, probe in probes:
            before_allowed, before_violation = len(allowed_requests), len(violation_requests)
            try:
                probe()
            except _SurfaceProbeViolation:
                if name in {item[0] for item in extra_probes}:
                    raise
                raise
            except _SurfaceProbeBlocked:
                outcome = "allowed_surface_blocked"
            except BaseException as error:
                outcome = f"prescore_rejected:{type(error).__name__}"
            else:
                outcome = "returned_without_model_or_surface"
            results.append({"entrypoint": name, "outcome": outcome,
                            "allowed_requests": allowed_requests[before_allowed:],
                            "violation_requests": violation_requests[before_violation:]})

        # Positive handler realization for all four surface families.
        for proof_name, probe in (
            ("allowed_file", lambda: Path(ROOT / "TODO.md").read_text()),
            ("allowed_root_directory", lambda: Path(ROOT).stat()),
            ("allowed_nonce_template", lambda: file_probe("positive_nonce")(
                "a" * 64 + ".consumed", dir_fd=42)),
            ("allowed_gpu_lock_template", lambda: file_probe("positive_lock")(
                "b" * 64 + ".lock", dir_fd=43)),
            ("allowed_check_template", lambda: Path(
                "/tmp/msae_independent_measurement_v3_post_m2_gen3_" + "c" * 64 +
                ".prescore.check.json").read_bytes()),
            ("allowed_trace_template", lambda: Path(
                "/tmp/msae_independent_measurement_v3_post_m2_gen3_" + "d" * 64 +
                ".prescore.trace.log").read_bytes()),
            ("allowed_socket_template", lambda: Path(
                "/tmp/msae_independent_measurement_v3_post_m2_gen3_" + "e" * 64 + ".sock").exists()),
            ("allowed_process", lambda: subprocess.run(
                ["/usr/bin/git", "status", "--porcelain=v2", "--untracked-files=all"])),
            ("allowed_ldd_template", lambda: process_probe("positive_ldd")(
                ["/usr/bin/ldd", "/usr/bin/ldd"])),
            ("allowed_strace_template", lambda: process_probe("positive_strace")([
                "/usr/bin/strace", "-f", "-qq", "-yy", "-s", "4096", "-e",
                "trace=open,openat,openat2,creat", "-o", "/proc/self/fd/12",
                python, "-S", "-B", "-I", controller, "prescore-check", "--output-fd", "11"])),
            ("allowed_python_broker_template", lambda: process_probe("positive_python")([
                python, "-S", "-B", "-I", controller, "broker", "--socket", dummy_socket,
                "--gpu-uuid", dummy_uuid, "--gpu-index", "0",
                "--launch-capability", dummy_launch_capability,
                "--intent-sha256", dummy_intent_sha256])),
            ("allowed_worker_execve_template", lambda: os.execve(
                python, [python, "-S", "-B", "-I", runner_executable,
                         "--run-root", ACTIVE_RUN_REL, "--gpu-uuid", dummy_uuid,
                         "--broker-pid", "2", "--readiness-fd", "5",
                         "--final-ack-fd", "6", "--confirmed-fd", "7"],
                worker_environment(dummy_uuid, 4, 5, 6, 7))),
            ("allowed_tmux_display_template", lambda: process_probe("positive_tmux_display")([
                "/usr/bin/tmux", "-S", "/tmp/msae_independent_measurement_v3_post_m2_gen3_" + "a" * 64 +
                ".sock", "display-message", "-p", "-t", "msae-independent-v3-gen3-calibration",
                "#{pane_pid}"])),
            ("allowed_tmux_new_template", lambda: process_probe("positive_tmux_new")([
                "/usr/bin/tmux", "-f", "/dev/null", "-S",
                "/tmp/msae_independent_measurement_v3_post_m2_gen3_" + "a" * 64 +
                ".sock", "new-session", "-d", "-s",
                "msae-independent-v3-gen3-calibration", "/usr/bin/bash", "--noprofile", "--norc", "-c",
                "exec " + shlex.join([python, "-S", "-B", "-I", controller, "supervise-broker",
                                      "--socket", dummy_socket, "--gpu-uuid", dummy_uuid,
                                      "--gpu-index", "0",
                                      "--launch-capability", dummy_launch_capability,
                                      "--intent-sha256", dummy_intent_sha256])])),
            ("allowed_unix_socket", lambda: socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)),
            ("allowed_global_libc", lambda: ctypes.CDLL(None)),
        ):
            try:
                probe()
            except _SurfaceProbeBlocked:
                tripwire_proofs.append(proof_name)
            else:
                raise AssertionError(f"surface positive probe escaped: {proof_name}")

        planted = (
            ("indirect_open", lambda: getattr(builtins, "open")("/etc/passwd", "rb")),
            ("unregistered_state_path", lambda: Path(ACTIVE_STATE / "unregistered/escape").read_text()),
            ("dynamic_subprocess", lambda: getattr(subprocess, "run")(["/bin/false"])),
            ("shell_expansion", lambda: subprocess.run(
                ["/usr/bin/git", "status", "--porcelain=v2", "--untracked-files=all", "-z"],
                shell=True)),
            ("bash_command", lambda: subprocess.run(["/usr/bin/bash", "-c", "cat /etc/passwd"])),
            ("dlopen_escape", lambda: ctypes.CDLL("/tmp/escape.so")),
            ("network_escape", lambda: socket.socket(socket.AF_INET, socket.SOCK_STREAM)),
        )
        for proof_name, probe in planted:
            try:
                probe()
            except _SurfaceProbeViolation:
                tripwire_proofs.append(proof_name)
            else:
                raise AssertionError(f"planted surface escape was not rejected: {proof_name}")

    public_allowed = [request for result in results for request in result["allowed_requests"]]
    static_operations = {(str(row["category"]), str(row["operation"]).rsplit(".", 1)[-1])
                         for row in static_analysis["surface_calls"]}
    normalized_operations = {
        (str(request["category"]),
         ("CDLL" if request["operation"] == "ctypes.dlopen" else
          str(request["operation"]).rsplit(".", 1)[-1]))
        for request in public_allowed
    }
    if not {row["category"] for row in public_allowed} <= static_categories:
        raise ValueError("CPU trace observed a category absent from static closure")
    if not normalized_operations <= static_operations:
        raise ValueError(f"CPU trace observed operations absent from static closure: "
                         f"{sorted(normalized_operations - static_operations)}")
    if tuple(tripwire_proofs) != (
            "allowed_file", "allowed_root_directory", "allowed_nonce_template",
            "allowed_gpu_lock_template", "allowed_check_template", "allowed_trace_template",
            "allowed_socket_template", "allowed_process", "allowed_ldd_template",
            "allowed_strace_template", "allowed_python_broker_template",
            "allowed_worker_execve_template",
            "allowed_tmux_display_template", "allowed_tmux_new_template", "allowed_unix_socket",
            "allowed_global_libc",
            "indirect_open", "unregistered_state_path", "dynamic_subprocess", "shell_expansion",
            "bash_command", "dlopen_escape", "network_escape"):
        raise AssertionError("CPU surface proof set drift")
    return {"schema_version": "msae_v3_cpu_no_model_public_entry_trace_v3",
            "entrypoints": [name for name, _ in probes], "results": results,
            "allowed_requests": allowed_requests, "violation_requests": violation_requests,
            "static_surface_set_sha256": static_analysis["surface_set_sha256"],
            "static_value_flow_ast_sha256": static_analysis["local_value_flow_ast_sha256"],
            "finite_file_registry": file_registry,
            "finite_process_registry": process_registry,
            "review_gates": dict(review_gates or {}),
            "tripwire_proofs": tripwire_proofs, "model_imports": 0,
            "allowed_request_set_sha256": base.sha_bytes(base.canonical_bytes(allowed_requests)),
            "violation_request_set_sha256": base.sha_bytes(base.canonical_bytes(violation_requests)),
            "status": "eligible"}


def _validate_cpu_no_model_trace(value: Mapping[str, Any], *, root: Path,
                                 checkpoints: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    if (value.get("schema_version") != "msae_v3_cpu_no_model_public_entry_trace_v3"
            or value.get("entrypoints") != list(PUBLIC_EXECUTION_ENTRYPOINTS)
            or value.get("status") != "eligible" or value.get("model_imports") != 0
            or value.get("static_surface_set_sha256") != FROZEN_STATIC_SURFACE_SET_SHA256
            or value.get("static_value_flow_ast_sha256") != FROZEN_LOCAL_VALUE_FLOW_AST_SHA256):
        raise ValueError("CPU/no-model public-entry trace schema/entrypoint drift")
    review_gates = value.get("review_gates")
    if (not isinstance(review_gates, dict)
            or set(review_gates) != {"plan_sha256", "plan_entry", "plan_review_sha256",
                                         "plan_review_entry", "implementation_review_sha256",
                                         "implementation_review_entry"}
            or review_gates.get("plan_sha256") != FROZEN_PLAN_SHA256):
        raise ValueError("CPU/no-model review-gate binding is incomplete")
    expected_review_gates = _trace_review_gates(
        root, str(review_gates["plan_review_sha256"]),
        str(review_gates["implementation_review_sha256"]))
    if review_gates != expected_review_gates:
        raise ValueError("CPU/no-model review-gate entries drift")
    expected_registry = _surface_file_registry(root=root, checkpoints=checkpoints)
    # Descriptor labels are deterministic typed names; the trace generator adds
    # them after opening real pipes and then rehashes the registry.
    expected_registry["exact_logical_paths"] = sorted(
        set(expected_registry["exact_logical_paths"]) |
        {"fd://pre_model_gate_read", "fd://pre_model_gate_write",
         "fd://model_gate_confirmation_read", "fd://model_gate_confirmation_write"})
    expected_registry.pop("registry_sha256")
    expected_registry["registry_sha256"] = base.sha_bytes(base.canonical_bytes(expected_registry))
    if value.get("finite_file_registry") != expected_registry:
        raise ValueError("CPU/no-model finite file registry drift")
    if value.get("finite_process_registry") != _finite_process_registry():
        raise ValueError("CPU/no-model finite process registry drift")
    results = value.get("results")
    if (not isinstance(results, list)
            or [row.get("entrypoint") for row in results] != list(PUBLIC_EXECUTION_ENTRYPOINTS)):
        raise ValueError("CPU/no-model public-entry result set drift")
    proofs = value.get("tripwire_proofs")
    required_proofs = {"indirect_open", "unregistered_state_path", "dynamic_subprocess",
                       "shell_expansion", "bash_command", "dlopen_escape", "network_escape"}
    if not isinstance(proofs, list) or not required_proofs <= set(proofs):
        raise ValueError("CPU/no-model planted escape proof set incomplete")
    for key in ("allowed_requests", "violation_requests"):
        rows = value.get(key)
        if not isinstance(rows, list) or value.get(
                key.removesuffix("s") + "_set_sha256") != base.sha_bytes(base.canonical_bytes(rows)):
            raise ValueError(f"CPU/no-model {key} digest drift")
    return dict(value)


def _verify_live_cpu_no_model_trace() -> dict[str, Any]:
    raw = _regular_bytes(CPU_NO_MODEL_TRACE, mode=0o644)
    observed = base.strict_json_loads(raw.decode("utf-8"))
    if raw != base.canonical_bytes(observed):
        raise ValueError("CPU/no-model trace artifact is noncanonical")
    checkpoints = checkpoint_registry()
    _validate_cpu_no_model_trace(observed, root=ROOT, checkpoints=checkpoints)
    reproduced = cpu_no_model_public_entry_trace(review_gates=observed["review_gates"])
    if reproduced != observed:
        raise ValueError("CPU/no-model public-entry trace does not reproduce")
    return observed


def _distribution_resolution(*, root: Path = ROOT) -> dict[str, Any]:
    """Resolve all frozen and runtime-root distributions through metadata."""
    from packaging.requirements import Requirement
    from packaging.utils import canonicalize_name

    lock_path = root / "requirements-atlas.lock.txt"
    lock_rows = []
    for ordinal, raw in enumerate(lock_path.read_text(encoding="utf-8").splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        match = re.fullmatch(r"([A-Za-z0-9_.-]+)==([^\s]+)", line, re.ASCII)
        if match is None:
            raise ValueError(f"malformed frozen requirement at line {ordinal}")
        name, version = match.groups()
        installed = importlib.metadata.distribution(name)
        if installed.version != version:
            raise ValueError(f"frozen requirement version drift: {name}=={version}")
        lock_rows.append({"name": installed.metadata["Name"], "version": version,
                          "line_number": ordinal})
    explicit = _static_runtime_distribution_roots(root=root)
    queue = list(explicit)
    resolved: dict[str, dict[str, str]] = {}
    edges: list[dict[str, Any]] = []
    while queue:
        requested = queue.pop(0)
        distribution = importlib.metadata.distribution(requested)
        canonical = canonicalize_name(distribution.metadata["Name"])
        if canonical in resolved:
            continue
        resolved[canonical] = {"name": distribution.metadata["Name"],
                               "version": distribution.version}
        for raw_requirement in distribution.requires or []:
            requirement = Requirement(raw_requirement)
            if requirement.marker is not None and not requirement.marker.evaluate({"extra": ""}):
                continue
            dependency = importlib.metadata.distribution(requirement.name)
            dependency_name = dependency.metadata["Name"]
            satisfied = not requirement.specifier or dependency.version in requirement.specifier
            if not satisfied:
                raise ValueError(
                    f"installed dependency violates requirement: {distribution.metadata['Name']}:{raw_requirement}")
            edges.append({"from": distribution.metadata["Name"], "requirement": raw_requirement,
                          "to": dependency_name, "resolved_version": dependency.version,
                          "specifier_satisfied": True})
            queue.append(dependency_name)
    rows = sorted(resolved.values(), key=lambda row: canonicalize_name(row["name"]))
    edges.sort(key=lambda row: (canonicalize_name(row["from"]), row["requirement"],
                                canonicalize_name(row["to"])))
    return {"schema_version": "msae_v3_distribution_resolution_v1",
            "lock_path": "requirements-atlas.lock.txt",
            "lock_sha256": base.sha_file(lock_path), "lock_rows": lock_rows,
            "static_runtime_roots": explicit, "distributions": rows,
            "dependency_edges": edges,
            "distribution_set_sha256": base.sha_bytes(base.canonical_bytes(rows)),
            "dependency_edge_set_sha256": base.sha_bytes(base.canonical_bytes(edges))}


def _closure_local_relative_names(checkpoints: Sequence[Mapping[str, Any]], *, root: Path) -> list[str]:
    """Mechanically enumerate repository-local closure paths without opening payloads."""
    paths = {
        "TODO.md", "requirements-atlas.lock.txt", "docs/rfc-msae-independent-measurement-v1.md",
        "docs/rfc-msae-measurement-remediation-readiness-v1.md",
        "docs/rfc-msae-independent-measurement-v3.md",
        "docs/rfc-msae-independent-measurement-v3-m2-continuation.md",
        "docs/rfc-msae-independent-measurement-v3-post-m2-runtime.md",
        "docs/rfc-msae-independent-measurement-v3-post-m4-gen3.md",
        "docs/plan-msae-independent-measurement-v3-post-m4-gen3.md",
        "scripts/msae_independent_measurement_v3.py",
        "scripts/msae_independent_measurement_v3_post_m1.py",
        "scripts/msae_independent_measurement_v3_post_m1_runtime.py",
        "scripts/run_msae_independent_calibration_v3.py",
        "scripts/launch_msae_independent_calibration_v3.sh",
        "scripts/msae_independent_measurement_v3_post_m2_gen3_runtime.py",
        "scripts/msae_independent_measurement_v3_post_m2_gen3.py",
        "scripts/run_msae_independent_calibration_v3_gen3.py",
        "scripts/launch_msae_independent_calibration_v3_gen3.sh",
        "scripts/msae_measurement_remediation_v1.py", "scripts/msae_measurement_v2.py",
        "configs/msae_measurement_remediation_v1/draft.json",
        "reports/provenance/msae_measurement_remediation_v1/BASELINE.json",
        "reports/provenance/msae_measurement_remediation_v1/FINAL_STATIC_VERIFICATION.json",
        "tests/test_msae_independent_measurement_v3.py",
        "tests/test_msae_independent_measurement_v3_post_m1.py",
        "tests/test_msae_independent_measurement_v3_post_m2_runtime.py",
        "tests/test_msae_independent_measurement_v3_post_m4_gen3.py",
        "tests/test_msae_measurement_remediation_v1.py",
        "configs/msae_independent_measurement_v1/protocol.json",
        "configs/msae_independent_measurement_v3/protocol.json",
        "configs/msae_independent_measurement_v3/authorization_commitment.json",
        "configs/msae_independent_measurement_v3/ed25519_public.pem",
        "configs/msae_independent_measurement_v3_post_m2_gen2/protocol.json",
        "configs/msae_independent_measurement_v3_post_m2_gen2/authorization_commitment.json",
        "configs/msae_independent_measurement_v3_post_m2_gen2/ed25519_public.pem",
        "configs/msae_independent_measurement_v3_post_m2_gen2/cpu_no_model_public_entry_trace.json",
        "configs/msae_independent_measurement_v3_post_m2_gen3/protocol.json",
        "configs/msae_independent_measurement_v3_post_m2_gen3/authorization_commitment.json",
        "configs/msae_independent_measurement_v3_post_m2_gen3/ed25519_public.pem",
        "configs/msae_independent_measurement_v3_post_m2_gen3/cpu_no_model_public_entry_trace.json",
        "reports/adversarial/msae_independent_measurement_v3_post_m2_gen3_plan.md",
        "reports/adversarial/msae_independent_measurement_v3_post_m2_gen3_implementation.md",
        "reports/adversarial/msae_independent_measurement_v3_post_m2_gen3_post_m3.md",
        "reports/provenance/msae_independent_measurement_v3_post_m2_gen2/m4_failure.json",
        "reports/provenance/msae_independent_measurement_v3/m1_completion_manifest.json",
        "reports/provenance/msae_independent_measurement_v3/m2_completion_manifest.json",
        "reports/provenance/msae_independent_measurement_v3/m3_preflight_attempt_1.json",
        "reports/provenance/msae_independent_measurement_v1/status.json",
        "reports/provenance/msae_independent_measurement_v1/history_overlap.json",
        "data/msae_independent_measurement_v1/calibration_strata.json",
        "data/atlas_measurement_v2_4/prepared/calibration/inference_units.jsonl",
        "data/atlas_measurement_v2_4/prepared/calibration/pairs.jsonl",
        "data/atlas_v1/partitions/discovery.records.jsonl",
        "data/atlas_v1/partitions/discovery.units.jsonl",
        "data/atlas_v1/partitions/calibration.records.jsonl",
        "data/atlas_v1/partitions/calibration.units.jsonl",
    }
    paths.update(_static_closure_analysis(root=root)["local_modules"])
    paths.update(f"data/msae_independent_measurement_v3/{name}"
                 for phase in ("M0", "M1", "M2") for name in base.V3_DATA_PHASE_FILES[phase])
    # Preservation is executable provenance, not merely a status label.  Carry
    # every byte protected by the terminal v1/v2 manifests into the successor
    # closure and candidate projection.  Quarantined payloads would remain
    # metadata-only, but neither protected manifest currently contains them.
    protected_root = root / "data/msae_independent_measurement_v3"
    for name in ("protected_v1_manifest.json", "protected_v2_manifest.json"):
        protected = base.strict_json_loads((protected_root / name).read_text(encoding="utf-8"))
        protected_entries = protected.get("entries")
        if not isinstance(protected_entries, list):
            raise ValueError(f"protected manifest lacks an entry array: {name}")
        for row in protected_entries:
            relative = row.get("path")
            if not isinstance(relative, str) or not relative or relative.startswith("/"):
                raise ValueError(f"protected manifest has an invalid path: {name}")
            if relative in base.QUARANTINED:
                continue
            paths.add(relative)
    alias_path = root / "data/msae_independent_measurement_v3/source_alias_manifest.json"
    aliases = base.strict_json_loads(alias_path.read_text(encoding="utf-8"))
    paths.update(str(row["path"]) for row in aliases["entries"])
    for row in checkpoints:
        paths.update((str(row["checkpoint_path"]), str(row["summary_path"]), str(row["metrics_path"])))
    return sorted(paths, key=lambda value: value.encode("utf-8"))


def _closure_local_relatives(checkpoints: Sequence[Mapping[str, Any]], *, root: Path) -> list[str]:
    """Exact validated repository-local input set used by closure and Stage A."""
    paths = _closure_local_relative_names(checkpoints, root=root)
    for relative in paths:
        path = root / relative
        st = path.lstat()
        if not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode):
            raise ValueError(f"closure local input is not regular: {relative}")
    return paths


EXPECTED_MODEL_SNAPSHOT_NAMES = {
    "config.json", "model.safetensors", "special_tokens_map.json",
    "tokenizer.json", "tokenizer_config.json",
}


def _model_snapshot_entries(snapshot: Path) -> list[dict[str, Any]]:
    children = list(snapshot.iterdir())
    observed_names = {path.name for path in children}
    if observed_names != EXPECTED_MODEL_SNAPSHOT_NAMES:
        raise ValueError(
            f"model snapshot exact filename set drift: missing="
            f"{sorted(EXPECTED_MODEL_SNAPSHOT_NAMES - observed_names)}, extra="
            f"{sorted(observed_names - EXPECTED_MODEL_SNAPSHOT_NAMES)}")
    entries = []
    for path in sorted(children, key=lambda item: item.name.encode("utf-8")):
        if not (path.is_file() or path.is_symlink()):
            raise ValueError(f"model snapshot entry is not a file/symlink: {path.name}")
        entry = base._content_entry(path, root=snapshot)
        if entry["type"] == "symlink":
            cache_root = snapshot.parents[2].resolve(strict=True)
            if not Path(entry["realpath"]).is_relative_to(cache_root):
                raise ValueError("model snapshot symlink escapes frozen cache root")
        entries.append(entry)
    return entries


def _extend_rooted_closure(payload: Mapping[str, Any], *, root: Path) -> dict[str, Any]:
    """Invoke the immutable post-M1 extension against only candidate-root bytes."""
    candidate_root = root
    extra_relatives = (
        PLAN_PATH.relative_to(ROOT), PLAN_REVIEW.relative_to(ROOT),
        IMPLEMENTATION_REVIEW.relative_to(ROOT), POST_M3_REVIEW.relative_to(ROOT),
        continuation.CONTROLLER_PATH.relative_to(ROOT), RUNTIME.relative_to(ROOT),
        RUNNER.relative_to(ROOT), LAUNCHER.relative_to(ROOT), RUNTIME_RFC.relative_to(ROOT),
        RUNTIME_TEST.relative_to(ROOT), GEN2_FAILURE_PATH.relative_to(ROOT),
        ACTIVE_CONFIG.relative_to(ROOT) / "protocol.json",
        ACTIVE_CONFIG.relative_to(ROOT) / "authorization_commitment.json",
        ACTIVE_CONFIG.relative_to(ROOT) / "ed25519_public.pem",
        CPU_NO_MODEL_TRACE.relative_to(ROOT),
    )
    original = {
        "root": immutable_continuation.ROOT,
        "controller": immutable_continuation.CONTROLLER_PATH,
        "rfc": immutable_continuation.CONTINUATION_RFC,
        "test": immutable_continuation.CONTINUATION_TEST,
        "m1": immutable_continuation.M1_COMPLETION_PATH,
        "base_root": base.ROOT,
        "base_content_entry": base._content_entry,
    }

    def rooted_content_entry(
        path: Path, *, root: Path = candidate_root,
    ) -> dict[str, Any]:
        candidate_path = Path(path)
        if root != candidate_root or not candidate_path.is_relative_to(candidate_root):
            raise ValueError(
                f"post-M1 closure attempted live/noncandidate input: {candidate_path}")
        # Match the successor closure schema (including owner/link count), not
        # the immutable helper's older entry schema.  Otherwise paths already
        # present in the gen3 payload conflict when the continuation revisits
        # them.
        return _regular_entry(candidate_path, root=candidate_root)

    try:
        immutable_continuation.ROOT = root
        immutable_continuation.CONTROLLER_PATH = (
            root / original["controller"].relative_to(ROOT))
        immutable_continuation.CONTINUATION_RFC = root / original["rfc"].relative_to(ROOT)
        immutable_continuation.CONTINUATION_TEST = root / original["test"].relative_to(ROOT)
        immutable_continuation.M1_COMPLETION_PATH = root / original["m1"].relative_to(ROOT)
        base.ROOT = root
        # The immutable helper's default ``root=ROOT`` was bound when the base
        # module was imported.  Rebinding the global alone therefore does not
        # root its entry paths.  Force every continuation entry through the
        # explicit candidate root for both M4 realizations.
        base._content_entry = rooted_content_entry
        result = continuation.extend_closure_payload(
            payload, [root / relative for relative in extra_relatives])
    finally:
        immutable_continuation.ROOT = original["root"]
        immutable_continuation.CONTROLLER_PATH = original["controller"]
        immutable_continuation.CONTINUATION_RFC = original["rfc"]
        immutable_continuation.CONTINUATION_TEST = original["test"]
        immutable_continuation.M1_COMPLETION_PATH = original["m1"]
        base.ROOT = original["base_root"]
        base._content_entry = original["base_content_entry"]
    paths = [str(row["path"]) for row in result["entries"]]
    if len(paths) != len(set(paths)):
        raise ValueError("rooted closure extension introduced duplicate paths")
    result["entry_path_set_sha256"] = base.sha_bytes(
        base.canonical_bytes(sorted(paths, key=lambda value: value.encode("utf-8"))))
    return result


def closure_payload(checkpoints: list[dict[str, Any]], *, root: Path = ROOT) -> dict[str, Any]:
    local_relatives = _closure_local_relatives(checkpoints, root=root)
    entries = [_regular_entry(root / relative, root=root) for relative in local_relatives]
    snapshot_entries = _model_snapshot_entries(base.SNAPSHOT)
    python_startup = _python_startup_payload()
    executable_paths = [Path(sys.executable), Path("/usr/bin/bash"), Path("/usr/bin/git"),
                        Path("/usr/bin/ldd"), Path("/usr/bin/nvidia-smi"),
                        Path("/usr/bin/strace"), Path("/usr/bin/tmux")]
    executables = [_executable_record(path) for path in executable_paths]
    distribution_resolution = _distribution_resolution(root=root)
    distributions = [_distribution_inventory(row["name"])
                     for row in distribution_resolution["distributions"]]
    native: dict[str, dict[str, Any]] = {}
    for executable in executables:
        for row in executable["ldd"]:
            native[row["path"]] = row
    for distribution in distributions:
        for row in distribution["native_libraries"]:
            native[row["path"]] = row
        for realization in distribution.get("native_ldd", []):
            for row in realization["dependencies"]:
                native[row["path"]] = row
    stdlib = Path(sys.executable).resolve().parent.parent / "lib/python3.12/lib-dynload"
    if stdlib.is_dir():
        for path in stdlib.glob("*.so"):
            resolved = path.resolve(strict=True)
            native[str(resolved)] = {"path": str(resolved), "size": resolved.stat().st_size,
                                     "sha256": base.sha_file(resolved)}
            for row in _ldd_inventory(resolved):
                native[row["path"]] = row
    system_root = Path("/usr/lib/x86_64-linux-gnu")
    driver_anchor = (system_root / "libcuda.so.1").resolve(strict=True)
    driver_suffix = driver_anchor.name.removeprefix("libcuda.so.")
    driver_names = (f"libcuda.so.{driver_suffix}", f"libnvidia-ml.so.{driver_suffix}",
                    f"libnvidia-ptxjitcompiler.so.{driver_suffix}",
                    f"libnvidia-nvvm.so.{driver_suffix}",
                    f"libnvidia-gpucomp.so.{driver_suffix}", f"libnvidia-tls.so.{driver_suffix}")
    for name in driver_names:
        resolved = (system_root / name).resolve(strict=True)
        if not resolved.is_file():
            raise ValueError(f"frozen compute-driver library is absent: {name}")
        native[str(resolved)] = {"path": str(resolved), "size": resolved.stat().st_size,
                                 "sha256": base.sha_file(resolved)}
        with resolved.open("rb") as handle:
            magic = handle.read(4)
        if magic != b"\x7fELF":
            raise ValueError(f"frozen compute-driver object is not ELF: {resolved}")
        for row in _ldd_inventory(resolved):
            native[row["path"]] = row
    # Python maps these locale/gconv support files but they are not ELF or wheel
    # members.  Enumerate the finite canonical paths, independent of which
    # modules happen to be imported while closure construction runs.
    for raw in ("/usr/lib/locale/locale-archive", "/usr/lib/locale/C.utf8/LC_CTYPE",
                "/usr/lib/x86_64-linux-gnu/gconv/gconv-modules.cache"):
        path = Path(raw)
        if path.exists():
            resolved = path.resolve(strict=True)
            native[str(resolved)] = {"path": str(resolved), "size": resolved.stat().st_size,
                                     "sha256": base.sha_file(resolved)}
    allowed_native = sorted(native.values(), key=lambda row: row["path"])
    runtime_controller = {
        "entrypoint": _regular_entry(root / continuation.CONTROLLER_PATH.relative_to(ROOT), root=root),
        "runtime": _regular_entry(root / RUNTIME.relative_to(ROOT), root=root),
        "runner": _regular_entry(root / RUNNER.relative_to(ROOT), root=root),
        "launcher": _regular_entry(root / LAUNCHER.relative_to(ROOT), root=root),
        "runtime_rfc": _regular_entry(root / RUNTIME_RFC.relative_to(ROOT), root=root),
        "runtime_test": _regular_entry(root / RUNTIME_TEST.relative_to(ROOT), root=root),
    }
    static_analysis = _static_closure_analysis(root=root)
    cpu_trace_path = root / CPU_NO_MODEL_TRACE.relative_to(ROOT)
    cpu_trace_raw = cpu_trace_path.read_bytes()
    cpu_trace = base.strict_json_loads(cpu_trace_raw.decode("utf-8"))
    if cpu_trace_raw != base.canonical_bytes(cpu_trace):
        raise ValueError("frozen CPU/no-model public-entry trace is noncanonical")
    _validate_cpu_no_model_trace(cpu_trace, root=root, checkpoints=checkpoints)
    executable_realpaths = {row["path"] for row in executables}
    allowed_processes = {str(Path(path).resolve(strict=True))
                         for path in static_analysis["allowed_process_argv0"]}
    if not allowed_processes <= executable_realpaths:
        raise ValueError(f"static process target is absent from executable closure: "
                         f"{sorted(allowed_processes - executable_realpaths)}")
    static_allowlist = {**static_analysis,
        "network": ["unix_domain_broker_handoff_only"],
        "shell": ["tmux_exact_no_profile_no_rc_bash_exec_of_content_bound_broker_argv"],
        "process_argv0": sorted(executable_realpaths),
        "external_write_roots": [str(ACTIVE_PRIVATE_KEY.parent), str(ACTIVE_STATE),
                                 str(M4_PRIMARY), str(M4_REBUILD), str(ACTIVE_RUN_ROOT), "/tmp"],
        "cpu_no_model_public_entry_trace": cpu_trace,
    }
    config_value = _read_root_json(
        root, str((ACTIVE_CONFIG / "protocol.json").relative_to(ROOT)))
    config_derivation = config_value.get("post_m2_runtime", {}).get(
        "environment_derivation")
    expected_derivation = _environment_derivation(candidate_root=root)
    if config_derivation != expected_derivation:
        raise ValueError("protocol-config environment derivation does not reproduce")
    _validate_config_closure_environment(
        config_value, expected_derivation, executables,
        python_executable=str(Path(sys.executable).resolve(strict=True)), root=root)
    payload = {
        "schema_version": "msae_v3_dependency_closure_v2", "protocol_id": PROTOCOL,
        "generation": GENERATION,
        "entries": sorted(entries, key=lambda row: row["path"]),
        "entry_path_set_sha256": base.sha_bytes(base.canonical_bytes(local_relatives)),
        "quarantined_entries": [base._quarantine_entry(rel) for rel in sorted(base.QUARANTINED)],
        "sealed_payload_content_reads": 0,
        "model_snapshot": {"path": str(base.SNAPSHOT), "revision": base.SNAPSHOT.name,
                           "entries": snapshot_entries},
        "checkpoint_registry": checkpoints,
        "python_executable": str(Path(sys.executable).resolve(strict=True)),
        "python_version": sys.version,
        "python_startup": python_startup,
        "executables": executables, "distribution_resolution": distribution_resolution,
        "distributions": distributions,
        "allowed_native_libraries": allowed_native,
        "runtime_controller": runtime_controller,
        "environment_derivation": expected_derivation,
        "static_runtime_allowlist": static_allowlist,
        "runtime_policy": {"deterministic_algorithms": True, "tf32": False,
                           "cublas_workspace_config": ":4096:8", "pythonhashseed": "0",
                           "tokenizers_parallelism": "false",
                           "model_dtype": "float16", "cache_dtype": "float32", "layer": 3,
                           "pooling": "registered_first_subtoken_rows",
                           "gpu_uuid_and_driver_realization_post_ship": True,
                           "prescore_gpu_queries_forbidden": True},
        "protocol_config_sha256": base.sha_file(root / ACTIVE_CONFIG.relative_to(ROOT) / "protocol.json"),
        "authorization_commitment_sha256": base.sha_file(
            root / ACTIVE_CONFIG.relative_to(ROOT) / "authorization_commitment.json"),
    }
    return _extend_rooted_closure(payload, root=root)


def _validate_config_closure_environment(
    config_value: Mapping[str, Any],
    expected_derivation: Mapping[str, Any],
    executables: Sequence[Mapping[str, Any]],
    *,
    python_executable: str,
    root: Path,
) -> None:
    """Cross-bind config strata, external Python, and executable closure."""
    if config_value.get("post_m2_runtime", {}).get(
            "environment_derivation") != expected_derivation:
        raise ValueError("protocol-config environment derivation does not reproduce")
    expected_python = expected_derivation.get("canonical_external_python_realpath")
    if python_executable != expected_python:
        raise ValueError("closure Python executable is not the canonical external Python")
    executable_paths = [row.get("path") for row in executables]
    if len(executable_paths) != len(set(executable_paths)):
        raise ValueError("duplicate executable closure record")
    executable_by_path = {row.get("path"): row for row in executables}
    python_row = executable_by_path.get(expected_python)
    if (python_row is None
            or python_row.get("size") !=
               expected_derivation.get("canonical_external_python_size")
            or python_row.get("mode") !=
               expected_derivation.get("canonical_external_python_mode")
            or python_row.get("sha256") !=
               expected_derivation.get("canonical_external_python_sha256")):
        raise ValueError("canonical external Python is absent/drifted in closure")
    # A sparse candidate's .venv path must never replace the registered
    # external interpreter, even if a candidate file/symlink happens to exist.
    if root != ROOT:
        candidate_python = root / ".venv-atlas/bin/python"
        if str(candidate_python.resolve()) == expected_python:
            raise ValueError("candidate-root .venv-atlas fallback is forbidden")
    expected_runner_sha256 = base.sha_file(root / RUNNER.relative_to(ROOT))
    replay_strata = config_value.get("replay", {}).get("strata")
    if (not isinstance(replay_strata, list)
            or [row.get("stratum_id") if isinstance(row, Mapping) else None
                for row in replay_strata] != list(EXPECTED_REPLAY_STRATUM_IDS)
            or any(row.get("code_sha256") != expected_runner_sha256
                   for row in replay_strata)
            or any(row.get("environment_sha256") !=
                   expected_derivation.get("canonical_environment_sha256")
                   for row in replay_strata)):
        raise ValueError(
            "protocol-config replay code/environment does not bind every stratum")


def environment_payload(closure: Mapping[str, Any], *, root: Path = ROOT) -> dict[str, Any]:
    commitment = base.strict_json_loads(
        (root / ACTIVE_CONFIG.relative_to(ROOT) / "authorization_commitment.json").read_text(encoding="utf-8"))
    config = _read_root_json(root, str((ACTIVE_CONFIG / "protocol.json").relative_to(ROOT)))
    derivation = config.get("post_m2_runtime", {}).get("environment_derivation")
    if derivation != closure.get("environment_derivation"):
        raise ValueError("config/closure environment derivation mismatch")
    return {
        "schema_version": "msae_v3_environment_allowlist_v2", "protocol_id": PROTOCOL,
        "generation": GENERATION,
        "python_executable": closure["python_executable"], "python_version": closure["python_version"],
        "python_startup_sha256": base.sha_bytes(base.canonical_bytes(closure["python_startup"])),
        "dependency_closure_payload_sha256": base.sha_bytes(base.canonical_bytes(closure)),
        "allowed_native_library_set_sha256": base.sha_bytes(
            base.canonical_bytes(closure["allowed_native_libraries"])),
        "executable_set_sha256": base.sha_bytes(base.canonical_bytes(closure["executables"])),
        "runtime_controller_sha256": base.sha_file(root / RUNTIME.relative_to(ROOT)),
        "runner_sha256": base.sha_file(root / RUNNER.relative_to(ROOT)),
        "launcher_sha256": base.sha_file(root / LAUNCHER.relative_to(ROOT)),
        "deterministic_algorithms": True, "allow_tf32": False,
        "model_revision": base.SNAPSHOT.name, "model_dtype": "float16", "cache_dtype": "float32",
        "layer": 3, "maximum_sequence_length": 128,
        "environment_derivation": derivation,
        "nonce_directory": commitment["nonce_directory"],
        "gpu_lock_directory": commitment["gpu_lock_directory"],
        "offline_environment": dict(FROZEN_WORKER_ENVIRONMENT),
    }


def verify_dependency_closure() -> dict[str, Any]:
    observed = base.read_json(ACTIVE_M4_DATA / "dependency_closure.json")
    expected = closure_payload(checkpoint_registry())
    if (observed != expected
            or (ACTIVE_M4_DATA / "dependency_closure.json").read_bytes() !=
               base.canonical_bytes(observed)):
        raise ValueError("post-M2 dependency closure does not reproduce")
    return observed


def verify_runtime_loaded_libraries(closure: Mapping[str, Any]) -> dict[str, Any]:
    allowed = {row["path"]: row for row in closure["allowed_native_libraries"]}
    for row in closure.get("executables", []):
        allowed[row["path"]] = row
    snapshot_root = Path(closure["model_snapshot"]["path"])
    for row in closure["model_snapshot"]["entries"]:
        path = row.get("realpath") if row.get("type") == "symlink" else str(snapshot_root / row["path"])
        allowed[str(Path(path).resolve(strict=True))] = {
            "path": str(Path(path).resolve(strict=True)), "size": row.get("target_size", row["size"]),
            "sha256": row["sha256"]}
    observed: dict[str, dict[str, Any]] = {}
    for line in Path("/proc/self/maps").read_text(encoding="utf-8").splitlines():
        fields = line.split(maxsplit=5)
        if len(fields) < 6 or not fields[5].startswith("/"):
            continue
        path = fields[5].removesuffix(" (deleted)")
        resolved = str(Path(path).resolve(strict=True))
        if resolved in observed:
            continue
        if resolved not in allowed:
            raise ValueError(f"runtime loaded library outside prescore closure: {resolved}")
        row = allowed[resolved]
        actual = Path(resolved)
        if actual.stat().st_size != row["size"] or base.sha_file(actual) != row["sha256"]:
            raise ValueError(f"runtime loaded library drift: {resolved}")
        observed[resolved] = row
    rows = sorted(observed.values(), key=lambda row: row["path"])
    return {"schema_version": "msae_v3_runtime_native_realization_v1", "entries": rows,
            "entry_count": len(rows), "entries_sha256": base.sha_bytes(base.canonical_bytes(rows))}


def _typed_artifact_paths() -> tuple[str, ...]:
    data = tuple(f"data/msae_independent_measurement_v3/{name}"
                 for name in (*base.V3_DATA_PHASE_FILES["M0"], *base.V3_DATA_PHASE_FILES["M1"],
                              *base.V3_DATA_PHASE_FILES["M2"]))
    gen3_data = tuple(f"data/msae_independent_measurement_v3_post_m2_gen3/{name}"
                      for name in base.V3_DATA_PHASE_FILES["M4"])
    return (*data, *gen3_data, "configs/msae_independent_measurement_v3/protocol.json",
            "configs/msae_independent_measurement_v3/authorization_commitment.json",
            "configs/msae_independent_measurement_v3/ed25519_public.pem",
            "configs/msae_independent_measurement_v3_post_m2_gen3/protocol.json",
            "configs/msae_independent_measurement_v3_post_m2_gen3/authorization_commitment.json",
            "configs/msae_independent_measurement_v3_post_m2_gen3/ed25519_public.pem",
            "configs/msae_independent_measurement_v3_post_m2_gen3/cpu_no_model_public_entry_trace.json",
            "docs/plan-msae-independent-measurement-v3-post-m4-gen3.md",
            "reports/adversarial/msae_independent_measurement_v3_post_m2_gen3_plan.md",
            "reports/adversarial/msae_independent_measurement_v3_post_m2_gen3_implementation.md",
            "reports/adversarial/msae_independent_measurement_v3_post_m2_gen3_post_m3.md",
            "reports/provenance/msae_independent_measurement_v3_post_m2_gen2/m4_failure.json",
            "reports/provenance/msae_independent_measurement_v3/m1_completion_manifest.json",
            "reports/provenance/msae_independent_measurement_v3/m2_completion_manifest.json",
            "reports/provenance/msae_independent_measurement_v3/m3_preflight_attempt_1.json")


def _overlay(relative: str, root: Path | None) -> Path:
    path = (root if root is not None else ROOT) / relative
    if not path.exists():
        raise FileNotFoundError(f"candidate-root input is absent: {relative}")
    return path


def _validate_completion_copy(root: Path, relative: str, expected_sha256: str,
                              expected_names: Sequence[str]) -> dict[str, Any]:
    path = root / relative
    if base.sha_file(path) != expected_sha256:
        raise ValueError(f"reviewed completion digest mismatch: {relative}")
    value = _read_root_json(root, relative)
    entries = value.get("entries")
    if not isinstance(entries, list) or len(entries) != len(expected_names):
        raise ValueError(f"completion entry dimensions drift: {relative}")
    expected_paths = {f"data/msae_independent_measurement_v3/{name}" for name in expected_names}
    if {row.get("path") for row in entries} != expected_paths:
        raise ValueError(f"completion entry path set drift: {relative}")
    for row in entries:
        target = root / row["path"]
        st = target.lstat()
        if (row.get("type") != "regular" or not stat.S_ISREG(st.st_mode)
                or stat.S_ISLNK(st.st_mode) or st.st_size != row.get("size")
                or stat.S_IMODE(st.st_mode) != row.get("mode")
                or base.sha_file(target) != row.get("sha256")):
            raise ValueError(f"completion-bound artifact drift: {row.get('path')}")
    if (value.get("entry_count") != len(entries)
            or value.get("entries_sha256") != base.sha_bytes(base.canonical_bytes(entries))):
        raise ValueError(f"completion entry summary drift: {relative}")
    return value


def _validate_m1_semantics(*, root: Path = ROOT) -> dict[str, Any]:
    prefix = "data/msae_independent_measurement_v3"
    overlap = _read_root_json(root, f"{prefix}/history_overlap.json")
    aliases = _read_root_json(root, f"{prefix}/source_alias_manifest.json")
    fixtures = _read_root_json(root, f"{prefix}/overlap_fixtures.json")
    crosswalk = _read_root_json(root, f"{prefix}/v1_row_crosswalk.json")
    if (overlap.get("schema_version") != "msae_v3_history_overlap_v1"
            or overlap.get("status") != "eligible"
            or overlap.get("blocking_collision_count") != 0
            or overlap.get("blocking_collisions") != []
            or overlap.get("idf_universe_documents") != 24008
            or overlap.get("sealed_payload_content_reads") != 0):
        raise ValueError("M1 overlap semantic gate drift")
    quarantine = overlap.get("quarantine_audit", {})
    if (quarantine.get("content_reads") != 0
            or quarantine.get("blocked_content_open_attempt_count") != 0
            or quarantine.get("before_lstat") != quarantine.get("after_scan_lstat")):
        raise ValueError("M1 quarantine attestation drift")
    if (aliases.get("schema_version") != "msae_v3_source_alias_manifest_v1"
            or aliases.get("selected_count") != 350 or len(aliases.get("entries", [])) != 350):
        raise ValueError("M1 source-alias semantics drift")
    if (fixtures.get("status") != "eligible" or fixtures.get("fixture_count") != 40
            or len(fixtures.get("fixtures", [])) != 40):
        raise ValueError("M1 fixture semantics drift")
    with (root / prefix / "history_census.json").open("rb") as handle:
        census_prefix = handle.read(4096)
    required_census_prefixes = (b'"candidate_pairs":8297', b'"historical_documents":23658',
                                b'"idf_universe_documents":24008')
    if any(item not in census_prefix for item in required_census_prefixes):
        raise ValueError("M1 history census semantics drift")
    rows = crosswalk.get("rows")
    if (crosswalk.get("legacy_status") != "ineligible" or crosswalk.get("legacy_row_count") != 206
            or not isinstance(rows, list) or len(rows) != 206):
        raise ValueError("M1 legacy crosswalk semantics drift")
    return {"overlap_status": "eligible", "blocking_collision_count": 0,
            "historical_documents": 23658, "idf_universe_documents": 24008,
            "source_alias_selected_count": 350, "fixture_count": 40,
            "fixture_status": "eligible", "candidate_pairs": 8297,
            "legacy_crosswalk_rows": 206, "legacy_crosswalk_status": "ineligible",
            "sealed_payload_content_reads": 0}


def _validate_tree_authorization(root: Path) -> dict[str, Any]:
    config_root = root / ACTIVE_CONFIG.relative_to(ROOT)
    config_st = config_root.lstat()
    if (not stat.S_ISDIR(config_st.st_mode) or stat.S_ISLNK(config_st.st_mode)
            or stat.S_IMODE(config_st.st_mode) != 0o700 or config_st.st_uid != os.getuid()):
        raise ValueError("candidate-tree active config directory drift")
    commitment_raw = _regular_bytes(config_root / "authorization_commitment.json", mode=0o644)
    commitment = base.strict_json_loads(commitment_raw.decode("utf-8"))
    if commitment_raw != base.canonical_bytes(commitment):
        raise ValueError("candidate-tree authorization commitment is noncanonical")
    public = _regular_bytes(config_root / "ed25519_public.pem", mode=0o644)
    if (commitment.get("schema_version") != "msae_v3_authorization_commitment_v2"
            or commitment.get("generation") != GENERATION
            or commitment.get("operator_instruction") != OPERATOR_INSTRUCTION
            or commitment.get("operator_instruction_sha256") !=
               base.sha_bytes(OPERATOR_INSTRUCTION.encode("utf-8"))
            or commitment.get("contains_execution_authorization") is not False
            or commitment.get("allowed_scope") != "calibration_replay_only"
            or commitment.get("public_key_sha256") != base.sha_bytes(public)):
        raise ValueError("candidate-tree authorization commitment drift")
    config = _read_root_json(
        root, str((ACTIVE_CONFIG / "protocol.json").relative_to(ROOT)))
    review_gates = config.get("post_m2_runtime", {}).get("review_gates")
    if commitment.get("review_gates") != review_gates:
        raise ValueError("candidate-tree config/commitment review binding mismatch")
    expected_review_gates = _trace_review_gates(
        root, str(review_gates.get("plan_review_sha256", "")),
        str(review_gates.get("implementation_review_sha256", "")))
    if review_gates != expected_review_gates:
        raise ValueError("candidate-tree review gate entries drift")
    expected_private = commitment["private_key_binding"]
    try:
        _validate_private_key_lstat_binding(ACTIVE_PRIVATE_KEY, expected_private)
    except ValueError as exc:
        raise ValueError("candidate-tree external private-key binding drift") from exc
    for key, observed in (("nonce_directory", base._directory_binding(ACTIVE_NONCE_DIR)),
                          ("gpu_lock_directory", base._directory_binding(base.GPU_LOCK_DIR))):
        if any(observed[field] != commitment[key][field]
               for field in ("path", "realpath", "device", "inode", "uid", "mode", "nlink")):
            raise ValueError(f"candidate-tree external {key} binding drift")
    return commitment


def _rooted_generic_build_stage_a(root: Path, raw_config: bytes, config_sha: str,
                                  evidence: Mapping[str, Mapping[str, Any]]) -> dict[str, Any]:
    """Execute the generic Stage-A builder and dependency from one candidate tree.

    The generic builder verifies its dependency via its own ``__file__`` and the
    imported dependency's origin.  Loading both copies explicitly prevents a
    module already cached from the live repository from defeating M4's two-tree
    isolation.
    """
    scripts = root / "scripts"
    dependency_path = scripts / "msae_measurement_v2.py"
    builder_path = scripts / "msae_measurement_remediation_v1.py"
    for path in (dependency_path, builder_path):
        st = path.lstat()
        if (not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode)
                or st.st_uid != os.getuid() or st.st_nlink != 1):
            raise ValueError(f"rooted Stage-A module identity drift: {path}")
    previous_dependency = sys.modules.get("msae_measurement_v2")
    module_name = f"_msae_measurement_remediation_rooted_{os.getpid()}_{id(root)}"
    try:
        dependency_spec = continuation.source_only_module_spec(
            "msae_measurement_v2", dependency_path)
        if dependency_spec is None or dependency_spec.loader is None:
            raise ValueError("cannot load rooted generic Stage-A dependency")
        dependency = importlib.util.module_from_spec(dependency_spec)
        sys.modules["msae_measurement_v2"] = dependency
        dependency_spec.loader.exec_module(dependency)
        builder_spec = continuation.source_only_module_spec(module_name, builder_path)
        if builder_spec is None or builder_spec.loader is None:
            raise ValueError("cannot load rooted generic Stage-A builder")
        builder = importlib.util.module_from_spec(builder_spec)
        sys.modules[module_name] = builder
        builder_spec.loader.exec_module(builder)
        return builder.build_stage_a(raw_config, config_sha, evidence)
    finally:
        continuation.sanitize_local_module_search_path(scripts)
        sys.modules.pop(module_name, None)
        if previous_dependency is None:
            sys.modules.pop("msae_measurement_v2", None)
        else:
            sys.modules["msae_measurement_v2"] = previous_dependency


def stage_a_payload(*, overlay_root: Path | None = None) -> dict[str, Any]:
    root = overlay_root if overlay_root is not None else ROOT
    config_path = root / ACTIVE_CONFIG.relative_to(ROOT) / "protocol.json"
    config_raw = config_path.read_bytes()
    config_sha = base.sha_bytes(config_raw)
    config = base.strict_json_loads(config_raw.decode("utf-8"))
    generic_config = generic_config_projection(config)
    generic_config_raw = base.canonical_bytes(generic_config)
    generic_config_sha = base.sha_bytes(generic_config_raw)
    reviewed_m2 = config["post_m2_runtime"]["reviewed_m2_completion_sha256"]
    if reviewed_m2 != M2_REVIEWED_COMPLETION_SHA256:
        raise ValueError("Stage A is not bound to the reviewed M2 completion pin")
    m1_completion = _validate_completion_copy(
        root, "reports/provenance/msae_independent_measurement_v3/m1_completion_manifest.json",
        M1_REVIEWED_COMPLETION_SHA256, base.V3_DATA_PHASE_FILES["M1"])
    m2_completion = _validate_completion_copy(
        root, "reports/provenance/msae_independent_measurement_v3/m2_completion_manifest.json",
        reviewed_m2, base.V3_DATA_PHASE_FILES["M2"])
    m1_semantics = _validate_m1_semantics(root=root)
    m2_semantics = _validate_m2_semantics(root=root)
    if m1_completion.get("success_semantics") != m1_semantics:
        raise ValueError("M1 completion semantics do not close")
    if m2_completion.get("success_semantics") != m2_semantics:
        raise ValueError("M2 completion semantics do not close")
    checkpoints = checkpoint_registry(root=root)
    config_review = config.get("post_m2_runtime", {}).get("review_gates", {})
    expected_config = _protocol_config_payload(
        checkpoints, reviewed_m2,
        plan_review_sha256=str(config_review.get("plan_review_sha256", "")),
        implementation_review_sha256=str(
            config_review.get("implementation_review_sha256", "")),
        root=root)
    if config != expected_config or config_raw != base.canonical_bytes(config):
        raise ValueError("active protocol config does not reproduce")
    _validate_tree_authorization(root)
    registry = base.read_json(_overlay("data/msae_independent_measurement_v3_post_m2_gen3/endpoint_registry.json", overlay_root))
    expected_registry = endpoint_registry()
    validate_endpoint_registry(registry)
    if registry != expected_registry:
        raise ValueError("endpoint registry semantic mismatch")
    closure = base.read_json(_overlay("data/msae_independent_measurement_v3_post_m2_gen3/dependency_closure.json", overlay_root))
    if closure != closure_payload(checkpoints, root=root):
        raise ValueError("dependency closure semantic mismatch")
    environment = base.read_json(_overlay("data/msae_independent_measurement_v3_post_m2_gen3/environment_allowlist.json", overlay_root))
    if environment != environment_payload(closure, root=root):
        raise ValueError("environment allowlist semantic mismatch")
    required = config["stages"]["A"]["required"]
    exact_required = ["candidate_confirmation_source", "immutable_source_revision",
                      "independent_grouping_provenance", "label_support_audit",
                      "construct_inventory", "counterfactual_template_specification",
                      "tolerance_ladder_frozen", "dependency_attestation"]
    if required != exact_required or config["stages"]["A"].get("optional") != []:
        raise ValueError("Stage-A endpoint registry is not exact")
    artifacts = {
        "candidate_confirmation_source": root / "data/msae_independent_measurement_v3/history_overlap.json",
        "immutable_source_revision": root / "data/msae_independent_measurement_v3/source_alias_manifest.json",
        "independent_grouping_provenance": root / "data/msae_independent_measurement_v3/v1_row_crosswalk.json",
        "label_support_audit": root / "data/msae_independent_measurement_v3/support.json",
        "construct_inventory": _overlay("data/msae_independent_measurement_v3_post_m2_gen3/endpoint_registry.json", overlay_root),
        "counterfactual_template_specification": root / "data/msae_independent_measurement_v3/prefix_templates.json",
        "tolerance_ladder_frozen": config_path,
        "dependency_attestation": _overlay("data/msae_independent_measurement_v3_post_m2_gen3/dependency_closure.json", overlay_root),
    }
    def canonical_artifact_path(path: Path) -> str:
        if not path.is_relative_to(root):
            raise ValueError(f"Stage-A artifact escapes candidate root: {path}")
        return path.relative_to(root).as_posix()

    evidence = {name: {"schema_version": "msae_endpoint_evidence_v1",
                       "protocol_config_sha256": generic_config_sha, "endpoint_name": name,
                       "category": "stage_a", "status": "eligible", "reasons": [],
                       "evidence_artifact_sha256": base.sha_file(path),
                       "observed_value": {"artifact_path": canonical_artifact_path(path),
                                          "artifact_sha256": base.sha_file(path)}}
                for name, path in artifacts.items() if name != "dependency_attestation"}
    generic = _rooted_generic_build_stage_a(root, generic_config_raw,
                                            generic_config_sha, evidence)
    typed = {relative: base.sha_file(_overlay(relative, overlay_root))
             for relative in _typed_artifact_paths()}
    scientific = {"m1_completion_sha256": M1_REVIEWED_COMPLETION_SHA256,
                  "m2_completion_sha256": reviewed_m2,
                  "endpoint_registry_payload_sha256": base.sha_bytes(base.canonical_bytes(registry)),
                  "checkpoint_registry_payload_sha256": base.sha_bytes(base.canonical_bytes(checkpoints)),
                  "closure_payload_sha256": base.sha_bytes(base.canonical_bytes(closure)),
                  "environment_payload_sha256": base.sha_bytes(base.canonical_bytes(environment)),
                  "generic_protocol_config_sha256": generic_config_sha,
                  "m1_semantics": m1_semantics, "m2_semantics": m2_semantics,
                  "authorization_commitment_sha256": base.sha_file(
                      root / ACTIVE_CONFIG.relative_to(ROOT) / "authorization_commitment.json")}
    ready = bool(generic.get("stage_ready") is True)
    return {"schema_version": "msae_exposed_source_stage_a_v4", "protocol_id": PROTOCOL,
            "claim_scope": "exposed_source_technical_measurement_replication",
            "confirmation_partition_status": "replacement_required_not_run",
            "protocol_config_sha256": config_sha, "typed_artifact_sha256": typed,
            "typed_artifact_set_sha256": base.sha_bytes(base.canonical_bytes(typed)),
            "scientific_gate_attestations": scientific, "base_stage_a": generic,
            "stage_ready": ready, "blockers": [] if ready else ["base_contract"]}


def validate_stage_a() -> dict[str, Any]:
    path = ACTIVE_PROV / "stage_a.json"
    observed = base.read_json(path)
    expected = stage_a_payload()
    if observed != expected or path.read_bytes() != base.canonical_bytes(observed):
        raise ValueError("post-M2 Stage A does not reproduce")
    if observed.get("stage_ready") is not True:
        raise ValueError("Stage A is not ready")
    return observed


M4_NEW = ("data/msae_independent_measurement_v3_post_m2_gen3/dependency_closure.json",
          "data/msae_independent_measurement_v3_post_m2_gen3/endpoint_registry.json",
          "data/msae_independent_measurement_v3_post_m2_gen3/environment_allowlist.json",
          "reports/provenance/msae_independent_measurement_v3_post_m2_gen3/stage_a.json",
          "reports/provenance/msae_independent_measurement_v3_post_m2_gen3/status.json",
          "reports/provenance/msae_independent_measurement_v3_post_m2_gen3/prescore_candidate_manifest.json")


def _candidate_relatives(*, include_m4: bool, root: Path = ROOT,
                         checkpoints: Sequence[Mapping[str, Any]] | None = None) -> list[str]:
    bound_checkpoints = checkpoint_registry(root=root) if checkpoints is None else list(checkpoints)
    paths = _closure_local_relative_names(bound_checkpoints, root=root)
    if include_m4:
        paths = [*paths, *M4_NEW[:-1]]
    if len(paths) != len(set(paths)):
        raise AssertionError("duplicate candidate relative")
    return sorted(paths, key=lambda value: value.encode("utf-8"))


def _sparse_copy(source: Path, destination: Path, mode: int) -> None:
    source_fd = os.open(source, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
    destination_fd = os.open(destination, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                             mode)
    try:
        size = os.fstat(source_fd).st_size
        os.ftruncate(destination_fd, size)
        offset = 0
        while offset < size:
            try:
                data = os.lseek(source_fd, offset, os.SEEK_DATA)
            except OSError as error:
                if error.errno == errno.ENXIO:  # the remainder is a hole.
                    break
                raise
            hole = os.lseek(source_fd, data, os.SEEK_HOLE)
            position = data
            while position < hole:
                os.lseek(source_fd, position, os.SEEK_SET)
                chunk = os.read(source_fd, min(8 << 20, hole - position))
                if not chunk:
                    raise IOError(f"short sparse-copy read: {source}")
                os.lseek(destination_fd, position, os.SEEK_SET)
                written = 0
                while written < len(chunk):
                    count = os.write(destination_fd, chunk[written:])
                    if count <= 0:
                        raise IOError(f"short sparse-copy write: {destination}")
                    written += count
                position += len(chunk)
            offset = hole
        os.fchmod(destination_fd, mode)
        os.fsync(destination_fd)
    finally:
        os.close(source_fd)
        os.close(destination_fd)


def _m4_input_relatives() -> list[str]:
    checkpoints = checkpoint_registry()
    return sorted(set(_candidate_relatives(include_m4=False, root=ROOT, checkpoints=checkpoints)) |
                  set(_closure_local_relatives(checkpoints, root=ROOT)),
                  key=lambda value: value.encode("utf-8"))


def _copy_complete_candidate_tree(root: Path) -> None:
    os.mkdir(root, 0o700)
    os.chmod(root, 0o700)
    def ensure_parent(relative: str) -> None:
        current = root
        source_current = ROOT
        for component in Path(relative).parent.parts:
            current = current / component
            source_current = source_current / component
            source_dir_st = source_current.lstat()
            if not stat.S_ISDIR(source_dir_st.st_mode) or stat.S_ISLNK(source_dir_st.st_mode):
                raise ValueError(f"candidate source ancestor is not a directory: {source_current}")
            if not current.exists():
                current.mkdir(mode=stat.S_IMODE(source_dir_st.st_mode))
                os.chmod(current, stat.S_IMODE(source_dir_st.st_mode))
            else:
                current_st = current.lstat()
                if (not stat.S_ISDIR(current_st.st_mode) or stat.S_ISLNK(current_st.st_mode)
                        or stat.S_IMODE(current_st.st_mode) != stat.S_IMODE(source_dir_st.st_mode)):
                    raise ValueError(f"candidate-tree ancestor drift: {current}")

    for relative in _m4_input_relatives():
        source = ROOT / relative
        destination = root / relative
        st = source.lstat()
        if not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode):
            raise ValueError(f"non-regular candidate source: {relative}")
        ensure_parent(relative)
        _sparse_copy(source, destination, stat.S_IMODE(st.st_mode))
    # M4 output files do not exist yet, but their live parent directories do.
    # Seed those ancestors so the two trees and installed projection bind the
    # same directory modes (not mkdir/umask defaults).
    for relative in M4_NEW:
        ensure_parent(relative)


def _full_tree_manifest(root: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    root_st = root.lstat()
    rows.append({"path": ".", "type": "directory", "mode": stat.S_IMODE(root_st.st_mode),
                 "uid": root_st.st_uid, "nlink": root_st.st_nlink})
    for path in sorted(root.rglob("*"), key=lambda item: item.relative_to(root).as_posix().encode("utf-8")):
        st = path.lstat()
        relative = path.relative_to(root).as_posix()
        if stat.S_ISDIR(st.st_mode) and not stat.S_ISLNK(st.st_mode):
            rows.append({"path": relative, "type": "directory", "mode": stat.S_IMODE(st.st_mode),
                         "uid": st.st_uid, "nlink": st.st_nlink})
        elif stat.S_ISREG(st.st_mode) and not stat.S_ISLNK(st.st_mode):
            rows.append({"path": relative, "type": "regular", "mode": stat.S_IMODE(st.st_mode),
                         "uid": st.st_uid, "nlink": st.st_nlink,
                         "size": st.st_size, "sha256": base.sha_file(path)})
        else:
            raise ValueError(f"non-regular object in complete M4 tree: {relative}")
    return rows


def _tree_entries(root: Path, relatives: Sequence[str]) -> list[dict[str, Any]]:
    entries = []
    for relative in relatives:
        entry = _regular_entry(root / relative, root=root)
        entry["path"] = relative
        entries.append(entry)
    return entries


def _candidate_directory_relatives(relatives: Iterable[str]) -> list[str]:
    result: set[str] = set()
    for relative in relatives:
        parent = Path(relative).parent
        while parent != Path("."):
            result.add(parent.as_posix())
            parent = parent.parent
    return sorted(result, key=lambda value: value.encode("utf-8"))


def _directory_entries(root: Path, relatives: Iterable[str]) -> list[dict[str, Any]]:
    rows = []
    for relative in _candidate_directory_relatives(relatives):
        path = root / relative
        st = path.lstat()
        if not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode):
            raise ValueError(f"candidate ancestor is not a real directory: {path}")
        rows.append({"path": relative, "type": "directory", "mode": stat.S_IMODE(st.st_mode),
                     "uid": st.st_uid, "nlink": st.st_nlink})
    return rows


def _git_status() -> list[str]:
    raw = subprocess.check_output(["/usr/bin/git", "status", "--porcelain=v2", "--untracked-files=all"],
                                  cwd=ROOT, text=True)
    return raw.splitlines()


def _status_path(line: str) -> str:
    if line.startswith("? ") or line.startswith("! "):
        return line[2:]
    # Porcelain-v2 ordinary records use eight fixed metadata fields then path.
    parts = line.split(" ", 8)
    if len(parts) != 9:
        raise ValueError(f"unsupported porcelain-v2 status record: {line!r}")
    return parts[8]


def _classify_repository_status(lines: Sequence[str], candidate_paths: set[str],
                                *, root: Path = ROOT) -> list[dict[str, str]]:
    data_root = root / V3_DATA.relative_to(ROOT)
    protected = base.read_json(data_root / "protected_v1_manifest.json")["entries"]
    protected += base.read_json(data_root / "protected_v2_manifest.json")["entries"]
    protected_paths = {row["path"] for row in protected}
    baseline_paths = {row["path"] for row in
                      base.read_json(data_root / "data_baseline_manifest.json")["entries"]}
    rows = []
    for line in lines:
        path = _status_path(line)
        if path in candidate_paths or any(item.startswith(path.rstrip("/") + "/") for item in candidate_paths):
            classification = "candidate"
        elif path in protected_paths or path in baseline_paths or any(
                item.startswith(path.rstrip("/") + "/") for item in protected_paths | baseline_paths):
            classification = "protected_baseline"
        else:
            raise ValueError(f"unclassified repository status path: {path}")
        rows.append({"line": line, "path_projection": path, "classification": classification})
    return rows


def candidate_manifest_payload(tree_root: Path, repository_status: Sequence[str],
                               directory_projection: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    tree_checkpoints = checkpoint_registry(root=tree_root)
    relatives = _candidate_relatives(include_m4=True, root=tree_root,
                                     checkpoints=tree_checkpoints)
    entries = _tree_entries(tree_root, relatives)
    directories = [dict(row) for row in directory_projection]
    if [row["path"] for row in directories] != _candidate_directory_relatives(relatives):
        raise ValueError("supplied live directory projection path set mismatch")
    # The sparse build has fewer siblings, so nlink intentionally differs.
    # Its type/mode/owner must still match the separately frozen live row.
    tree_directories = {row["path"]: row for row in _directory_entries(tree_root, relatives)}
    for row in directories:
        tree_row = tree_directories[row["path"]]
        if any(tree_row[key] != row[key] for key in ("path", "type", "mode", "uid")):
            raise ValueError(f"sparse-tree directory metadata drift: {row['path']}")
    classifications = _classify_repository_status(repository_status, set(relatives) | {M4_NEW[-1]},
                                                    root=tree_root)
    stage_sha = base.sha_file(tree_root / M4_NEW[3])
    closure_sha = base.sha_file(tree_root / M4_NEW[0])
    commitment = _read_root_json(tree_root, str((ACTIVE_CONFIG / "authorization_commitment.json").relative_to(ROOT)))
    return {"schema_version": "msae_v3_prescore_candidate_manifest_v3", "protocol_id": PROTOCOL,
            "generation": GENERATION,
            "candidate_root_realpath": str(ROOT.resolve(strict=True)),
            "candidate_files": entries,
            "candidate_directories": directories,
            "candidate_directory_tree_sha256": base.sha_bytes(base.canonical_bytes(directories)),
            "candidate_file_paths": relatives,
            "candidate_tree_sha256": base.sha_bytes(base.canonical_bytes(entries)),
            "dependency_closure_sha256": closure_sha, "stage_a_sha256": stage_sha,
            "repository_status": list(repository_status),
            "repository_status_classification": classifications,
            "required_absent_post_review_outputs": [str(PRESCORE_REVIEW.relative_to(ROOT)), ACTIVE_RUN_REL],
            "required_external_state": {
                "private_key": commitment["private_key_binding"],
                "nonce_directory": commitment["nonce_directory"],
                "gpu_lock_directory": base._directory_binding(base.GPU_LOCK_DIR),
                "required_empty_nonce_directory": True,
                "required_absent_build_roots": [str(M4_PRIMARY), str(M4_REBUILD)],
                "required_absent_tmux_socket": (
                    f"/tmp/msae_independent_measurement_v3_post_m2_gen3_{stage_sha}.sock"),
                "required_absent_prescore_evidence_rule": {
                    "schema_version": "msae_v3_manifest_digest_evidence_paths_v1",
                    "check_template": ("/tmp/msae_independent_measurement_v3_post_m2_gen3_"
                                       "{manifest_sha256}.prescore.check.json"),
                    "trace_template": ("/tmp/msae_independent_measurement_v3_post_m2_gen3_"
                                       "{manifest_sha256}.prescore.trace.log"),
                    "manifest_sha256_pattern": "[0-9a-f]{64}"}},
            "quarantined_entries": [base._quarantine_entry(rel) for rel in sorted(base.QUARANTINED)],
            "sealed_payload_content_reads": 0, "self_hash_excluded": True}


def _anticipated_status() -> list[str]:
    current = _git_status()
    transaction_relative = (M4_TRANSACTION.relative_to(ROOT).as_posix()
                            if M4_TRANSACTION.is_relative_to(ROOT) else None)
    output_paths = set(M4_NEW)
    current = [line for line in current
               if _status_path(line) not in output_paths
               and not (transaction_relative is not None
                        and (_status_path(line) == transaction_relative
                             or _status_path(line).startswith(transaction_relative + "/")))]
    tracked = [line for line in current if not line.startswith("? ")]
    untracked = {line[2:]: line for line in current if line.startswith("? ")}
    # ``data/`` is ignored by the repository.  Git will not report the three
    # data products after installation, so the pre-install projection must not
    # synthesize status rows that the post-install verifier can never observe.
    # The two provenance outputs are unignored and the manifest excludes only
    # itself to avoid a self-hash cycle.
    for relative in M4_NEW[3:-1]:
        untracked.setdefault(relative, f"? {relative}")
    return [*tracked, *(untracked[path] for path in sorted(untracked, key=lambda value: value.encode("utf-8")))]


def _historical_manifest_directory_projection(
    current: Sequence[Mapping[str, Any]], *, recovery: bool,
) -> list[dict[str, Any]]:
    """Remove only the validated transaction-subdir nlink from M4 evidence."""
    rows = [dict(row) for row in current]
    if recovery and _path_present(M4_TRANSACTION):
        parent = M4_TRANSACTION.parent.relative_to(ROOT).as_posix()
        matches = [row for row in rows if row.get("path") == parent]
        if len(matches) != 1 or matches[0].get("nlink", 0) < 3:
            raise ValueError("M4 recovery provenance-directory projection drift")
        matches[0]["nlink"] -= 1
    return rows


def _materialize_complete_m4(root: Path, checkpoints: list[dict[str, Any]],
                             anticipated_status: list[str],
                             directory_projection: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    _copy_complete_candidate_tree(root)
    tree_checkpoints = checkpoint_registry(root=root)
    if tree_checkpoints != checkpoints:
        raise ValueError("M4 checkpoint reconstruction differs from live frozen inputs")
    closure = closure_payload(tree_checkpoints, root=root)
    registry = endpoint_registry()
    environment = environment_payload(closure, root=root)
    for relative, value in zip(M4_NEW[:3], (closure, registry, environment)):
        base.write_once(root / relative, base.canonical_bytes(value), 0o644)
    stage = stage_a_payload(overlay_root=root)
    base.write_once(root / M4_NEW[3], base.canonical_bytes(stage), 0o644)
    status_payload = {"schema_version": "msae_v3_prescore_status_v2", "protocol_id": PROTOCOL,
                      "status": "ready_prescore_review" if stage["stage_ready"] else "blocked_prescore",
                      "stage_a_ready": stage["stage_ready"],
                      "stage_a_sha256": base.sha_file(root / M4_NEW[3]),
                      "stage_b": "not_run", "stage_c": "not_run",
                      "confirmation_partition": "replacement_required"}
    base.write_once(root / M4_NEW[4], base.canonical_bytes(status_payload), 0o644)
    manifest = candidate_manifest_payload(root, anticipated_status, directory_projection)
    manifest_raw = base.canonical_bytes(manifest)
    manifest_sha = base.sha_bytes(manifest_raw)
    if any(_path_present(path) for path in _prescore_evidence_paths(manifest_sha)):
        raise FileExistsError("digest-derived prescore evidence exists before M4")
    base.write_once(root / M4_NEW[5], manifest_raw, 0o644)
    return stage


def _install_transaction(root: Path, relatives: Sequence[str], payloads: Mapping[str, bytes],
                         schema: str) -> None:
    def verify_file(path: Path, raw: bytes, mode: int) -> None:
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
        try:
            before = os.fstat(fd)
            chunks = []
            while True:
                chunk = os.read(fd, 8 << 20)
                if not chunk:
                    break
                chunks.append(chunk)
            after = os.fstat(fd)
        finally:
            os.close(fd)
        path_st = path.lstat()
        identity = (before.st_dev, before.st_ino, before.st_mode, before.st_uid,
                    before.st_nlink, before.st_size)
        if (identity != (after.st_dev, after.st_ino, after.st_mode, after.st_uid,
                         after.st_nlink, after.st_size)
                or (before.st_dev, before.st_ino) != (path_st.st_dev, path_st.st_ino)
                or not stat.S_ISREG(before.st_mode) or stat.S_ISLNK(path_st.st_mode)
                or before.st_uid != os.getuid() or before.st_nlink != 1
                or stat.S_IMODE(before.st_mode) != mode or b"".join(chunks) != raw):
            raise ValueError(f"transaction file identity/content drift: {path}")

    expected = set(relatives)
    if set(payloads) != expected:
        raise ValueError("transaction payload set mismatch")
    states = {relative: (ROOT / relative).exists() for relative in relatives}
    _require_ordered_output_prefix(relatives, states)
    if not root.exists() and any(states.values()):
        for relative, raw in payloads.items():
            if states[relative]:
                verify_file(ROOT / relative, raw, 0o644)
        if all(states.values()):
            return
        # A power loss can persist target entries while losing the transaction
        # directory entry.  Exact rebuilt payloads authenticate the surviving
        # prefix; recreate staging and resume the remaining create-once files.
    if not root.exists():
        root.mkdir(mode=0o700)
        os.chmod(root, 0o700)
        base._fsync_directory(root.parent)
    st = root.lstat()
    if (not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)
            or stat.S_IMODE(st.st_mode) != 0o700 or st.st_uid != os.getuid()):
        raise ValueError("invalid transaction directory")
    allowed = {"transaction.json"} | {f"{i:02d}.payload" for i in range(len(relatives))}
    observed = {entry.name for entry in os.scandir(root)}
    if observed - allowed:
        raise ValueError(f"undeclared transaction entries: {sorted(observed - allowed)}")
    entries = []
    for i, relative in enumerate(relatives):
        raw = payloads[relative]
        staged = root / f"{i:02d}.payload"
        if staged.exists():
            verify_file(staged, raw, 0o600)
        else:
            base.write_once(staged, raw, 0o600)
        entries.append({"relative": relative, "staged": staged.name,
                        "size": len(raw), "sha256": base.sha_bytes(raw), "mode": 0o644})
    descriptor = base.canonical_bytes({"schema_version": schema, "protocol_id": PROTOCOL,
                                       "entries": entries,
                                       "entries_sha256": base.sha_bytes(base.canonical_bytes(entries))})
    descriptor_path = root / "transaction.json"
    if descriptor_path.exists():
        if _regular_bytes(descriptor_path, mode=0o600) != descriptor:
            raise ValueError("transaction descriptor drift")
    else:
        base.write_once(descriptor_path, descriptor, 0o600)
    base._fsync_directory(root)
    for relative in relatives:
        destination = ROOT / relative
        raw = payloads[relative]
        if destination.exists():
            verify_file(destination, raw, 0o644)
        else:
            base.write_once(destination, raw, 0o644)
            base._fsync_directory(destination.parent)
    descriptor_path.unlink()
    for row in entries:
        (root / row["staged"]).unlink()
    root.rmdir()
    base._fsync_directory(root.parent)


def _compare_complete_m4_trees(left_root: Path, right_root: Path,
                               left_stage: Mapping[str, Any],
                               right_stage: Mapping[str, Any]) -> dict[str, bytes]:
    if (_full_tree_manifest(left_root) != _full_tree_manifest(right_root)
            or left_stage != right_stage):
        raise ValueError("independent complete M4 trees differ")
    payloads: dict[str, bytes] = {}
    for relative in M4_NEW:
        left = _regular_bytes(left_root / relative, mode=0o644)
        right = _regular_bytes(right_root / relative, mode=0o644)
        if left != right:
            raise ValueError(f"independent M4 bytes differ: {relative}")
        payloads[relative] = left
    return payloads


def _verify_live_m4_inputs(snapshot: Sequence[Mapping[str, Any]],
                           initial_status: Sequence[str],
                           directory_projection: Sequence[Mapping[str, Any]]) -> None:
    relatives = [str(row["path"]) for row in snapshot]
    if _tree_entries(ROOT, relatives) != list(snapshot):
        raise ValueError("live M4 inputs drifted after candidate-tree snapshot")
    if _git_status() != list(initial_status):
        raise ValueError("repository status drifted after candidate-tree snapshot")
    if _directory_entries(ROOT, _candidate_relatives(include_m4=True)) != list(directory_projection):
        raise ValueError("live candidate directory projection drifted during M4")
    base.verify_baseline_projection("M2")
    base.verify_protected_v1()
    base.verify_protected_v2()
    base.validate_source_exposure()


def _quarantine_metadata_rows() -> list[dict[str, Any]]:
    """Revalidate sealed identities without opening any sealed payload."""
    rows = [base._quarantine_entry(relative) for relative in sorted(base.QUARANTINED)]
    if any(row.get("nlink") != 1 for row in rows):
        # nlink==1 is also the exhaustive same-inode hard-link-alias proof.
        raise ValueError("quarantined payload has a same-inode alias")
    return rows


@contextlib.contextmanager
def quarantine_guard() -> Iterable[dict[str, Any]]:
    """Install the sealed-content tripwire and prove stable metadata around work."""
    before = _quarantine_metadata_rows()
    try:
        with base.quarantine_open_tripwire() as state:
            if state.get("before_lstat") != before:
                raise ValueError("quarantine tripwire initial metadata mismatch")
            try:
                yield state
            finally:
                if state.get("blocked_content_open_attempts"):
                    raise AssertionError(
                        "quarantine tripwire recorded a sealed content-open attempt")
    finally:
        after = _quarantine_metadata_rows()
        if after != before:
            raise ValueError(
                "quarantined payload metadata changed during guarded operation")


def _post_m3_forbidden_tmp_patterns() -> tuple[str, ...]:
    return (
        "msae_independent_measurement_v3_post_m2_gen3_*.prescore.check.json",
        "msae_independent_measurement_v3_post_m2_gen3_*.prescore.trace.log",
        "msae_independent_measurement_v3_post_m2_gen3_*.sock",
        # Immutable gen2 uses the older undifferentiated v3 prefix.
        "msae_independent_measurement_v3_*.prescore.check.json",
        "msae_independent_measurement_v3_*.prescore.trace.log",
        "msae_independent_measurement_v3_*.sock",
    )


def _m4_recovery_present() -> bool:
    return any(_path_present(path) for path in (
        M4_TRANSACTION, M4_PRIMARY, M4_REBUILD,
        *(ROOT / relative for relative in M4_NEW),
    ))


def _require_ordered_output_prefix(
    relatives: Sequence[str], states: Mapping[str, bool],
) -> None:
    """Reject a crash state impossible for the registered ordered installer."""
    seen_absent = False
    for relative in relatives:
        present = states.get(relative) is True
        if seen_absent and present:
            raise ValueError("installed output set is not an ordered prefix")
        if not present:
            seen_absent = True


def _validate_m4_recovery_artifacts() -> None:
    """Validate crash-left M4 objects without trusting their content bytes."""
    for path in (M4_PRIMARY, M4_REBUILD, M4_TRANSACTION):
        if not _path_present(path):
            continue
        st = path.lstat()
        if (not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)
                or stat.S_IMODE(st.st_mode) != 0o700 or st.st_uid != os.getuid()):
            raise ValueError(f"invalid M4 recovery directory: {path}")
    if _path_present(M4_TRANSACTION):
        allowed = {"transaction.json"} | {
            f"{index:02d}.payload" for index in range(len(M4_NEW))}
        observed = {entry.name for entry in os.scandir(M4_TRANSACTION)}
        if not observed <= allowed:
            raise ValueError(f"undeclared M4 recovery transaction entries: {observed - allowed}")
        for name in observed:
            _regular_bytes(M4_TRANSACTION / name, mode=0o600)
    output_states = {relative: _path_present(ROOT / relative) for relative in M4_NEW}
    _require_ordered_output_prefix(M4_NEW, output_states)
    for relative in M4_NEW:
        path = ROOT / relative
        if output_states[relative]:
            _regular_bytes(path, mode=0o644)


def _post_m3_state_binding(*, allow_m4_recovery: bool = False) -> dict[str, Any]:
    """Reconstruct the exact post-M3/pre-M4 review subject and absence set."""
    _validate_gen3_review_namespace("post_m3")
    # The create-once setup already verified public/private agreement.  This
    # independent post-M3 subject deliberately revalidates only the committed
    # private-key lstat identity; the private key's content remains unread.
    _verify_existing_authorization_state(verify_private_content=False)
    _validate_gen2_terminal_namespace(require_failure=True)
    _verify_live_cpu_no_model_trace()
    config_names = {"protocol.json", "authorization_commitment.json",
                    "ed25519_public.pem", "cpu_no_model_public_entry_trace.json"}
    _exact_directory_entries(ACTIVE_CONFIG, config_names, mode=0o700)
    for name in sorted(config_names):
        _regular_bytes(ACTIVE_CONFIG / name, mode=0o644)
    if allow_m4_recovery:
        _validate_m4_recovery_artifacts()
    elif _m4_recovery_present():
        raise ValueError("post-M3 subject has crash-left M4 recovery artifacts")
    prov_children = {
        Path(relative).name for relative in M4_NEW[3:]
        if _path_present(ROOT / relative)
    }
    if _path_present(M4_TRANSACTION):
        prov_children.add(M4_TRANSACTION.name)
    data_children = {
        Path(relative).name for relative in M4_NEW[:3]
        if _path_present(ROOT / relative)
    }
    _exact_directory_entries(
        ACTIVE_PROV, prov_children if allow_m4_recovery else set(), mode=0o700)
    _exact_directory_entries(
        ACTIVE_M4_DATA, data_children if allow_m4_recovery else set(), mode=0o700)
    _exact_directory_entries(ACTIVE_STATE, {"nonces"}, mode=0o700)
    _exact_directory_entries(ACTIVE_NONCE_DIR, set(), mode=0o700)
    private_st = ACTIVE_PRIVATE_KEY.lstat()
    private_lstat = {
        "path": str(ACTIVE_PRIVATE_KEY), "device": private_st.st_dev,
        "inode": private_st.st_ino, "uid": private_st.st_uid,
        "mode": stat.S_IMODE(private_st.st_mode), "size": private_st.st_size,
        "nlink": private_st.st_nlink, "mtime_ns": private_st.st_mtime_ns,
        "ctime_ns": private_st.st_ctime_ns, "content_read_for_this_binding": False,
    }
    if (not stat.S_ISREG(private_st.st_mode) or stat.S_ISLNK(private_st.st_mode)
            or private_lstat["mode"] != 0o600 or private_st.st_uid != os.getuid()
            or private_st.st_nlink != 1):
        raise ValueError("post-M3 private-key lstat drift")
    exact_absent = [
        *(ROOT / relative for relative in M4_NEW), M4_TRANSACTION,
        M4_PRIMARY, M4_REBUILD, PRESCORE_REVIEW, ACTIVE_RUN_ROOT,
        *(ROOT / relative for relative in predecessor_runtime.M4_NEW),
        predecessor_runtime.M4_TRANSACTION, predecessor_runtime.M4_PRIMARY,
        predecessor_runtime.M4_REBUILD, predecessor_runtime.PRESCORE_REVIEW,
        predecessor_runtime.ACTIVE_RUN_ROOT,
    ]
    recoverable_paths = {
        *(ROOT / relative for relative in M4_NEW),
        M4_TRANSACTION, M4_PRIMARY, M4_REBUILD,
    }
    for path in exact_absent:
        if _path_present(path) and not (allow_m4_recovery and path in recoverable_paths):
            raise ValueError(f"post-M3 downstream-absence binding failed: {path}")
    tmp = Path("/tmp")
    patterned = []
    for pattern in _post_m3_forbidden_tmp_patterns():
        matches = sorted(str(path) for path in tmp.glob(pattern))
        if matches:
            raise ValueError(f"post-M3 derived downstream output exists: {matches}")
        patterned.append({"pattern": str(tmp / pattern), "matches": []})
    if any(predecessor_runtime.ACTIVE_NONCE_DIR.iterdir()):
        raise ValueError("gen2 nonce output exists")
    absence = {
        "exact_paths": sorted(str(path) for path in exact_absent),
        "derived_path_patterns": patterned,
        "gen3_nonce_children": [], "gen2_nonce_children": [],
        "tmux_session_rule": "dedicated_session_exists_only_under_dedicated_socket",
        "post_m3_review_self_excluded": str(POST_M3_REVIEW.relative_to(ROOT)),
        "gen2_exception": str(GEN2_FAILURE_PATH.relative_to(ROOT)),
    }
    provenance_binding = base._directory_binding(ACTIVE_PROV)
    if allow_m4_recovery and _path_present(M4_TRANSACTION):
        # The historical post-M3 subject was reviewed before the transaction
        # subdirectory incremented the parent's link count.
        provenance_binding = {**provenance_binding,
                              "nlink": provenance_binding["nlink"] - 1}
    directory_bindings = {
        "config": base._directory_binding(ACTIVE_CONFIG),
        "provenance": provenance_binding,
        "m4_data": base._directory_binding(ACTIVE_M4_DATA),
        "state": base._directory_binding(ACTIVE_STATE),
        "nonce": base._directory_binding(ACTIVE_NONCE_DIR),
    }
    return {
        "schema_version": "msae_v3_gen3_post_m3_review_subject_v1",
        "config_entries": [_regular_entry(ACTIVE_CONFIG / name)
                           for name in sorted(config_names)],
        "private_key_lstat": private_lstat,
        "directory_bindings": directory_bindings,
        "gen2_failure_entry": _regular_entry(GEN2_FAILURE_PATH),
        "plan_entry": _regular_entry(PLAN_PATH),
        "plan_review_entry": _regular_entry(PLAN_REVIEW),
        "implementation_review_entry": _regular_entry(IMPLEMENTATION_REVIEW),
        "downstream_absence": absence,
        "downstream_absence_sha256": base.sha_bytes(base.canonical_bytes(absence)),
    }


def verify_post_m3_review(
    supplied_sha256: str, *, allow_m4_recovery: bool = False,
) -> dict[str, Any]:
    subject = _post_m3_state_binding(allow_m4_recovery=allow_m4_recovery)
    config_by_name = {Path(row["path"]).name: row for row in subject["config_entries"]}
    expected = {
        "PLAN": FROZEN_PLAN_SHA256,
        "PLAN_REVIEW": FROZEN_PLAN_REVIEW_SHA256,
        "IMPLEMENTATION_REVIEW": base.sha_file(IMPLEMENTATION_REVIEW),
        "PROTOCOL_CONFIG": config_by_name["protocol.json"]["sha256"],
        "CPU_NO_MODEL_TRACE": config_by_name[
            "cpu_no_model_public_entry_trace.json"]["sha256"],
        "AUTHORIZATION_COMMITMENT": config_by_name[
            "authorization_commitment.json"]["sha256"],
        "PUBLIC_KEY": config_by_name["ed25519_public.pem"]["sha256"],
        "PRIVATE_KEY_LSTAT": base.sha_bytes(
            base.canonical_bytes(subject["private_key_lstat"])),
        "CONFIG_DIRECTORY": base.sha_bytes(base.canonical_bytes(
            subject["directory_bindings"]["config"])),
        "PROVENANCE_DIRECTORY": base.sha_bytes(base.canonical_bytes(
            subject["directory_bindings"]["provenance"])),
        "M4_DATA_DIRECTORY": base.sha_bytes(base.canonical_bytes(
            subject["directory_bindings"]["m4_data"])),
        "STATE_DIRECTORY": base.sha_bytes(base.canonical_bytes(
            subject["directory_bindings"]["state"])),
        "NONCE_DIRECTORY": base.sha_bytes(base.canonical_bytes(
            subject["directory_bindings"]["nonce"])),
        "GEN2_FAILURE": subject["gen2_failure_entry"]["sha256"],
        "DOWNSTREAM_ABSENCE": subject["downstream_absence_sha256"],
    }
    review = _canonical_review(
        POST_M3_REVIEW, supplied_sha256, scope="post_m3", expected_digests=expected)
    return {"review": review, "subject": subject}


def _build_m4_impl(
    post_m3_review_sha256: str, *, allow_m4_recovery: bool = False,
) -> dict[str, Any]:
    base.verify_baseline_projection("M2")
    base.verify_protected_v1()
    base.verify_protected_v2()
    base.validate_source_exposure()
    _verify_live_cpu_no_model_trace()
    checkpoints = checkpoint_registry()
    if _path_present(M4_PRIMARY) or _path_present(M4_REBUILD):
        raise FileExistsError("M4 complete-tree roots must both be initially absent")
    initial_status = _git_status()
    anticipated = _anticipated_status()
    raw_directory_projection = _directory_entries(
        ROOT, _candidate_relatives(include_m4=True))
    directory_projection = _historical_manifest_directory_projection(
        raw_directory_projection, recovery=allow_m4_recovery)
    payloads: dict[str, bytes] = {}
    snapshot: list[dict[str, Any]] = []
    try:
        left_stage = _materialize_complete_m4(M4_PRIMARY, checkpoints, anticipated,
                                              directory_projection)
        right_stage = _materialize_complete_m4(M4_REBUILD, checkpoints, anticipated,
                                               directory_projection)
        payloads = _compare_complete_m4_trees(M4_PRIMARY, M4_REBUILD,
                                              left_stage, right_stage)
        snapshot = _tree_entries(M4_PRIMARY, _m4_input_relatives())
        _verify_live_m4_inputs(snapshot, initial_status, raw_directory_projection)
    finally:
        shutil.rmtree(M4_PRIMARY, ignore_errors=True)
        shutil.rmtree(M4_REBUILD, ignore_errors=True)
    if _path_present(M4_PRIMARY) or _path_present(M4_REBUILD):
        raise RuntimeError("M4 complete-tree cleanup failed")
    _verify_live_m4_inputs(snapshot, initial_status, raw_directory_projection)
    _verify_live_cpu_no_model_trace()
    # Reconstruct the complete external/downstream absence subject after both
    # long builds and their cleanup, immediately before the create-once install.
    verify_post_m3_review(
        post_m3_review_sha256, allow_m4_recovery=allow_m4_recovery)
    manifest_sha = base.sha_bytes(payloads[M4_NEW[5]])
    if any(_path_present(path) for path in _prescore_evidence_paths(manifest_sha)):
        raise FileExistsError("digest-derived prescore evidence appeared before M4 install")
    _install_transaction(M4_TRANSACTION, M4_NEW, payloads, "msae_v3_m4_recoverable_install_v2")
    # Shared M0-M2 data remain exactly at the immutable M2 projection; gen3 M4
    # products live in their disjoint ACTIVE_M4_DATA root.
    base.verify_baseline_projection("M2")
    validate_stage_a()
    return left_stage


def build_m4(post_m3_review_sha256: str) -> dict[str, Any]:
    """Build/install M4 while making sealed-content access impossible."""
    with quarantine_guard():
        recovery = _m4_recovery_present()
        review = verify_post_m3_review(
            post_m3_review_sha256, allow_m4_recovery=recovery)
        # Crash-left complete-tree roots are disposable, authenticated scratch
        # state.  Remove them only after validating their dedicated identities;
        # Stage/transaction outputs are retained for byte-checked resume.
        if recovery:
            for root in (M4_PRIMARY, M4_REBUILD):
                if _path_present(root):
                    shutil.rmtree(root)
            if _path_present(M4_PRIMARY) or _path_present(M4_REBUILD):
                raise RuntimeError("M4 recovery-tree cleanup failed")
        result = _build_m4_impl(
            post_m3_review_sha256, allow_m4_recovery=recovery)
        return {**result, "post_m3_review_sha256": review["review"]["sha256"]}


def _expected_live_candidate_paths() -> set[str]:
    return set(_candidate_relatives(include_m4=True))


def _verify_manifest_entry(entry: Mapping[str, Any]) -> dict[str, Any]:
    path = ROOT / str(entry["path"])
    expected = _regular_entry(path, root=ROOT)
    if dict(entry) != expected:
        raise ValueError(f"candidate entry drift: {path}")
    return {**expected, "result": "match"}


def _verify_manifest_directory(entry: Mapping[str, Any]) -> dict[str, Any]:
    path = ROOT / str(entry["path"])
    st = path.lstat()
    if (entry.get("type") != "directory" or not stat.S_ISDIR(st.st_mode)
            or stat.S_ISLNK(st.st_mode) or stat.S_IMODE(st.st_mode) != entry.get("mode")
            or st.st_uid != entry.get("uid") or st.st_nlink != entry.get("nlink")):
        raise ValueError(f"candidate directory drift: {path}")
    return {"path": entry["path"], "verification_action": "lstat_directory",
            "result": "match", "type": "directory", "mode": stat.S_IMODE(st.st_mode),
            "uid": st.st_uid, "nlink": st.st_nlink}


def _strict_review_verdict(review: str, manifest: Mapping[str, Any], manifest_sha: str) -> None:
    lines = review.splitlines()
    review_controls = [line for line in lines
                       if re.match(r"(?:VERDICT|REVIEW_SCOPE)\b", line.strip(),
                                   re.ASCII)]
    if review_controls != ["VERDICT: SHIP"]:
        raise ValueError(
            f"review has non-unique, malformed, indented, or non-SHIP controls: "
            f"{review_controls}")
    check_path, trace_path = _prescore_evidence_paths(manifest_sha)
    expected = {
        "PRESCORE_CANDIDATE_MANIFEST_SHA256": manifest_sha,
        "STAGE_A_SHA256": str(manifest["stage_a_sha256"]),
        "DEPENDENCY_CLOSURE_SHA256": str(manifest["dependency_closure_sha256"]),
        "PRESCORE_CHECK_SHA256": base.sha_file(check_path),
        "PRESCORE_TRACE_SHA256": base.sha_file(trace_path),
        "SEALED_PAYLOAD_CONTENT_READS": "0",
    }
    controls: dict[str, str] = {}
    for line in lines:
        stripped = line.strip()
        control_like = re.match(
            r"(?:[A-Z][A-Z0-9_]*_SHA256|SEALED_PAYLOAD_CONTENT_READS)\b",
            stripped, re.ASCII)
        if control_like is None:
            continue
        if line != stripped:
            raise ValueError("review has indented/padded digest controls")
        match = re.fullmatch(
            r"([A-Z][A-Z0-9_]*_SHA256|SEALED_PAYLOAD_CONTENT_READS): "
            r"([0-9a-f]{64}|[0-9]+)", line, re.ASCII)
        if match is None or match.group(1) in controls:
            raise ValueError("review has malformed/duplicate digest controls")
        controls[match.group(1)] = match.group(2)
    if controls != expected:
        raise ValueError(f"review digest control set mismatch: {controls!r}")


def _review_bytes() -> bytes:
    raw = _regular_bytes(PRESCORE_REVIEW, mode=0o644)
    text = raw.decode("utf-8", errors="strict")
    if "\r" in text or not text or text != text.rstrip() + "\n":
        raise ValueError("prescore review is not canonical newline-terminated UTF-8")
    return raw


def _prescore_evidence_paths(manifest_sha256: str) -> tuple[Path, Path]:
    base.validate_sha256(manifest_sha256, "candidate-manifest SHA-256")
    prefix = Path(
        f"/tmp/msae_independent_measurement_v3_post_m2_gen3_{manifest_sha256}")
    return Path(f"{prefix}.prescore.check.json"), Path(f"{prefix}.prescore.trace.log")


def _exact_directory_entries(
    path: Path, expected: set[str], *, mode: int | None = None,
) -> None:
    st = path.lstat()
    if (not stat.S_ISDIR(st.st_mode) or stat.S_ISLNK(st.st_mode)
            or st.st_uid != os.getuid()
            or (mode is not None and stat.S_IMODE(st.st_mode) != mode)):
        raise ValueError(f"invalid projected directory: {path}")
    observed = set()
    for item in os.scandir(path):
        item_st = item.stat(follow_symlinks=False)
        if stat.S_ISLNK(item_st.st_mode):
            raise ValueError(f"symlink forbidden in projected directory: {item.path}")
        observed.add(item.name)
    if observed != expected:
        raise ValueError(f"directory projection drift at {path}: {sorted(observed ^ expected)}")


def _protected_baseline_results() -> dict[str, Any]:
    baseline = base.verify_baseline_projection("M2")
    protected_v1 = base.verify_protected_v1()
    protected_v2 = base.verify_protected_v2()
    exposure = base.validate_source_exposure()
    value = {
        "baseline_projection": baseline,
        "protected_v1_content_rehash": protected_v1,
        "protected_v2_content_rehash": protected_v2,
        "source_exposure_sha256": base.sha_file(V3_DATA / "source_exposure.json"),
        "source_exposure_disposition": exposure["disposition"],
        "result": "match",
    }
    return {**value, "result_sha256": base.sha_bytes(base.canonical_bytes(value))}


def _quarantine_manifest_results(manifest: Mapping[str, Any]) -> list[dict[str, Any]]:
    current = _quarantine_metadata_rows()
    if manifest.get("quarantined_entries") != current:
        raise ValueError("candidate quarantined metadata projection drift")
    return [{**row, "result": "match"} for row in current]


def _prescore_check_payload(*, phase: str, manifest: Mapping[str, Any],
                            manifest_sha256: str,
                            candidate_results: Sequence[Mapping[str, Any]],
                            directory_results: Sequence[Mapping[str, Any]],
                            quarantine_results: Sequence[Mapping[str, Any]],
                            protected_results: Mapping[str, Any],
                            closure_sha256: str, stage_a_sha256: str) -> dict[str, Any]:
    status_path = ACTIVE_PROV / "status.json"
    status_raw = _regular_bytes(status_path, mode=0o644)
    status = base.strict_json_loads(status_raw.decode("utf-8"))
    if status_raw != base.canonical_bytes(status):
        raise ValueError("M4 status is not canonical")
    return {
        "schema_version": "msae_v3_prescore_check_v3", "protocol_id": PROTOCOL,
        "phase": phase, "checker_code_sha256": base.sha_file(RUNTIME),
        "manifest_sha256": manifest_sha256,
        "candidate_tree_sha256": manifest["candidate_tree_sha256"],
        "dependency_closure_sha256": closure_sha256,
        "stage_a_sha256": stage_a_sha256,
        "m4_status_sha256": base.sha_bytes(status_raw),
        "candidate_file_results": list(candidate_results),
        "candidate_directory_results": list(directory_results),
        "quarantined_metadata_results": list(quarantine_results),
        "protected_baseline_results": dict(protected_results),
        "repository_status_projection": manifest["repository_status"],
        "repository_status_classification": manifest["repository_status_classification"],
        "repository_status_sha256": base.sha_bytes(
            base.canonical_bytes(manifest["repository_status"])),
        "candidate_file_count": len(candidate_results),
        "candidate_directory_count": len(directory_results),
        "quarantined_entry_count": len(quarantine_results),
        "sealed_payload_content_reads": 0, "eligible": True,
    }


def _verify_candidate_manifest_impl(phase: str = "prescore") -> dict[str, Any]:
    _validate_gen3_review_namespace(
        "prescore" if phase == "prescore" else "post_review")
    _validate_gen2_terminal_namespace(require_failure=True)
    manifest_path = ACTIVE_PROV / "prescore_candidate_manifest.json"
    manifest_raw = _regular_bytes(manifest_path, mode=0o644)
    manifest = base.strict_json_loads(manifest_raw.decode("utf-8"))
    if manifest_raw != base.canonical_bytes(manifest):
        raise ValueError("candidate manifest is not canonical")
    if (manifest.get("schema_version") != "msae_v3_prescore_candidate_manifest_v3"
            or manifest.get("protocol_id") != PROTOCOL
            or manifest.get("generation") != GENERATION
            or manifest.get("candidate_root_realpath") != str(ROOT.resolve(strict=True))):
        raise ValueError("candidate manifest schema/root drift")
    # Reconstruct the entire self-excluding manifest from current live bytes and
    # the frozen status projection.  This prevents any unvalidated top-level
    # field (including absence lists or classifications) from being rewritten.
    expected_paths = _expected_live_candidate_paths()
    live_directories = _directory_entries(ROOT, expected_paths)
    expected_manifest = candidate_manifest_payload(
        ROOT, manifest.get("repository_status", []), live_directories)
    if manifest != expected_manifest:
        raise ValueError("candidate manifest does not exactly reconstruct")
    protected_results = _protected_baseline_results()
    quarantine_results = _quarantine_manifest_results(manifest)
    entries = manifest.get("candidate_files")
    if (not isinstance(entries, list) or {row.get("path") for row in entries} != expected_paths
            or len(entries) != len(expected_paths) or manifest.get("candidate_file_paths") != sorted(expected_paths)):
        raise ValueError("candidate manifest is not an independently closed path projection")
    candidate_results = [_verify_manifest_entry(row) for row in entries]
    directories = manifest.get("candidate_directories")
    expected_directories = _candidate_directory_relatives(expected_paths)
    if (not isinstance(directories, list)
            or [row.get("path") for row in directories] != expected_directories
            or manifest.get("candidate_directory_tree_sha256") !=
               base.sha_bytes(base.canonical_bytes(directories))):
        raise ValueError("candidate directory projection is not closed")
    directory_results = [_verify_manifest_directory(row) for row in directories]
    if base.sha_bytes(base.canonical_bytes(entries)) != manifest.get("candidate_tree_sha256"):
        raise ValueError("candidate tree digest drift")
    old_data_names = {name for phase in ("M0", "M1", "M2")
                      for name in base.V3_DATA_PHASE_FILES[phase]}
    if set(path.name for path in V3_DATA.iterdir()) != old_data_names:
        raise ValueError("v3 data root contains an undeclared entry")
    _exact_directory_entries(ACTIVE_M4_DATA, set(base.V3_DATA_PHASE_FILES["M4"]))
    _exact_directory_entries(V3_CONFIG,
                             {"protocol.json", "authorization_commitment.json", "ed25519_public.pem"})
    _exact_directory_entries(ACTIVE_CONFIG,
                             {"protocol.json", "authorization_commitment.json", "ed25519_public.pem",
                              "cpu_no_model_public_entry_trace.json"})
    _exact_directory_entries(V3_PROV,
                             {"m1_completion_manifest.json", "m2_completion_manifest.json",
                              "m3_preflight_attempt_1.json"})
    _exact_directory_entries(ACTIVE_PROV,
                             {"stage_a.json", "status.json", "prescore_candidate_manifest.json"})
    closure = verify_dependency_closure()
    stage = validate_stage_a()
    if (base.sha_file(ACTIVE_M4_DATA / "dependency_closure.json") != manifest["dependency_closure_sha256"]
            or base.sha_file(ACTIVE_PROV / "stage_a.json") != manifest["stage_a_sha256"]):
        raise ValueError("candidate closure/Stage-A digest mismatch")
    current = _git_status()
    allowed = {f"? {M4_NEW[-1]}"}
    if phase in {"post_review", "post_signature", "prelaunch"}:
        allowed.add(f"? {PRESCORE_REVIEW.relative_to(ROOT)}")
    if phase in {"post_signature", "prelaunch"}:
        allowed.add(f"? {ACTIVE_RUN_REL}/authorization.json")
    projected = [line for line in current if line not in allowed]
    if projected != manifest["repository_status"]:
        raise ValueError("repository status projection drift")
    classifications = _classify_repository_status(
        manifest["repository_status"], expected_paths | {M4_NEW[-1]})
    if classifications != manifest["repository_status_classification"]:
        raise ValueError("repository status classification drift")
    for root in manifest["required_external_state"]["required_absent_build_roots"]:
        if _path_present(Path(root)):
            raise ValueError(f"temporary build root exists: {root}")
    commitment = _verify_existing_authorization_state()
    external = manifest["required_external_state"]
    if (external.get("private_key") != commitment["private_key_binding"]
            or external.get("nonce_directory") != base._directory_binding(ACTIVE_NONCE_DIR)
            or external.get("gpu_lock_directory") != base._directory_binding(base.GPU_LOCK_DIR)):
        raise ValueError("candidate external-state binding drift")
    if any(ACTIVE_NONCE_DIR.iterdir()):
        raise ValueError("nonce directory is not empty")
    socket_path = Path(external["required_absent_tmux_socket"])
    if socket_path.exists() or socket_path.is_symlink():
        raise ValueError("candidate tmux socket unexpectedly exists")
    if phase == "prescore":
        if _path_present(PRESCORE_REVIEW) or _path_present(ACTIVE_RUN_ROOT):
            raise ValueError("post-review output exists at prescore")
    elif phase == "post_review":
        if _path_present(ACTIVE_RUN_ROOT):
            raise ValueError("post-review projection mismatch")
        _strict_review_verdict(_review_bytes().decode("utf-8"), manifest,
                               base.sha_file(manifest_path))
        check_path, trace_path = _prescore_evidence_paths(base.sha_file(manifest_path))
        verify_prescore_trace(manifest_path, check_path, trace_path)
    elif phase in {"post_signature", "prelaunch"}:
        if not PRESCORE_REVIEW.is_file() or PRESCORE_REVIEW.is_symlink() or not ACTIVE_RUN_ROOT.is_dir():
            raise ValueError("post-signature projection mismatch")
        run_entries = []
        run_st = ACTIVE_RUN_ROOT.lstat()
        if stat.S_IMODE(run_st.st_mode) != 0o700 or stat.S_ISLNK(run_st.st_mode):
            raise ValueError("prelaunch run-root identity/mode drift")
        for path in ACTIVE_RUN_ROOT.rglob("*"):
            st = path.lstat()
            if stat.S_ISREG(st.st_mode) and not stat.S_ISLNK(st.st_mode):
                if stat.S_IMODE(st.st_mode) != 0o600 or st.st_uid != os.getuid() or st.st_nlink != 1:
                    raise ValueError(f"prelaunch run file identity/mode drift: {path}")
                run_entries.append(path.relative_to(ACTIVE_RUN_ROOT).as_posix())
            else:
                raise ValueError(f"unexpected prelaunch run-root object: {path}")
        if sorted(run_entries) != ["authorization.json"]:
            raise ValueError(f"unexpected prelaunch run outputs: {run_entries}")
        verify_authorization(ACTIVE_RUN_ROOT / "authorization.json", consume=False)
        check_path, trace_path = _prescore_evidence_paths(base.sha_file(manifest_path))
        verify_prescore_trace(manifest_path, check_path, trace_path)
    else:
        raise ValueError(f"unknown candidate phase: {phase}")
    return _prescore_check_payload(
        phase=phase, manifest=manifest, manifest_sha256=base.sha_bytes(manifest_raw),
        candidate_results=candidate_results, directory_results=directory_results,
        quarantine_results=quarantine_results, protected_results=protected_results,
        closure_sha256=base.sha_bytes(base.canonical_bytes(closure)),
        stage_a_sha256=base.sha_bytes(base.canonical_bytes(stage)))


def verify_candidate_manifest(phase: str = "prescore") -> dict[str, Any]:
    with quarantine_guard():
        return _verify_candidate_manifest_impl(phase)


def _prescore_traced_check_impl(manifest: Path, output: Path, trace: Path) -> None:
    if manifest.resolve(strict=True) != (ACTIVE_PROV / "prescore_candidate_manifest.json").resolve(strict=True):
        raise ValueError("unexpected candidate manifest")
    verify_candidate_manifest("prescore")
    expected_output, expected_trace = _prescore_evidence_paths(base.sha_file(manifest))
    if output != expected_output or trace != expected_trace:
        raise ValueError("prescore evidence paths are not manifest-derived")
    for path in (output, trace):
        if path.exists() or path.is_symlink():
            raise FileExistsError(f"prescore evidence path already exists: {path}")
    fds: list[int] = []
    try:
        for path in (output, trace):
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600)
            os.fchmod(fd, 0o600)
            os.set_inheritable(fd, True)
            fds.append(fd)
        check_fd, trace_fd = fds
        command = ["/usr/bin/strace", "-f", "-qq", "-yy", "-s", "4096",
                   "-e", "trace=open,openat,openat2,creat", "-o", f"/proc/self/fd/{trace_fd}",
                   str(ROOT / ".venv-atlas/bin/python"), "-S", "-B", "-I",
                   str(continuation.CONTROLLER_PATH.resolve()), "prescore-check",
                   "--output-fd", str(check_fd)]
        result = subprocess.run(command, pass_fds=(check_fd, trace_fd), close_fds=True,
                                env=FROZEN_BASE_PROCESS_ENVIRONMENT)
        if result.returncode != 0:
            raise RuntimeError(f"traced prescore check failed: {result.returncode}")
        for fd, path in zip(fds, (output, trace)):
            os.fsync(fd)
            fd_st, path_st = os.fstat(fd), path.lstat()
            if (fd_st.st_dev, fd_st.st_ino) != (path_st.st_dev, path_st.st_ino):
                raise ValueError("prescore output path/FD substitution")
    finally:
        for fd in fds:
            with contextlib.suppress(OSError):
                os.close(fd)


def prescore_traced_check(manifest: Path, output: Path, trace: Path) -> None:
    with quarantine_guard():
        _prescore_traced_check_impl(manifest, output, trace)


def _trace_open_candidates(line: str) -> set[str]:
    if re.search(r"\b(?:open|openat|openat2|creat)\(", line) is None:
        return set()
    candidates = {match for match in re.findall(r"<(/[^>]*)>", line)}
    quoted = re.findall(r'"(?:[^"\\]|\\.)*"', line)
    decoded = []
    for raw in quoted:
        try:
            value = ast.literal_eval(raw)
        except (SyntaxError, ValueError):
            continue
        if isinstance(value, str):
            decoded.append(value)
            if value.startswith("/"):
                candidates.add(value)
    directory = re.search(r"(?:AT_FDCWD|\d+)<(/[^>]*)>\s*,", line)
    if directory and decoded:
        candidates.add(str(Path(directory.group(1)) / decoded[0]))
    return {os.path.realpath(path.removesuffix(" (deleted)")) for path in candidates}


def verify_trace_no_forbidden(trace_text: str, forbidden_paths: Iterable[Path]) -> None:
    forbidden = {os.path.realpath(path) for path in forbidden_paths}
    for line in trace_text.splitlines():
        touched = _trace_open_candidates(line) & forbidden
        if touched:
            raise ValueError(f"trace observed forbidden content open: {sorted(touched)}")


def _verify_prescore_trace_impl(manifest: Path, check: Path, trace: Path) -> dict[str, Any]:
    if manifest.resolve(strict=True) != (ACTIVE_PROV / "prescore_candidate_manifest.json").resolve(strict=True):
        raise ValueError("unexpected prescore manifest path")
    manifest_raw = _regular_bytes(manifest, mode=0o644)
    manifest_payload = base.strict_json_loads(manifest_raw.decode("utf-8"))
    if manifest_raw != base.canonical_bytes(manifest_payload):
        raise ValueError("prescore manifest is not canonical")
    expected_manifest = base.sha_bytes(manifest_raw)
    expected_check, expected_trace = _prescore_evidence_paths(expected_manifest)
    if check != expected_check or trace != expected_trace:
        raise ValueError("prescore evidence path mismatch")
    check_raw = _regular_bytes(check, mode=0o600)
    trace_raw = _regular_bytes(trace, mode=0o600)
    payload = base.strict_json_loads(check_raw.decode("utf-8"))
    if check_raw != base.canonical_bytes(payload):
        raise ValueError("prescore check output is not canonical")
    closure_raw = _regular_bytes(ACTIVE_M4_DATA / "dependency_closure.json", mode=0o644)
    stage_raw = _regular_bytes(ACTIVE_PROV / "stage_a.json", mode=0o644)
    closure_payload_value = base.strict_json_loads(closure_raw.decode("utf-8"))
    stage_payload_value = base.strict_json_loads(stage_raw.decode("utf-8"))
    if (closure_raw != base.canonical_bytes(closure_payload_value)
            or stage_raw != base.canonical_bytes(stage_payload_value)):
        raise ValueError("prescore closure/Stage-A evidence is noncanonical")
    expected_paths = _expected_live_candidate_paths()
    expected_manifest_payload = candidate_manifest_payload(
        ROOT, manifest_payload.get("repository_status", []),
        _directory_entries(ROOT, expected_paths))
    if manifest_payload != expected_manifest_payload:
        raise ValueError("traced candidate manifest does not exactly reconstruct")
    entries = manifest_payload.get("candidate_files")
    directories = manifest_payload.get("candidate_directories")
    if not isinstance(entries, list) or not isinstance(directories, list):
        raise ValueError("traced candidate manifest entry arrays malformed")
    candidate_results = [_verify_manifest_entry(row) for row in entries]
    directory_results = [_verify_manifest_directory(row) for row in directories]
    quarantine_results = _quarantine_manifest_results(manifest_payload)
    protected_results = _protected_baseline_results()
    expected_payload = _prescore_check_payload(
        phase="prescore", manifest=manifest_payload, manifest_sha256=expected_manifest,
        candidate_results=candidate_results, directory_results=directory_results,
        quarantine_results=quarantine_results, protected_results=protected_results,
        closure_sha256=base.sha_bytes(closure_raw), stage_a_sha256=base.sha_bytes(stage_raw))
    if payload != expected_payload:
        raise ValueError("prescore check output mismatch")
    if len(trace_raw) < 1024 or not trace_raw.endswith(b"\n"):
        raise ValueError("prescore trace is empty, truncated, or implausibly small")
    trace_text = trace_raw.decode("utf-8", errors="strict")
    successful = [line for line in trace_text.splitlines()
                  if re.search(r"\b(?:open|openat|openat2|creat)\(", line)
                  and re.search(r"\)\s+=\s+[0-9]+(?:<[^>]+>)?", line)]
    if len(successful) < 10:
        raise ValueError("prescore trace lacks expected successful open activity")
    opened = set().union(*(_trace_open_candidates(line) for line in successful))
    expected_opened = {str(path.resolve(strict=True)) for path in
                       (continuation.CONTROLLER_PATH, RUNTIME,
                        ACTIVE_PROV / "prescore_candidate_manifest.json",
                        ACTIVE_PROV / "stage_a.json", ACTIVE_M4_DATA / "dependency_closure.json")}
    if not expected_opened.issubset(opened):
        raise ValueError(f"prescore trace lacks required opens: {sorted(expected_opened - opened)}")
    verify_trace_no_forbidden(trace_text,
                              (ROOT / rel for rel in base.QUARANTINED))
    result = {"manifest_sha256": expected_manifest, "check_sha256": base.sha_file(check),
              "trace_sha256": base.sha_file(trace), "sealed_payload_content_reads": 0,
              "eligible": True}
    print(json.dumps(result, sort_keys=True, separators=(",", ":")))
    return result


def verify_prescore_trace(manifest: Path, check: Path, trace: Path) -> dict[str, Any]:
    with quarantine_guard():
        return _verify_prescore_trace_impl(manifest, check, trace)


def _authorization_unsigned(envelope_path: Path) -> tuple[dict[str, Any], bytes, bytes, bytes]:
    raw = _regular_bytes(envelope_path, mode=0o600)
    envelope = base.strict_json_loads(raw.decode("utf-8"))
    if raw != base.canonical_bytes(envelope):
        raise ValueError("authorization envelope is not canonical JSON")
    if set(envelope).issuperset({"signature_b64"}) is False:
        raise ValueError("authorization signature missing")
    signature = base64.b64decode(envelope.pop("signature_b64"), validate=True)
    signed = base.canonical_bytes(envelope)
    return envelope, signed, signature, raw


def verify_authorization(envelope_path: Path, *, consume: bool,
                         run_root: Path | None = None) -> dict[str, Any]:
    from cryptography.hazmat.primitives import serialization
    envelope, signed, signature, envelope_file_bytes = _authorization_unsigned(envelope_path)
    commitment_path = ACTIVE_CONFIG / "authorization_commitment.json"
    commitment = _verify_existing_authorization_state()
    manifest_path = ACTIVE_PROV / "prescore_candidate_manifest.json"
    expected = {"prescore_candidate_manifest_sha256": base.sha_file(manifest_path),
                "operator_instruction_sha256": base.sha_bytes(OPERATOR_INSTRUCTION.encode("utf-8")),
                "operator_instruction": OPERATOR_INSTRUCTION,
                "review_sha256": base.sha_bytes(_review_bytes()),
                "review_verdict": "SHIP", "scope": "calibration_replay_only"}
    if any(envelope.get(key) != value for key, value in expected.items()):
        raise ValueError("authorization does not bind exact review/manifest/operator/scope")
    public_bytes = _regular_bytes(ACTIVE_CONFIG / "ed25519_public.pem", mode=0o644)
    if base.sha_bytes(public_bytes) != commitment.get("public_key_sha256"):
        raise ValueError("authorization public-key drift")
    serialization.load_pem_public_key(public_bytes).verify(signature, signed)
    bindings = {
        "schema_version": commitment["envelope_schema"], "protocol_id": PROTOCOL,
        "commitment_sha256": base.sha_file(commitment_path),
        "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
        "protocol_config_sha256": base.sha_file(ACTIVE_CONFIG / "protocol.json"),
        "dependency_closure_sha256": base.sha_file(ACTIVE_M4_DATA / "dependency_closure.json"),
    }
    if any(envelope.get(key) != value for key, value in bindings.items()):
        raise ValueError("authorization cryptographic lineage mismatch")
    now = int(time.time())
    issued, expires = envelope.get("issued_unix"), envelope.get("expires_unix")
    if (type(issued) is not int or type(expires) is not int or not issued <= now <= expires
            or expires <= issued or expires - issued > commitment["maximum_lifetime_seconds"]):
        raise ValueError("authorization validity interval mismatch")
    nonce = envelope.get("nonce")
    if not isinstance(nonce, str) or re.fullmatch(r"[0-9a-f]{64}", nonce, re.ASCII) is None:
        raise ValueError("authorization nonce malformed")
    envelope_digest = base.sha_bytes(envelope_file_bytes)
    record_name = f"{envelope_digest}.consumed"
    directory_fd = os.open(ACTIVE_NONCE_DIR,
                           os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
    record_stat: os.stat_result | None = None
    record_path = ACTIVE_NONCE_DIR / record_name
    try:
        directory_before = os.fstat(directory_fd)
        expected_directory = commitment["nonce_directory"]
        path_before = ACTIVE_NONCE_DIR.lstat()
        fields = ("st_dev", "st_ino", "st_uid", "st_nlink")
        if (not stat.S_ISDIR(directory_before.st_mode)
                or stat.S_ISLNK(path_before.st_mode)
                or stat.S_IMODE(directory_before.st_mode) != expected_directory["mode"]
                or any(getattr(directory_before, field) != expected_directory[key]
                       for field, key in zip(fields, ("device", "inode", "uid", "nlink")))
                or (directory_before.st_dev, directory_before.st_ino) !=
                   (path_before.st_dev, path_before.st_ino)):
            raise ValueError("held nonce-directory FD does not match commitment/path")
        if consume:
            fd = os.open(record_name,
                         os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC,
                         0o600, dir_fd=directory_fd)
            try:
                os.fchmod(fd, 0o600)
                payload = base.canonical_bytes({"schema_version": "msae_v3_nonce_consumed_v2",
                                                "authorization_file_sha256": envelope_digest,
                                                "stage_a_sha256": envelope["stage_a_sha256"]})
                try:
                    _write_all(fd, payload)
                    os.fsync(fd)
                    os.lseek(fd, 0, os.SEEK_SET)
                    if os.read(fd, len(payload) + 1) != payload:
                        raise OSError("nonce consumed record did not reread exactly")
                except BaseException:
                    # A partial record must not irreversibly consume the nonce.
                    with contextlib.suppress(OSError):
                        os.unlink(record_name, dir_fd=directory_fd)
                        os.fsync(directory_fd)
                    raise
                record_stat = os.fstat(fd)
            finally:
                os.close(fd)
            os.fsync(directory_fd)
        else:
            try:
                probe = os.open(record_name, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC,
                                dir_fd=directory_fd)
            except FileNotFoundError:
                probe = -1
            if probe >= 0:
                os.close(probe)
                raise ValueError("authorization nonce has already been consumed")
        directory_after = os.fstat(directory_fd)
        path_after = ACTIVE_NONCE_DIR.lstat()
        if ((directory_before.st_dev, directory_before.st_ino, directory_before.st_mode,
             directory_before.st_uid, directory_before.st_nlink) !=
            (directory_after.st_dev, directory_after.st_ino, directory_after.st_mode,
             directory_after.st_uid, directory_after.st_nlink)
                or (directory_after.st_dev, directory_after.st_ino) !=
                   (path_after.st_dev, path_after.st_ino) or stat.S_ISLNK(path_after.st_mode)):
            raise ValueError("nonce directory changed during authorization verification")
    finally:
        os.close(directory_fd)
    if consume:
        assert record_stat is not None
        path_st = record_path.lstat()
        if ((record_stat.st_dev, record_stat.st_ino) != (path_st.st_dev, path_st.st_ino)
                or not stat.S_ISREG(record_stat.st_mode) or stat.S_ISLNK(path_st.st_mode)
                or stat.S_IMODE(record_stat.st_mode) != 0o600 or record_stat.st_uid != os.getuid()
                or record_stat.st_nlink != 1):
            raise ValueError("nonce record identity/mode/ownership drift")
        if run_root is not None:
            base.install_json(run_root / "nonce_consumed.json", {
                "schema_version": "msae_v3_nonce_attestation_v2", "record_path": str(record_path),
                "record_device": record_stat.st_dev, "record_inode": record_stat.st_ino,
                "record_mode": stat.S_IMODE(record_stat.st_mode),
                "record_sha256": base.sha_file(record_path),
                "authorization_file_sha256": envelope_digest})
    return {**envelope, "signature_b64": base64.b64encode(signature).decode("ascii"),
            "envelope_sha256": envelope_digest}


def _sign_authorization_impl() -> dict[str, Any]:
    from cryptography.hazmat.primitives import serialization
    verify_candidate_manifest("post_review")
    commitment = _verify_existing_authorization_state(verify_private_content=True)
    if _path_present(ACTIVE_RUN_ROOT) or any(ACTIVE_NONCE_DIR.iterdir()):
        raise ValueError("run root/nonce state must be absent before signing")
    private = serialization.load_pem_private_key(
        _regular_bytes(ACTIVE_PRIVATE_KEY, mode=0o600), password=None)
    issued = int(time.time())
    envelope = {"schema_version": commitment["envelope_schema"], "protocol_id": PROTOCOL,
                "scope": "calibration_replay_only",
                "commitment_sha256": base.sha_file(ACTIVE_CONFIG / "authorization_commitment.json"),
                "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
                "protocol_config_sha256": base.sha_file(ACTIVE_CONFIG / "protocol.json"),
                "dependency_closure_sha256": base.sha_file(ACTIVE_M4_DATA / "dependency_closure.json"),
                "prescore_candidate_manifest_sha256": base.sha_file(ACTIVE_PROV / "prescore_candidate_manifest.json"),
                "operator_instruction": OPERATOR_INSTRUCTION,
                "operator_instruction_sha256": commitment["operator_instruction_sha256"],
                "review_sha256": base.sha_bytes(_review_bytes()), "review_verdict": "SHIP",
                "nonce": os.urandom(32).hex(), "issued_unix": issued, "expires_unix": issued + 86400}
    signature = private.sign(base.canonical_bytes(envelope))
    output = {**envelope, "signature_b64": base64.b64encode(signature).decode("ascii")}
    ACTIVE_RUN_ROOT.mkdir(mode=0o700, parents=False)
    os.chmod(ACTIVE_RUN_ROOT, 0o700)
    base._fsync_directory(ACTIVE_RUN_ROOT.parent)
    base.write_once(ACTIVE_RUN_ROOT / "authorization.json", base.canonical_bytes(output), 0o600)
    base._fsync_directory(ACTIVE_RUN_ROOT)
    verify_candidate_manifest("post_signature")
    return output


def sign_authorization() -> dict[str, Any]:
    with quarantine_guard():
        return _sign_authorization_impl()


def _send_json(sock: socket.socket, value: Any) -> None:
    raw = base.canonical_bytes(value)
    sock.sendall(struct.pack(">Q", len(raw)) + raw)


def _recv_json(sock: socket.socket) -> Any:
    header = b""
    while len(header) < 8:
        chunk = sock.recv(8 - len(header))
        if not chunk:
            raise EOFError("handoff closed before header")
        header += chunk
    length = struct.unpack(">Q", header)[0]
    if length > (1 << 20):
        raise ValueError("oversized handoff frame")
    raw = b""
    while len(raw) < length:
        chunk = sock.recv(length - len(raw))
        if not chunk:
            raise EOFError("handoff closed before body")
        raw += chunk
    return base.strict_json_loads(raw.decode("utf-8"))


def validate_runner_readiness(readiness: Mapping[str, Any], worker: Mapping[str, Any],
                              gpu_uuid: str, authorization: Mapping[str, Any]) -> dict[str, Any]:
    attestation_raw = _regular_bytes(ACTIVE_RUN_ROOT / "nonce_consumed.json", mode=0o644)
    attestation = base.strict_json_loads(attestation_raw.decode("utf-8"))
    if attestation_raw != base.canonical_bytes(attestation):
        raise ValueError("nonce attestation is noncanonical")
    expected = {
        "schema_version": "msae_v3_runner_ready_v1", "protocol_id": PROTOCOL,
        "worker_pid": worker["worker_pid"], "worker_pgid": worker["worker_pgid"],
        "broker_pid": worker["broker_pid"], "gpu_uuid": gpu_uuid,
        "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
        "protocol_config_sha256": base.sha_file(ACTIVE_CONFIG / "protocol.json"),
        "dependency_closure_sha256": base.sha_file(ACTIVE_M4_DATA / "dependency_closure.json"),
        "authorization_envelope_sha256": authorization["envelope_sha256"],
        "nonce_attestation_sha256": base.sha_bytes(attestation_raw),
        "pre_model": True,
    }
    if dict(readiness) != expected:
        raise ValueError("runner readiness exact lineage mismatch")
    expected_record_path = ACTIVE_NONCE_DIR / f"{authorization['envelope_sha256']}.consumed"
    record_path = Path(str(attestation.get("record_path")))
    if record_path != expected_record_path:
        raise ValueError("nonce attestation does not name the exact derived consumed record")
    record_raw = _regular_bytes(record_path, mode=0o600)
    record_st = record_path.lstat()
    expected_record_raw = base.canonical_bytes({
        "schema_version": "msae_v3_nonce_consumed_v2",
        "authorization_file_sha256": authorization["envelope_sha256"],
        "stage_a_sha256": expected["stage_a_sha256"],
    })
    if (attestation.get("schema_version") != "msae_v3_nonce_attestation_v2"
            or attestation.get("authorization_file_sha256") != authorization["envelope_sha256"]
            or attestation.get("record_device") != record_st.st_dev
            or attestation.get("record_inode") != record_st.st_ino
            or attestation.get("record_mode") != 0o600
            or record_raw != expected_record_raw
            or attestation.get("record_sha256") != base.sha_bytes(expected_record_raw)):
        raise ValueError("nonce attestation/record identity mismatch")
    return attestation


def _receive_fd(sock: socket.socket) -> int:
    _, ancillary, _, _ = sock.recvmsg(1, socket.CMSG_LEN(array.array("i", [0]).itemsize))
    fds: list[int] = []
    for level, kind, raw in ancillary:
        if level == socket.SOL_SOCKET and kind == socket.SCM_RIGHTS:
            values = array.array("i")
            values.frombytes(raw[:len(raw) - len(raw) % values.itemsize])
            fds.extend(values)
    if len(fds) != 1:
        for fd in fds:
            os.close(fd)
        raise ValueError("expected exactly one GPU lease FD")
    return fds[0]


def _validate_gpu_lock_fd(lease_fd: int, gpu_uuid: str) -> dict[str, int]:
    commitment = base.read_json(ACTIVE_CONFIG / "authorization_commitment.json")
    directory_fd = os.open(base.GPU_LOCK_DIR,
                           os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
    name = f"{base.sha_bytes(gpu_uuid.encode('ascii'))}.lock"
    try:
        directory_st = os.fstat(directory_fd)
        directory_path_st = base.GPU_LOCK_DIR.lstat()
        expected_dir = commitment["gpu_lock_directory"]
        if ((directory_st.st_dev, directory_st.st_ino) !=
                (directory_path_st.st_dev, directory_path_st.st_ino)
                or (directory_st.st_dev, directory_st.st_ino, directory_st.st_uid,
                    stat.S_IMODE(directory_st.st_mode), directory_st.st_nlink) !=
                   (expected_dir["device"], expected_dir["inode"], expected_dir["uid"],
                    expected_dir["mode"], expected_dir["nlink"])):
            raise ValueError("inherited GPU lock directory binding drift")
        path_fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=directory_fd)
        try:
            path_st = os.fstat(path_fd)
            lease_st = os.fstat(lease_fd)
            os.lseek(path_fd, 0, os.SEEK_SET)
            payload = os.read(path_fd, 4096)
        finally:
            os.close(path_fd)
        live_path_st = (base.GPU_LOCK_DIR / name).lstat()
        directory_after = os.fstat(directory_fd)
        directory_path_after = base.GPU_LOCK_DIR.lstat()
        expected_payload = base.canonical_bytes({"schema_version": "msae_gpu_uuid_lock_v1",
                                                 "gpu_uuid": gpu_uuid})
        if ((lease_st.st_dev, lease_st.st_ino) != (path_st.st_dev, path_st.st_ino)
                or (path_st.st_dev, path_st.st_ino) != (live_path_st.st_dev, live_path_st.st_ino)
                or not stat.S_ISREG(lease_st.st_mode) or stat.S_ISLNK(live_path_st.st_mode)
                or stat.S_IMODE(lease_st.st_mode) != 0o600 or lease_st.st_uid != os.getuid()
                or lease_st.st_nlink != 1 or payload != expected_payload):
            raise ValueError("inherited GPU lock FD/path/type/mode/owner/content drift")
        if ((directory_st.st_dev, directory_st.st_ino, directory_st.st_mode,
             directory_st.st_uid, directory_st.st_nlink) !=
            (directory_after.st_dev, directory_after.st_ino, directory_after.st_mode,
             directory_after.st_uid, directory_after.st_nlink)
                or (directory_after.st_dev, directory_after.st_ino) !=
                   (directory_path_after.st_dev, directory_path_after.st_ino)):
            raise ValueError("inherited GPU lock directory changed during validation")
        return {"device": lease_st.st_dev, "inode": lease_st.st_ino}
    finally:
        os.close(directory_fd)


def _technical_failure(reason: str, broker_pid: int, worker_pid: int | None) -> None:
    payload = {"schema_version": "msae_v3_technical_failure_v3", "protocol_id": PROTOCOL,
               "status": "not_run", "reason": reason, "broker_pid": broker_pid,
               "worker_pid": worker_pid, "stage_b_written": False}
    commit_terminal_failure(ACTIVE_RUN_ROOT, payload)


def enforce_live_gpu_lease(lease_fd: int, gpu_uuid: str, broker_pid: int,
                           worker_pid: int) -> None:
    """Turn any persistent lock path/directory drift into a terminal not-run."""
    try:
        _validate_gpu_lock_fd(lease_fd, gpu_uuid)
    except BaseException as error:
        with contextlib.suppress(Exception):
            _terminate_group(worker_pid)
        _technical_failure(f"gpu_lease_loss:{type(error).__name__}:{error}",
                           broker_pid, worker_pid)
        raise RuntimeError("GPU UUID lease identity was lost") from error


def _claim_terminal(run_root: Path, kind: str) -> bool:
    claim = run_root / "terminal.claim"
    try:
        base.write_once(claim, base.canonical_bytes({"schema_version": "msae_v3_terminal_claim_v1",
                                                     "kind": kind}), 0o600)
        base._fsync_directory(run_root)
        return True
    except FileExistsError:
        return False


def commit_terminal_failure(run_root: Path, payload: Mapping[str, Any]) -> bool:
    if (run_root / "terminal_success").exists():
        return False
    claim = run_root / "terminal.claim"
    if not claim.exists():
        if not _claim_terminal(run_root, "technical_failure"):
            raise RuntimeError("terminal claim race")
    else:
        claim_value = base.read_json(claim)
        if claim_value.get("kind") not in {"technical_failure", "valid_calibration_completion"}:
            raise ValueError("unknown terminal claim")
        if (run_root / "terminal_failure").is_dir():
            return True
        # The broker only calls this after the worker is dead.  An incomplete
        # success staging tree must never strand the run without a terminal
        # outcome after a write/fsync failure or kill.
    shutil.rmtree(run_root / ".terminal_success_staging", ignore_errors=True)
    staging = run_root / ".terminal_failure_staging"
    final = run_root / "terminal_failure"
    if staging.exists():
        shutil.rmtree(staging)
    staging.mkdir(mode=0o700)
    os.chmod(staging, 0o700)
    base.write_once(staging / "technical_failure.json", base.canonical_bytes(dict(payload)), 0o600)
    status = {"schema_version": "msae_v3_runtime_status_v2",
              "status": "technical_failure_not_run", "stage_b_ready": False,
              "technical_failure_sha256": base.sha_file(staging / "technical_failure.json")}
    base.write_once(staging / "status.json", base.canonical_bytes(status), 0o600)
    base._fsync_directory(staging)
    os.rename(staging, final)
    base._fsync_directory(run_root)
    return True


def commit_terminal_success(run_root: Path, files: Mapping[str, bytes]) -> Path:
    expected = {"stage_b.json", "status.json", "runtime_native_pre_import.json",
                "runtime_native_post_torch.json", "runtime_native_post_model.json",
                "runtime_native_final.json"}
    if set(files) != expected:
        raise ValueError("terminal-success file set mismatch")
    staging = run_root / ".terminal_success_staging"
    final = run_root / "terminal_success"
    if final.exists() or (run_root / "terminal_failure").exists():
        raise FileExistsError("terminal outcome already exists")
    if staging.exists():
        shutil.rmtree(staging)
    staging.mkdir(mode=0o700)
    os.chmod(staging, 0o700)
    try:
        for name in sorted(expected):
            base.write_once(staging / name, files[name], 0o600)
        base._fsync_directory(staging)
        if not _claim_terminal(run_root, "valid_calibration_completion"):
            claim = base.read_json(run_root / "terminal.claim")
            if claim.get("kind") != "valid_calibration_completion":
                raise FileExistsError("terminal failure already claimed")
        os.rename(staging, final)
        try:
            base._fsync_directory(run_root)
        except BaseException:
            os.rename(final, staging)
            with contextlib.suppress(Exception):
                base._fsync_directory(run_root)
            raise
    except BaseException:
        shutil.rmtree(staging, ignore_errors=True)
        raise
    return final


def _group_live_pids(pgid: int) -> list[int]:
    result = []
    for path in Path("/proc").iterdir():
        if not path.name.isdecimal():
            continue
        try:
            raw = (path / "stat").read_text(encoding="ascii")
            right = raw.rfind(")")
            fields = raw[right + 2:].split()
            # After comm: state=field 3, ppid=4, pgrp=5.
            if len(fields) > 2 and int(fields[2]) == pgid and fields[0] != "Z":
                result.append(int(path.name))
        except (FileNotFoundError, ProcessLookupError, PermissionError, ValueError):
            continue
    return sorted(result)


def _terminate_group(pgid: int, *, grace: float = 5.0) -> None:
    if pgid <= 1:
        return
    with contextlib.suppress(ProcessLookupError):
        os.killpg(pgid, signal.SIGTERM)
    deadline = time.monotonic() + grace
    while time.monotonic() < deadline:
        if not _group_live_pids(pgid):
            return
        time.sleep(0.05)
    with contextlib.suppress(ProcessLookupError):
        os.killpg(pgid, signal.SIGKILL)
    deadline = time.monotonic() + 2
    while time.monotonic() < deadline:
        if not _group_live_pids(pgid):
            return
        time.sleep(0.05)
    raise RuntimeError(f"worker process group survived KILL: {pgid}")


def install_parent_death_watchdog(expected_parent: int) -> None:
    """Arm Linux parent-death SIGKILL and close the fork/arm race."""
    import ctypes
    libc = ctypes.CDLL(None, use_errno=True)
    if libc.prctl(1, signal.SIGKILL, 0, 0, 0) != 0 or os.getppid() != expected_parent:
        raise RuntimeError("worker parent-death watchdog setup failed")


def confirm_pre_model_gate(final_ack_fd: int, confirmed_fd: int) -> None:
    """Cross the durable handoff gate; callers may import models only afterward."""
    try:
        if os.read(final_ack_fd, 1) != b"F":
            raise RuntimeError("durable launcher handoff acknowledgement missing")
    finally:
        os.close(final_ack_fd)
    try:
        os.write(confirmed_fd, b"A")
    finally:
        os.close(confirmed_fd)


def worker_environment(gpu_uuid: str, lease_fd: int, readiness_fd: int,
                       final_ack_fd: int, confirmed_fd: int) -> dict[str, str]:
    """Return the exact closed worker environment; inherited keys never survive."""
    if re.fullmatch(r"GPU-[0-9A-Fa-f-]{16,}", gpu_uuid, re.ASCII) is None:
        raise ValueError("malformed worker GPU UUID")
    if any(fd < 0 for fd in (lease_fd, readiness_fd, final_ack_fd, confirmed_fd)):
        raise ValueError("worker descriptor number is negative")
    return {**FROZEN_BASE_PROCESS_ENVIRONMENT, **FROZEN_WORKER_ENVIRONMENT,
            "CUDA_VISIBLE_DEVICES": gpu_uuid, "MSAE_LEASE_FD": str(lease_fd),
            "MSAE_GPU_UUID": gpu_uuid, "MSAE_READINESS_FD": str(readiness_fd),
            "MSAE_FINAL_ACK_FD": str(final_ack_fd),
            "MSAE_CONFIRMED_FD": str(confirmed_fd)}


def _validate_launcher_intent(socket_path: str, gpu_uuid: str, gpu_index: int,
                              launch_capability: str, intent_sha256: str,
                              lease_fd: int | None = None) -> dict[str, Any]:
    """Authenticate launcher-only internal broker/supervisor entrypoints."""
    if (re.fullmatch(r"[0-9a-f]{64}", launch_capability, re.ASCII) is None
            or re.fullmatch(r"[0-9a-f]{64}", intent_sha256, re.ASCII) is None):
        raise ValueError("malformed launcher capability or intent digest")
    raw = _regular_bytes(LAUNCH_INTENT, mode=0o600)
    intent = base.strict_json_loads(raw.decode("utf-8"))
    if raw != base.canonical_bytes(intent) or base.sha_bytes(raw) != intent_sha256:
        raise ValueError("launcher intent canonical bytes/digest mismatch")
    lock_path = base.GPU_LOCK_DIR / f"{base.sha_bytes(gpu_uuid.encode('ascii'))}.lock"
    lock_st = lock_path.lstat()
    expected = {
        "schema_version": "msae_v3_launcher_intent_v1", "protocol_id": PROTOCOL,
        "socket_path": str(ACTIVE_RUN_ROOT / "broker.sock"),
        "gpu_uuid": gpu_uuid, "gpu_index": gpu_index,
        "lock_path": str(lock_path), "lock_device": lock_st.st_dev,
        "lock_inode": lock_st.st_ino,
        "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
        "authorization_envelope_sha256": base.sha_file(
            ACTIVE_RUN_ROOT / "authorization.json"),
        "launch_capability_sha256": base.sha_bytes(launch_capability.encode("ascii")),
        "launcher_pid": intent.get("launcher_pid"),
        "launcher_start_ticks": intent.get("launcher_start_ticks"),
    }
    if intent != expected or socket_path != expected["socket_path"]:
        raise ValueError("launcher intent exact socket/GPU/lock lineage mismatch")
    launcher_pid = intent.get("launcher_pid")
    launcher_ticks = intent.get("launcher_start_ticks")
    if (type(launcher_pid) is not int or not isinstance(launcher_ticks, str)
            or not launcher_ticks.isdecimal()
            or not _pid_has_start_ticks(launcher_pid, launcher_ticks)):
        raise ValueError("launcher intent process is not live")
    if lease_fd is not None:
        lease_st = os.fstat(lease_fd)
        if (lease_st.st_dev, lease_st.st_ino) != (lock_st.st_dev, lock_st.st_ino):
            raise ValueError("launcher intent does not bind inherited lease FD")
    return intent


def broker(socket_path: str, gpu_uuid: str, gpu_index: int,
           launch_capability: str, intent_sha256: str) -> None:
    _validate_launcher_intent(socket_path, gpu_uuid, gpu_index,
                              launch_capability, intent_sha256)
    log_fd = os.open(ACTIVE_RUN_ROOT / "logs/broker.log",
                     os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    os.fchmod(log_fd, 0o600)
    os.dup2(log_fd, 1); os.dup2(log_fd, 2)
    if log_fd > 2:
        os.close(log_fd)
    broker_pid = os.getpid()
    sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    deadline = time.monotonic() + 15
    while True:
        try:
            sock.connect(socket_path)
            break
        except (FileNotFoundError, ConnectionRefusedError):
            if time.monotonic() >= deadline:
                raise
            time.sleep(0.05)
    _send_json(sock, {"schema_version": "msae_v3_broker_hello_v2", "pid": broker_pid,
                      "start_ticks": base._start_ticks(broker_pid), "sid": os.getsid(0),
                      "pgid": os.getpgrp(), "supervisor_pid": os.getppid(),
                      "supervisor_start_ticks": base._start_ticks(os.getppid())})
    lease_fd = _receive_fd(sock)
    os.set_inheritable(lease_fd, True)
    fcntl.flock(lease_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    _validate_gpu_lock_fd(lease_fd, gpu_uuid)
    _validate_launcher_intent(socket_path, gpu_uuid, gpu_index,
                              launch_capability, intent_sha256, lease_fd)
    gate_r, gate_w = os.pipe()
    ready_r, ready_w = os.pipe()
    final_ack_r, final_ack_w = os.pipe()
    confirmed_r, confirmed_w = os.pipe()
    worker_pid = os.fork()
    if worker_pid == 0:
        os.close(gate_w); os.close(ready_r); os.close(final_ack_w); os.close(confirmed_r)
        try:
            os.setpgid(0, 0)
            install_parent_death_watchdog(broker_pid)
            if os.read(gate_r, 1) != b"G":
                raise RuntimeError("launcher gate missing")
            os.close(gate_r)
            worker_log = os.open(ACTIVE_RUN_ROOT / "logs/worker.log",
                                 os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
            os.fchmod(worker_log, 0o600)
            os.dup2(worker_log, 1); os.dup2(worker_log, 2)
            if worker_log > 2:
                os.close(worker_log)
            environment = worker_environment(
                gpu_uuid, lease_fd, ready_w, final_ack_r, confirmed_w)
            for fd in (ready_w, final_ack_r, confirmed_w):
                os.set_inheritable(fd, True)
            argv = [str(ROOT / ".venv-atlas/bin/python"), "-S", "-B", "-I", str(RUNNER.resolve()),
                    "--run-root", ACTIVE_RUN_REL, "--gpu-uuid", gpu_uuid,
                    "--broker-pid", str(broker_pid), "--readiness-fd", str(ready_w),
                    "--final-ack-fd", str(final_ack_r), "--confirmed-fd", str(confirmed_w)]
            os.execve(argv[0], argv, environment)
        except BaseException as error:
            _technical_failure(f"worker_setup:{type(error).__name__}:{error}", broker_pid, os.getpid())
            os._exit(125)
    worker_started = time.monotonic()
    os.close(gate_r); os.close(ready_w); os.close(final_ack_r); os.close(confirmed_w)
    os.setpgid(worker_pid, worker_pid)
    worker = {"schema_version": "msae_v3_worker_handoff_v2", "broker_pid": broker_pid,
              "broker_start_ticks": base._start_ticks(broker_pid), "worker_pid": worker_pid,
              "worker_start_ticks": base._start_ticks(worker_pid), "worker_pgid": worker_pid,
              "gpu_uuid": gpu_uuid, "gpu_index": gpu_index,
              "launcher_intent_sha256": intent_sha256}
    _send_json(sock, worker)
    sock.settimeout(15)
    if sock.recv(1) != b"G":
        _terminate_group(worker_pid)
        _technical_failure("launcher_handoff_ack_missing", broker_pid, worker_pid)
        raise RuntimeError("launcher acknowledgement missing")
    os.write(gate_w, b"G"); os.close(gate_w)
    ready_deadline = time.monotonic() + 120
    readiness = b""
    os.set_blocking(ready_r, False)
    while time.monotonic() < ready_deadline:
        try:
            readiness += os.read(ready_r, 4096)
        except BlockingIOError:
            pass
        if readiness.endswith(b"\n"):
            break
        pid, status = os.waitpid(worker_pid, os.WNOHANG)
        if pid == worker_pid:
            _technical_failure(f"worker_exit_before_readiness:{status}", broker_pid, worker_pid)
            raise RuntimeError("worker exited before readiness")
        time.sleep(0.05)
    os.close(ready_r)
    if not readiness.endswith(b"\n"):
        _terminate_group(worker_pid)
        _technical_failure("runner_readiness_timeout", broker_pid, worker_pid)
        raise RuntimeError("runner readiness timeout")
    ready = base.strict_json_loads(readiness.decode("utf-8"))
    if ready.get("schema_version") != "msae_v3_runner_ready_v1" or ready.get("worker_pid") != worker_pid:
        _terminate_group(worker_pid)
        raise ValueError("invalid runner readiness")
    _send_json(sock, ready)
    sock.settimeout(30)
    if sock.recv(1) != b"F":
        _terminate_group(worker_pid)
        _technical_failure("launcher_final_model_gate_missing", broker_pid, worker_pid)
        raise RuntimeError("launcher final model gate missing")
    os.write(final_ack_w, b"F"); os.close(final_ack_w)
    os.set_blocking(confirmed_r, False)
    confirmed = b""
    confirmation_deadline = min(worker_started + 6 * 60 * 60, time.monotonic() + 30)
    while time.monotonic() < confirmation_deadline:
        try:
            confirmed += os.read(confirmed_r, 1)
        except BlockingIOError:
            pass
        if confirmed == b"A":
            break
        pid, status = os.waitpid(worker_pid, os.WNOHANG)
        if pid == worker_pid:
            _technical_failure(f"worker_exit_before_model_gate_confirmation:{status}",
                               broker_pid, worker_pid)
            raise RuntimeError("worker exited before confirming model gate")
        time.sleep(0.05)
    os.close(confirmed_r)
    if confirmed != b"A":
        _terminate_group(worker_pid)
        _technical_failure("runner_model_gate_confirmation_timeout", broker_pid, worker_pid)
        raise RuntimeError("runner model-gate confirmation timeout")
    _send_json(sock, {"schema_version": "msae_v3_model_gate_open_v1",
                      "worker_pid": worker_pid, "pre_model": True})
    sock.close()
    while True:
        enforce_live_gpu_lease(lease_fd, gpu_uuid, broker_pid, worker_pid)
        pid, status = os.waitpid(worker_pid, os.WNOHANG)
        if pid == worker_pid:
            enforce_live_gpu_lease(lease_fd, gpu_uuid, broker_pid, worker_pid)
            if not (os.WIFEXITED(status) and os.WEXITSTATUS(status) == 0):
                _technical_failure(f"worker_exit_status:{status}", broker_pid, worker_pid)
            break
        if time.monotonic() - worker_started >= 6 * 60 * 60:
            _terminate_group(worker_pid, grace=60)
            with contextlib.suppress(ChildProcessError):
                os.waitpid(worker_pid, 0)
            _technical_failure("six_hour_timeout", broker_pid, worker_pid)
            raise SystemExit(124)
        time.sleep(1)
    os.close(lease_fd)


def _supervise_broker_process(argv: Sequence[str], environment: Mapping[str, str]) -> int:
    process = subprocess.Popen(list(argv), env=dict(environment))
    received_signal: list[int] = []

    def forward_signal(signum: int, _frame: Any) -> None:
        # The supervisor is the tmux pane process.  It must not disappear and
        # strand a broker/worker when tmux or the launcher terminates it during
        # a failed handoff.  Forward first, then let the ordinary post-wait
        # extinction/terminal path below run in this still-live supervisor.
        received_signal.append(signum)
        with contextlib.suppress(ProcessLookupError):
            process.send_signal(signal.SIGTERM)

    previous_handlers: dict[int, Any] = {}
    for signum in (signal.SIGTERM, signal.SIGHUP):
        previous_handlers[signum] = signal.getsignal(signum)
        signal.signal(signum, forward_signal)
    try:
        while process.poll() is None:
            if received_signal:
                try:
                    returncode = process.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    process.kill()
                    returncode = process.wait(timeout=5)
                break
            time.sleep(0.05)
        else:
            returncode = int(process.returncode)
    finally:
        for signum, handler in previous_handlers.items():
            signal.signal(signum, handler)
    lock_record_path = ACTIVE_RUN_ROOT / "lock_acquired.json"
    if lock_record_path.exists() and not lock_record_path.is_symlink():
        try:
            record_raw = _regular_bytes(lock_record_path, mode=0o644)
            record = base.strict_json_loads(record_raw.decode("utf-8"))
            if record_raw != base.canonical_bytes(record):
                raise ValueError("supervisor lock record is noncanonical")
            worker_pid = int(record["worker_pid"])
            worker_ticks = int(record["worker_start_ticks"])
            worker_pgid = int(record["worker_pgid"])
            if worker_pgid != worker_pid:
                raise ValueError("supervisor lock record has noncanonical worker PGID")
            # The leader may already be dead while grandchildren in its process
            # group survive.  Group membership, not leader liveness, controls
            # whether extinction is still required.
            if _pid_has_start_ticks(worker_pid, worker_ticks) or _group_live_pids(worker_pgid):
                _terminate_group(worker_pgid)
        except BaseException as error:
            _technical_failure(f"supervisor_worker_extinction:{type(error).__name__}:{error}",
                               process.pid, None)
            raise
    if not (ACTIVE_RUN_ROOT / "terminal_success").is_dir() and not (
            ACTIVE_RUN_ROOT / "terminal_failure").is_dir():
        suffix = (f"supervisor_signal:{received_signal[-1]}" if received_signal
                  else f"broker_exit:{returncode}")
        _technical_failure(suffix, process.pid, None)
    return returncode


def supervise_broker(socket_path: str, gpu_uuid: str, gpu_index: int,
                     launch_capability: str, intent_sha256: str) -> None:
    _validate_launcher_intent(socket_path, gpu_uuid, gpu_index,
                              launch_capability, intent_sha256)
    argv = [str(ROOT / ".venv-atlas/bin/python"), "-S", "-B", "-I",
            str(continuation.CONTROLLER_PATH), "broker", "--socket", socket_path,
            "--gpu-uuid", gpu_uuid, "--gpu-index", str(gpu_index),
            "--launch-capability", launch_capability,
            "--intent-sha256", intent_sha256]
    returncode = _supervise_broker_process(argv, FROZEN_BASE_PROCESS_ENVIRONMENT)
    if returncode != 0:
        raise SystemExit(returncode if 0 < returncode < 256 else 125)


def _gpu_rows() -> list[tuple[int, int, str, int]]:
    query = subprocess.check_output(["/usr/bin/nvidia-smi", "--query-gpu=index,uuid,memory.used,utilization.gpu",
                                     "--format=csv,noheader,nounits"], text=True,
                                    env=FROZEN_BASE_PROCESS_ENVIRONMENT)
    processes = subprocess.check_output(["/usr/bin/nvidia-smi", "--query-compute-apps=gpu_uuid,pid",
                                         "--format=csv,noheader,nounits"], text=True,
                                        env=FROZEN_BASE_PROCESS_ENVIRONMENT).strip()
    busy = {line.split(",", 1)[0].strip() for line in processes.splitlines() if line.strip()}
    rows = []
    for line in query.splitlines():
        values = [item.strip() for item in line.split(",")]
        if len(values) != 4:
            raise ValueError("malformed nvidia-smi row")
        index, uuid, memory, utilization = values
        if (re.fullmatch(r"[0-9]+", index, re.ASCII) is None
                or re.fullmatch(r"GPU-[0-9A-Fa-f-]{16,}", uuid, re.ASCII) is None
                or re.fullmatch(r"[0-9]+", memory, re.ASCII) is None
                or re.fullmatch(r"[0-9]+", utilization, re.ASCII) is None):
            raise ValueError("malformed nvidia-smi GPU value")
        if uuid not in busy and int(memory) < 1024 and int(utilization) <= 5:
            rows.append((int(memory), int(utilization), uuid, int(index)))
    return sorted(rows)


def _open_gpu_lock(uuid: str) -> tuple[int, int, Path]:
    commitment = base.read_json(ACTIVE_CONFIG / "authorization_commitment.json")
    binding = base._directory_binding(base.GPU_LOCK_DIR)
    if any(binding[key] != commitment["gpu_lock_directory"][key]
           for key in ("path", "realpath", "device", "inode", "uid", "mode", "nlink")):
        raise ValueError("GPU lock directory drift")
    directory_fd = os.open(base.GPU_LOCK_DIR,
                           os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
    directory_st = os.fstat(directory_fd)
    path_directory_st = base.GPU_LOCK_DIR.lstat()
    expected_directory = commitment["gpu_lock_directory"]
    if ((directory_st.st_dev, directory_st.st_ino) !=
            (path_directory_st.st_dev, path_directory_st.st_ino)
            or (directory_st.st_dev, directory_st.st_ino, directory_st.st_uid,
                stat.S_IMODE(directory_st.st_mode), directory_st.st_nlink) !=
               (expected_directory["device"], expected_directory["inode"], expected_directory["uid"],
                expected_directory["mode"], expected_directory["nlink"])):
        os.close(directory_fd)
        raise ValueError("held GPU lock-directory FD/path/commitment mismatch")
    name = f"{base.sha_bytes(uuid.encode('ascii'))}.lock"
    try:
        try:
            fd = os.open(name, os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC,
                         0o600, dir_fd=directory_fd)
            os.fchmod(fd, 0o600)
        except FileExistsError:
            fd = os.open(name, os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC, dir_fd=directory_fd)
        st = os.fstat(fd)
        if (not stat.S_ISREG(st.st_mode) or stat.S_IMODE(st.st_mode) != 0o600
                or st.st_uid != os.getuid() or st.st_nlink != 1):
            raise ValueError("invalid persistent GPU lock")
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        os.lseek(fd, 0, os.SEEK_SET)
        raw = os.read(fd, 4096)
        expected = base.canonical_bytes({"schema_version": "msae_gpu_uuid_lock_v1", "gpu_uuid": uuid})
        if raw not in (b"", expected):
            raise ValueError("GPU lock payload drift")
        if raw == b"":
            try:
                os.ftruncate(fd, 0)
                os.lseek(fd, 0, os.SEEK_SET)
                _write_all(fd, expected)
                os.ftruncate(fd, len(expected))
                os.fsync(fd)
                os.lseek(fd, 0, os.SEEK_SET)
                if os.read(fd, len(expected) + 1) != expected:
                    raise OSError("GPU lock payload did not reread exactly")
                os.fsync(directory_fd)
            except BaseException:
                # Persistent protocol-independent locks stay retryable rather
                # than being poisoned by a short write or interrupted fsync.
                with contextlib.suppress(OSError):
                    os.ftruncate(fd, 0)
                    os.fsync(fd)
                raise
        st = os.fstat(fd)
        if st.st_size != len(expected):
            raise ValueError("GPU lock payload size drift")
        path = base.GPU_LOCK_DIR / name
        path_st = path.lstat()
        if (st.st_dev, st.st_ino) != (path_st.st_dev, path_st.st_ino):
            raise ValueError("GPU lock FD/path substitution")
        directory_after = os.fstat(directory_fd)
        directory_path_after = base.GPU_LOCK_DIR.lstat()
        if ((directory_st.st_dev, directory_st.st_ino, directory_st.st_mode,
             directory_st.st_uid, directory_st.st_nlink) !=
            (directory_after.st_dev, directory_after.st_ino, directory_after.st_mode,
             directory_after.st_uid, directory_after.st_nlink)
                or (directory_after.st_dev, directory_after.st_ino) !=
                   (directory_path_after.st_dev, directory_path_after.st_ino)):
            raise ValueError("GPU lock directory changed while acquiring lease")
        os.set_inheritable(fd, True)
        return fd, directory_fd, path
    except BaseException:
        with contextlib.suppress(UnboundLocalError, OSError):
            os.close(fd)
        os.close(directory_fd)
        raise


def _pid_has_start_ticks(pid: int, start_ticks: int | str) -> bool:
    if pid <= 1:
        return False
    try:
        raw = (Path("/proc") / str(pid) / "stat").read_text(encoding="ascii")
        right = raw.rfind(")")
        fields = raw[right + 2:].split()
        # Fields after comm start at process-state (field 3); starttime is 22.
        return len(fields) > 19 and fields[0] != "Z" and fields[19] == str(start_ticks)
    except (FileNotFoundError, ProcessLookupError, ValueError):
        return False


def _proc_parent_pid(pid: int) -> int:
    raw = (Path("/proc") / str(pid) / "stat").read_text(encoding="ascii")
    right = raw.rfind(")")
    if right < 0:
        raise ValueError("malformed proc stat comm field")
    fields = raw[right + 2:].split()
    # Fields after comm start with state; the next field is PPID.
    if len(fields) < 2 or not fields[1].isdecimal():
        raise ValueError("malformed proc stat parent field")
    return int(fields[1])


def _verify_failed_handoff_extinction(socket_path: Path, session: str,
                                      identities: Sequence[tuple[int, int]]) -> None:
    for sig in (signal.SIGTERM, signal.SIGKILL):
        for pid, ticks in identities:
            if _pid_has_start_ticks(pid, ticks):
                with contextlib.suppress(ProcessLookupError):
                    os.kill(pid, sig)
        deadline = time.monotonic() + (2 if sig == signal.SIGTERM else 3)
        while time.monotonic() < deadline:
            if not any(_pid_has_start_ticks(pid, ticks) for pid, ticks in identities):
                break
            time.sleep(0.05)
    result = subprocess.run(["/usr/bin/tmux", "-S", str(socket_path), "has-session", "-t", session],
                            check=False, env=FROZEN_BASE_PROCESS_ENVIRONMENT,
                            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    if result.returncode == 0 or any(_pid_has_start_ticks(pid, ticks) for pid, ticks in identities):
        raise RuntimeError("failed handoff left a live tmux/broker process")
    deadline = time.monotonic() + 2
    while (socket_path.exists() or socket_path.is_symlink()) and time.monotonic() < deadline:
        time.sleep(0.05)
    if socket_path.exists() or socket_path.is_symlink():
        raise RuntimeError("failed handoff left the tmux socket path")


def _launch_impl() -> dict[str, Any]:
    verify_candidate_manifest("prelaunch")
    stage = validate_stage_a()
    authorization = verify_authorization(ACTIVE_RUN_ROOT / "authorization.json", consume=False)
    rows = _gpu_rows()
    if not rows:
        raise RuntimeError("no GPU satisfies the frozen idle rule")
    lease_fd = directory_fd = -1
    selected = None
    for memory, utilization, uuid, index in rows:
        try:
            lease_fd, directory_fd, lock_path = _open_gpu_lock(uuid)
            selected = (memory, utilization, uuid, index, lock_path)
            break
        except BlockingIOError:
            continue
    if selected is None:
        raise RuntimeError("all eligible GPU UUID locks are held")
    memory, utilization, uuid, index, lock_path = selected
    try:
        return _launch_with_acquired_gpu(
            memory, utilization, uuid, index, lock_path, lease_fd, directory_fd, authorization)
    finally:
        for fd in (lease_fd, directory_fd):
            if fd >= 0:
                with contextlib.suppress(OSError):
                    os.close(fd)


def _launch_with_acquired_gpu(memory: int, utilization: int, uuid: str, index: int,
                              lock_path: Path, lease_fd: int, directory_fd: int,
                              authorization: Mapping[str, Any]) -> dict[str, Any]:
    if not any(row[2] == uuid and row[3] == index for row in _gpu_rows()):
        raise RuntimeError("GPU no longer idle after UUID lease")
    launch_capability = os.urandom(32).hex()
    lease_st = os.fstat(lease_fd)
    launcher_pid = os.getpid()
    intent = {
        "schema_version": "msae_v3_launcher_intent_v1", "protocol_id": PROTOCOL,
        "socket_path": str(ACTIVE_RUN_ROOT / "broker.sock"),
        "gpu_uuid": uuid, "gpu_index": index, "lock_path": str(lock_path),
        "lock_device": lease_st.st_dev, "lock_inode": lease_st.st_ino,
        "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
        "authorization_envelope_sha256": authorization["envelope_sha256"],
        "launch_capability_sha256": base.sha_bytes(launch_capability.encode("ascii")),
        "launcher_pid": launcher_pid,
        "launcher_start_ticks": base._start_ticks(launcher_pid),
    }
    base.write_once(LAUNCH_INTENT, base.canonical_bytes(intent), 0o600)
    base._fsync_directory(ACTIVE_RUN_ROOT)
    intent_sha256 = base.sha_file(LAUNCH_INTENT)
    logs = ACTIVE_RUN_ROOT / "logs"
    logs.mkdir(mode=0o700); os.chmod(logs, 0o700)
    socket_path = Path(
        f"/tmp/msae_independent_measurement_v3_post_m2_gen3_"
        f"{base.sha_file(ACTIVE_PROV / 'stage_a.json')}.sock")
    if _path_present(socket_path):
        raise ValueError("tmux socket already exists")
    handoff_socket = ACTIVE_RUN_ROOT / "broker.sock"
    session = "msae-independent-v3-gen3-calibration"
    broker_argv = [str(ROOT / ".venv-atlas/bin/python"), "-S", "-B", "-I",
                   str(continuation.CONTROLLER_PATH), "supervise-broker", "--socket", str(handoff_socket),
                   "--gpu-uuid", uuid, "--gpu-index", str(index),
                   "--launch-capability", launch_capability,
                   "--intent-sha256", intent_sha256]
    broker_command = "exec " + shlex.join(broker_argv)
    tmux_started = False
    worker: dict[str, Any] = {}
    hello: dict[str, Any] = {}
    pane_pid = -1
    pane_start_ticks = -1
    connection: socket.socket | None = None
    server: socket.socket | None = None
    try:
        server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        server.bind(str(handoff_socket)); os.chmod(handoff_socket, 0o600)
        server.listen(1); server.settimeout(30)
        subprocess.check_call(["/usr/bin/tmux", "-f", "/dev/null", "-S", str(socket_path),
                               "new-session", "-d", "-s", session,
                               "/usr/bin/bash", "--noprofile", "--norc", "-c", broker_command],
                              env=FROZEN_BASE_PROCESS_ENVIRONMENT)
        tmux_started = True
        # Bind the pane/supervisor before waiting for a broker hello so even a
        # pre-accept timeout has a concrete identity to extinguish and verify.
        pane_pid = int(subprocess.check_output(
            ["/usr/bin/tmux", "-S", str(socket_path), "display-message", "-p",
             "-t", session, "#{pane_pid}"], text=True,
            env=FROZEN_BASE_PROCESS_ENVIRONMENT).strip())
        pane_start_ticks = base._start_ticks(pane_pid)
        connection, _ = server.accept()
        connection.settimeout(15)
        peer_pid, peer_uid, peer_gid = struct.unpack(
            "3i", connection.getsockopt(socket.SOL_SOCKET, socket.SO_PEERCRED,
                                         struct.calcsize("3i")))
        hello = _recv_json(connection)
        if (hello.get("schema_version") != "msae_v3_broker_hello_v2"
                or peer_uid != os.getuid() or peer_gid != os.getgid()
                or peer_pid != int(hello["pid"])
                or _proc_parent_pid(peer_pid) != pane_pid
                or base._start_ticks(int(hello["pid"])) != hello["start_ticks"]
                or hello.get("supervisor_pid") != pane_pid
                or pane_start_ticks != hello.get("supervisor_start_ticks")
                or not _pid_has_start_ticks(pane_pid, pane_start_ticks)):
            raise ValueError("broker identity validation failed")
        connection.sendmsg([b"L"], [(socket.SOL_SOCKET, socket.SCM_RIGHTS,
                                      array.array("i", [lease_fd]))])
        worker = _recv_json(connection)
        if (worker.get("broker_pid") != hello["pid"] or worker.get("gpu_uuid") != uuid
                or worker.get("launcher_intent_sha256") != intent_sha256
                or base._start_ticks(int(worker["worker_pid"])) != worker["worker_start_ticks"]):
            raise ValueError("worker identity validation failed")
        lease_st, path_st = os.fstat(lease_fd), lock_path.lstat()
        dir_st = os.fstat(directory_fd)
        if ((lease_st.st_dev, lease_st.st_ino) != (path_st.st_dev, path_st.st_ino)
                or (dir_st.st_dev, dir_st.st_ino) !=
                   (base.GPU_LOCK_DIR.lstat().st_dev, base.GPU_LOCK_DIR.lstat().st_ino)):
            raise ValueError("GPU lock path/directory drift at handoff")
        lock_record = {"schema_version": "msae_v3_lock_acquired_v2", "protocol_id": PROTOCOL,
                       "gpu_uuid": uuid, "gpu_index": index, "memory_used_mib": memory,
                       "utilization_percent": utilization, "lock_path": str(lock_path),
                       "lock_device": lease_st.st_dev, "lock_inode": lease_st.st_ino,
                       "broker_pid": worker["broker_pid"], "broker_start_ticks": worker["broker_start_ticks"],
                       "worker_pid": worker["worker_pid"], "worker_start_ticks": worker["worker_start_ticks"],
                       "worker_pgid": worker["worker_pgid"], "stage_a_sha256": base.sha_file(ACTIVE_PROV / "stage_a.json"),
                       "authorization_envelope_sha256": authorization["envelope_sha256"],
                       "launcher_intent_sha256": intent_sha256}
        base.install_json(ACTIVE_RUN_ROOT / "lock_acquired.json", lock_record)
        connection.sendall(b"G")
        connection.settimeout(150)
        readiness = _recv_json(connection)
        validate_runner_readiness(readiness, worker, uuid, authorization)
        handoff = {"schema_version": "msae_v3_live_handoff_v3", "status": "live_handoff_no_result_wait",
                   "session": session, "tmux_socket": str(socket_path), "run_root": ACTIVE_RUN_REL,
                   "supervisor_pid": pane_pid, "broker_pid": worker["broker_pid"],
                   "worker_pid": worker["worker_pid"],
                   "gpu_uuid": uuid, "runner_readiness": readiness,
                   "launcher_intent_sha256": intent_sha256,
                   "lock_acquired_sha256": base.sha_file(ACTIVE_RUN_ROOT / "lock_acquired.json")}
        base.install_json(ACTIVE_RUN_ROOT / "handoff.json", handoff)
        base._fsync_directory(ACTIVE_RUN_ROOT)
        connection.sendall(b"F")
        connection.settimeout(30)
        gate_confirmation = _recv_json(connection)
        if (gate_confirmation.get("schema_version") != "msae_v3_model_gate_open_v1"
                or gate_confirmation.get("worker_pid") != worker["worker_pid"]
                or gate_confirmation.get("pre_model") is not True):
            raise ValueError("runner model gate was not confirmed")
        return handoff
    except BaseException as error:
        if worker.get("worker_pgid"):
            with contextlib.suppress(Exception):
                _terminate_group(int(worker["worker_pgid"]))
        if tmux_started:
            subprocess.run(["/usr/bin/tmux", "-S", str(socket_path), "kill-session", "-t", session],
                           check=False, env=FROZEN_BASE_PROCESS_ENVIRONMENT,
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        identities = []
        if hello.get("pid") and hello.get("start_ticks"):
            identities.append((int(hello["pid"]), int(hello["start_ticks"])))
        if pane_pid > 1 and pane_start_ticks >= 0:
            identities.append((pane_pid, pane_start_ticks))
        _verify_failed_handoff_extinction(socket_path, session, identities)
        _technical_failure(f"launcher_or_handoff_failure:{type(error).__name__}:{error}",
                           int(worker.get("broker_pid", hello.get("pid", -1))),
                           int(worker["worker_pid"]) if worker.get("worker_pid") else None)
        raise
    finally:
        if connection is not None:
            connection.close()
        if server is not None:
            server.close()
        with contextlib.suppress(FileNotFoundError):
            handoff_socket.unlink()


def launch() -> dict[str, Any]:
    """Failure-contained outer transition; GPU queries occur only inside it."""
    with quarantine_guard():
        try:
            return _launch_impl()
        except BaseException as error:
            if ACTIVE_RUN_ROOT.is_dir():
                with contextlib.suppress(Exception):
                    _technical_failure(f"launch_transition_failure:{type(error).__name__}:{error}", -1, None)
                with contextlib.suppress(FileNotFoundError):
                    (ACTIVE_RUN_ROOT / "broker.sock").unlink()
            raise


def _pooling_disposition(selected: Any, reconstructed_passes: Sequence[bool]) -> tuple[str, list[str]]:
    pooling_ok = selected is not None and bool(reconstructed_passes) and all(reconstructed_passes)
    return (("eligible", []) if pooling_ok else
            ("ineligible", ["no_registered_tolerance"]) if selected is None else
            ("ineligible", ["unit_batch_selector_failure"]))


def validate_stage_b_typed_qa(run_root: Path, config: Mapping[str, Any],
                              bundle: Mapping[str, Any], selection: Mapping[str, Any]) -> dict[str, str]:
    """Digest- and semantics-check the three QA artifacts before Stage B exists."""
    import numpy as np
    from msae_measurement_remediation_v1 import payload_sha256, select_replay_tolerance
    def load_registered_npy(path: Path, row: Mapping[str, Any]) -> Any:
        if not path.is_relative_to(run_root):
            raise ValueError("registered NPY escapes the run root")
        current = path.parent
        while current != run_root.parent:
            current_st = current.lstat()
            if (not stat.S_ISDIR(current_st.st_mode) or stat.S_ISLNK(current_st.st_mode)
                    or stat.S_IMODE(current_st.st_mode) != 0o700
                    or current_st.st_uid != os.getuid()):
                raise ValueError(f"registered NPY ancestor drift: {current}")
            if current == run_root:
                break
            current = current.parent
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
        try:
            before = os.fstat(fd)
            path_before = path.lstat()
            if ((before.st_dev, before.st_ino) != (path_before.st_dev, path_before.st_ino)
                    or not stat.S_ISREG(before.st_mode) or stat.S_ISLNK(path_before.st_mode)
                    or stat.S_IMODE(before.st_mode) != 0o644 or before.st_uid != os.getuid()
                    or before.st_nlink != 1 or before.st_size != row.get("bytes")):
                raise ValueError(f"registered NPY pre-read identity drift: {path}")
            with os.fdopen(os.dup(fd), "rb") as handle:
                value = np.load(handle, allow_pickle=False)
            os.lseek(fd, 0, os.SEEK_SET)
            digest = hashlib.sha256()
            while True:
                chunk = os.read(fd, 8 << 20)
                if not chunk:
                    break
                digest.update(chunk)
            after = os.fstat(fd)
        finally:
            os.close(fd)
        path_st = path.lstat()
        if ((before.st_dev, before.st_ino, before.st_mode, before.st_uid, before.st_nlink,
             before.st_size, before.st_mtime_ns, before.st_ctime_ns) !=
            (after.st_dev, after.st_ino, after.st_mode, after.st_uid, after.st_nlink,
             after.st_size, after.st_mtime_ns, after.st_ctime_ns)
                or (before.st_dev, before.st_ino) != (path_st.st_dev, path_st.st_ino)
            or not stat.S_ISREG(before.st_mode) or stat.S_ISLNK(path_st.st_mode)
                or digest.hexdigest() != row.get("sha256")):
            raise ValueError(f"registered NPY identity/digest drift: {path}")
        return value
    noop_path = run_root / "cached_noop_hash_replay.json"
    pooling_path = run_root / "canonical_pooling_qa.json"
    alignment_path = run_root / "counterfactual_cache_alignment_qa.json"
    def read_run_json(path: Path) -> Any:
        root_st = run_root.lstat()
        if (not stat.S_ISDIR(root_st.st_mode) or stat.S_ISLNK(root_st.st_mode)
                or stat.S_IMODE(root_st.st_mode) != 0o700 or root_st.st_uid != os.getuid()):
            raise ValueError("Stage-B run-root identity drift")
        raw = _regular_bytes(path, mode=0o644)
        value = base.strict_json_loads(raw.decode("utf-8"))
        if raw != base.canonical_bytes(value):
            raise ValueError(f"noncanonical Stage-B QA JSON: {path}")
        return value
    noop = read_run_json(noop_path)
    pooling = read_run_json(pooling_path)
    alignment = read_run_json(alignment_path)
    replay = config.get("replay", {})
    strata = replay.get("strata")
    if (bundle.get("schema_version") != "msae_calibration_replay_bundle_v1"
            or bundle.get("protocol_config_sha256") !=
               base.sha_bytes(base.canonical_bytes(config))
            or bundle.get("source_role") != replay.get("source_role")
            or bundle.get("source_revision") != replay.get("source_revision")
            or bundle.get("partition") != replay.get("partition")
            or not isinstance(strata, list) or [row.get("stratum_id") for row in strata] !=
               ["main_short", "main_long", "pair_context", "pair_entity"]):
        raise ValueError("Stage-B replay bundle/config global binding drift")
    if noop.get("status") != "eligible" or not isinstance(noop.get("cache_records"), list):
        raise ValueError("cached no-op QA ineligible/malformed")
    observations = bundle.get("observations")
    if not isinstance(observations, Mapping) or set(observations) != {row["stratum_id"] for row in strata}:
        raise ValueError("Stage-B observation stratum set mismatch")
    expected_records: list[tuple[Mapping[str, Any], str, int]] = []
    for meta in strata:
        if (meta.get("source_role") != replay["source_role"]
                or meta.get("source_revision") != replay["source_revision"]
                or meta.get("partition") != replay["partition"]):
            raise ValueError("Stage-B stratum provenance drift")
        ids = [meta["reference_evaluation_id"], *meta["repeat_evaluation_ids"]]
        if len(ids) != 4 or len(set(ids)) != 4 or set(observations[meta["stratum_id"]]) != set(ids):
            raise ValueError("Stage-B evaluation registry mismatch")
        expected_records.extend((meta, evaluation_id, index)
                                for index, evaluation_id in enumerate(ids))
    if len(noop["cache_records"]) != len(expected_records):
        raise ValueError("cached no-op record count mismatch")
    loaded_by_evaluation: dict[tuple[str, str], Any] = {}
    for row, (meta, evaluation_id, index) in zip(noop["cache_records"], expected_records):
        sid = meta["stratum_id"]
        expected_relative = f"{ACTIVE_RUN_REL}/cache/{sid}/forward_{index}.npy"
        if (row.get("stratum_id") != sid or row.get("evaluation_id") != evaluation_id
                or row.get("path") != expected_relative or row.get("dtype") != "float32"
                or row.get("row_ids_sha256") != meta["row_ids_sha256"]
                or row.get("exact_reload") is not True):
            raise ValueError("cached no-op registry field drift")
        path = ROOT / row["path"]
        st = path.lstat()
        if (not stat.S_ISREG(st.st_mode) or stat.S_ISLNK(st.st_mode)
                or st.st_size != row.get("bytes") or base.sha_file(path) != row.get("sha256")):
            raise ValueError("cached no-op digest replay drift")
        values = load_registered_npy(path, row)
        observation = observations[sid][evaluation_id]
        rows = observation.get("row_ids")
        if (values.dtype != np.float32 or list(values.shape) != row.get("shape")
                or not np.array_equal(values, observation.get("values"))
                or not isinstance(rows, list)
                or base.sha_bytes(base.canonical_bytes(rows)) != meta["row_ids_sha256"]
                or payload_sha256(values, rows) != observation.get("payload_sha256")):
            raise ValueError("cached no-op payload/row reconstruction drift")
        loaded_by_evaluation[(sid, evaluation_id)] = values
    generic_config = generic_config_projection(config)
    generic_config_raw = base.canonical_bytes(generic_config)
    generic_config_sha = base.sha_bytes(generic_config_raw)
    recomputed_selection = select_replay_tolerance(
        generic_config_raw, generic_config_sha,
        generic_replay_bundle(bundle, generic_config_sha))
    if dict(selection) != recomputed_selection:
        raise ValueError("tolerance selection does not reproduce")
    selection_path = run_root / "tolerance_selection.json"
    selection_record = read_run_json(selection_path)
    if selection_record != {**dict(selection),
                            "selector_inequality": "2*abs(a-b)<=atol+rtol*max(abs(a),abs(b))",
                            "array_allclose_forbidden": True}:
        raise ValueError("persisted tolerance selection drift")
    selected = selection.get("selected_tolerance")
    pooling_rows = pooling.get("strata")
    if (pooling.get("selected_tolerance") != selected
            or not isinstance(pooling_rows, list) or len(pooling_rows) != 4
            or {row.get("stratum_id") for row in pooling_rows} !=
               {row["stratum_id"] for row in strata}):
        raise ValueError("canonical pooling QA ineligible/malformed")
    pooling_by_sid = {row["stratum_id"]: row for row in pooling_rows}
    reconstructed_passes: list[bool] = []
    for meta in strata:
        sid = meta["stratum_id"]
        row = pooling_by_sid[sid]
        expected_relative = f"{ACTIVE_RUN_REL}/cache/{sid}/pooling_per_unit.npy"
        if row.get("path") != expected_relative:
            raise ValueError("canonical pooling cache path drift")
        path = ROOT / expected_relative
        values = load_registered_npy(path, row)
        reference_observation = observations[sid][meta["reference_evaluation_id"]]
        reference = loaded_by_evaluation[(sid, meta["reference_evaluation_id"])]
        rows = reference_observation["row_ids"]
        aa, bb = reference.astype(np.float64), values.astype(np.float64)
        difference = np.abs(aa - bb)
        if selected is None:
            selector_pass = False
            maximum = float(np.max(difference, initial=0.0))
        else:
            bound = float(selected[0]) + float(selected[1]) * np.maximum(np.abs(aa), np.abs(bb))
            selector_pass = bool(values.dtype == np.float32 and values.shape == reference.shape
                                 and np.isfinite(values).all() and np.isfinite(bound).all()
                                 and np.all(2.0 * difference <= bound))
            maximum = float(np.max(difference, initial=0.0))
        reconstructed_passes.append(selector_pass)
        if (row.get("selector_pass") is not selector_pass
                or row.get("dtype") != "float32" or row.get("shape") != list(values.shape)
                or row.get("bytes") != path.stat().st_size or row.get("sha256") != base.sha_file(path)
                or row.get("row_ids_sha256") != base.sha_bytes(base.canonical_bytes(rows))
                or row.get("reference_payload_sha256") != reference_observation["payload_sha256"]
                or row.get("unit_payload_sha256") != payload_sha256(values, rows)
                or row.get("max_abs") != maximum):
            raise ValueError("canonical pooling payload/selector reconstruction drift")
    expected_pooling_status, expected_pooling_reasons = _pooling_disposition(
        selected, reconstructed_passes)
    if (pooling.get("status") != expected_pooling_status
            or pooling.get("reasons") != expected_pooling_reasons):
        raise ValueError("canonical pooling QA status/reason reconstruction drift")
    frozen = base.read_json(ROOT / "data/msae_independent_measurement_v1/calibration_strata.json")
    source = [base.strict_json_loads(line) for line in
              (ROOT / frozen["source_path"]).read_text(encoding="utf-8").splitlines()]
    pairs = [base.strict_json_loads(line) for line in
             (ROOT / frozen["source_path"]).with_name("pairs.jsonl").read_text(encoding="utf-8").splitlines()]
    expected_alignment = base.counterfactual_alignment_qa(frozen, source, pairs)
    if (alignment != expected_alignment or alignment.get("status") != "eligible"
            or len(alignment.get("pairs", [])) != 16):
        raise ValueError("counterfactual alignment QA semantic/digest drift")
    return {"cached_noop_hash_replay_sha256": base.sha_file(noop_path),
            "canonical_pooling_qa_sha256": base.sha_file(pooling_path),
            "counterfactual_cache_alignment_qa_sha256": base.sha_file(alignment_path)}


def dispatch(argv: Sequence[str]) -> None:
    import argparse
    # The immutable M2 regression suite imports this mutable extension under a
    # deliberately non-canonical module name and requires launch to stay
    # blocked.  Only the controller's canonical import name is an entrypoint.
    if __name__ != "msae_independent_measurement_v3_post_m2_gen3_runtime" and list(argv) == ["launch"]:
        raise RuntimeError("not implemented or prescore-authorized outside canonical controller entrypoint")
    if sys.flags.no_site != 1 or sys.flags.isolated != 1 or sys.flags.dont_write_bytecode != 1:
        raise RuntimeError("post-M2 commands require -S -I -B interpreter isolation")
    parser = argparse.ArgumentParser()
    commands = parser.add_subparsers(dest="command", required=True)
    m3 = commands.add_parser("setup-m3")
    m3.add_argument("--reviewed-m2-sha256", required=True)
    m3.add_argument("--plan-review-sha256", required=True)
    m3.add_argument("--implementation-review-sha256", required=True)
    m4 = commands.add_parser("build-m4")
    m4.add_argument("--post-m3-review-sha256", required=True)
    commands.add_parser("sign")
    commands.add_parser("launch")
    broker_parser = commands.add_parser("broker")
    broker_parser.add_argument("--socket", required=True); broker_parser.add_argument("--gpu-uuid", required=True)
    broker_parser.add_argument("--gpu-index", required=True, type=int)
    broker_parser.add_argument("--launch-capability", required=True)
    broker_parser.add_argument("--intent-sha256", required=True)
    supervisor_parser = commands.add_parser("supervise-broker")
    supervisor_parser.add_argument("--socket", required=True)
    supervisor_parser.add_argument("--gpu-uuid", required=True)
    supervisor_parser.add_argument("--gpu-index", required=True, type=int)
    supervisor_parser.add_argument("--launch-capability", required=True)
    supervisor_parser.add_argument("--intent-sha256", required=True)
    check = commands.add_parser("prescore-check"); check.add_argument("--output-fd", type=int, required=True)
    traced = commands.add_parser("prescore-traced-check"); traced.add_argument("--manifest", type=Path, required=True)
    traced.add_argument("--output", type=Path, required=True); traced.add_argument("--trace", type=Path, required=True)
    verify = commands.add_parser("verify-prescore-trace"); verify.add_argument("--manifest", type=Path, required=True)
    verify.add_argument("--check", type=Path, required=True); verify.add_argument("--trace", type=Path, required=True)
    args = parser.parse_args(list(argv))
    if args.command == "setup-m3":
        with quarantine_guard():
            print(json.dumps(setup_m3(
                args.reviewed_m2_sha256, args.plan_review_sha256,
                args.implementation_review_sha256), indent=2))
    elif args.command == "build-m4":
        print(json.dumps(build_m4(args.post_m3_review_sha256), indent=2))
    elif args.command == "prescore-check":
        with base.quarantine_open_tripwire() as state:
            payload = verify_candidate_manifest("prescore")
            if state["blocked_content_open_attempts"]:
                raise AssertionError("quarantine tripwire recorded an attempted content open")
            _write_all(args.output_fd, base.canonical_bytes(payload)); os.fsync(args.output_fd)
    elif args.command == "prescore-traced-check":
        prescore_traced_check(args.manifest, args.output, args.trace)
    elif args.command == "verify-prescore-trace":
        verify_prescore_trace(args.manifest, args.check, args.trace)
    elif args.command == "sign":
        print(json.dumps(sign_authorization(), indent=2))
    elif args.command == "launch":
        print(json.dumps(launch(), indent=2))
    elif args.command == "broker":
        broker(args.socket, args.gpu_uuid, args.gpu_index,
               args.launch_capability, args.intent_sha256)
    elif args.command == "supervise-broker":
        supervise_broker(args.socket, args.gpu_uuid, args.gpu_index,
                         args.launch_capability, args.intent_sha256)
